import fs from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";
import { dataPaths, SEGMENT_MAX_BYTES, type DataPaths } from "../config.js";
import type { Document, OffsetEntry, OffsetIndex, StoredDocument, WalRecord } from "../types.js";
import { WriteAheadLog } from "./wal.js";

const SEGMENT_PREFIX = "segment-";
const SEGMENT_SUFFIX = ".log";
const LOCK_NAME = ".lock";

export interface StorageDiagnostics {
  documents: number;
  tombstones: number;
  segments: number;
  segmentBytes: number;
  walBytes: number;
  version: number;
}

function segmentName(index: number): string { return `${SEGMENT_PREFIX}${String(index).padStart(4, "0")}${SEGMENT_SUFFIX}`; }

export class Storage {
  private readonly offsetIndex: OffsetIndex = new Map();
  private readonly wal: WriteAheadLog;
  private readonly paths: DataPaths;
  private writeFd = -1;
  private currentSegmentIndex = 0;
  private currentSegmentSize = 0;
  private readonly readFds = new Map<string, number>();
  private version = 0;
  private closed = false;
  private writeBroken = false;
  private readonly plannedDocs = new Map<string, Document>();

  constructor(dataDir?: string) {
    this.paths = dataPaths(dataDir);
    ensureDirs(this.paths);
    acquireLock(this.paths.dataDir);
    let openedWal: WriteAheadLog | undefined;
    try {
      openedWal = new WriteAheadLog(this.paths.walPath);
      this.wal = openedWal;
      this.loadOffsetSnapshot();
      this.replayWal();
      this.closeReadFds();
      this.cleanupOrphans();
      this.openCurrentSegment();
    } catch (error) {
      openedWal?.close();
      for (const fd of this.readFds.values()) fs.closeSync(fd);
      this.readFds.clear();
      releaseLock(this.paths.dataDir);
      throw error;
    }
  }

  private segmentPath(name: string): string { return path.join(this.paths.segmentsDir, name); }

  write(doc: Document): string { return this.writeWithId(randomUUID(), doc); }

  writeWithId(docId: string, doc: Document): string {
    this.assertWritable();
    validateId(docId);
    const plan = this.planRecords([{ id: docId, doc }])[0]!;
    this.plannedDocs.set(docId, doc);
    try {
      this.wal.logPending(plan);
      this.writePlanned([plan]);
      this.wal.logCommitted(plan);
      this.applyWrite(plan);
      this.version++;
    } finally { this.plannedDocs.delete(docId); }
    return docId;
  }

  writeBatch(docs: Document[]): string[] {
    this.assertWritable();
    if (docs.length === 0) return [];
    const inputs = docs.map((doc) => ({ id: randomUUID(), doc }));
    const plans = this.planRecords(inputs);
    for (const input of inputs) this.plannedDocs.set(input.id, input.doc);
    try {
      this.wal.logManyPending(plans);
      this.writePlanned(plans);
      this.wal.logManyCommitted(plans);
      for (const plan of plans) this.applyWrite(plan);
      this.version += plans.length;
      return plans.map((p) => p.docId);
    } finally { for (const input of inputs) this.plannedDocs.delete(input.id); }
  }

  read(docId: string): Document | null {
    const entry = this.offsetIndex.get(docId);
    if (!entry || entry.deleted) return null;
    return this.readAt(entry, docId).doc;
  }

  delete(docId: string): boolean {
    this.assertWritable();
    const entry = this.offsetIndex.get(docId);
    if (!entry || entry.deleted) return false;
    this.wal.logDelete(docId);
    entry.deleted = true;
    this.version++;
    return true;
  }

  liveDocIds(): string[] {
    return [...this.offsetIndex].filter(([, entry]) => !entry.deleted).map(([id]) => id);
  }

  stateVersion(): number { return this.version; }

  size(): number { return this.liveDocIds().length; }

  diagnostics(): StorageDiagnostics {
    let tombstones = 0;
    for (const entry of this.offsetIndex.values()) if (entry.deleted) tombstones++;
    let segmentBytes = 0;
    let segments = 0;
    for (const name of this.segmentNames()) { segments++; segmentBytes += fs.statSync(this.segmentPath(name)).size; }
    return { documents: this.size(), tombstones, segments, segmentBytes, walBytes: fs.statSync(this.paths.walPath).size, version: this.version };
  }

  snapshot(): void {
    const entries: Record<string, OffsetEntry> = {};
    for (const [id, entry] of this.offsetIndex) entries[id] = entry;
    fsyncDir(this.paths.segmentsDir);
    writeJsonAtomic(this.paths.offsetSnapshot, {
      segmentIndex: this.currentSegmentIndex,
      segmentSize: this.currentSegmentSize,
      version: this.version,
      entries,
    });
    this.wal.checkpoint();
    fsyncDir(this.paths.dataDir);
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    if (this.writeFd >= 0) fs.closeSync(this.writeFd);
    for (const fd of this.readFds.values()) fs.closeSync(fd);
    this.readFds.clear();
    this.wal.close();
    releaseLock(this.paths.dataDir);
  }

  reset(): void {
    this.assertWritable();
    // Clear the old WAL against the old snapshot before committing an empty store.
    this.snapshot();
    const index = Math.max(this.currentSegmentIndex, ...this.segmentNames().map(segmentIndexOf)) + 1;
    const fd = fs.openSync(this.segmentPath(segmentName(index)), "wx");
    const version = this.version + 1;
    let committed = false;
    try {
      fs.fsyncSync(fd);
      fsyncDir(this.paths.segmentsDir);
      writeSnapshotAtomic(this.paths.offsetSnapshot, index, 0, version, new Map(), () => { committed = true; });
    } finally {
      if (committed) {
        const oldFd = this.writeFd;
        this.writeFd = fd;
        this.offsetIndex.clear();
        this.currentSegmentIndex = index;
        this.currentSegmentSize = 0;
        this.version = version;
        if (oldFd >= 0) fs.closeSync(oldFd);
        this.closeReadFds();
      } else { fs.closeSync(fd); }
    }
    this.cleanupOrphans();
    fsyncDir(this.paths.segmentsDir);
  }

  compact(): { reclaimedBytes: number; removedDocuments: number } {
    const removedDocuments = [...this.offsetIndex.values()].filter((e) => e.deleted).length;
    if (removedDocuments === 0) return { reclaimedBytes: 0, removedDocuments: 0 };
    const bytesBefore = this.segmentBytes();
    const oldIndex = this.currentSegmentIndex;
    const oldSize = this.currentSegmentSize;
    const oldVersion = this.version;
    const oldEntries = new Map(this.offsetIndex);
    if (this.writeFd >= 0) { fs.fsyncSync(this.writeFd); fs.closeSync(this.writeFd); this.writeFd = -1; }
    this.cleanupOrphans();
    let committed = false;
    let index = oldIndex + 1;
    let fd = -1;
    let size = 0;
    const next: OffsetIndex = new Map();
    try {
      // This checkpoint is the rollback point if the new snapshot never renames.
      this.snapshot();
      fd = fs.openSync(this.segmentPath(segmentName(index)), "wx");
      for (const [docId, entry] of this.offsetIndex) {
        if (entry.deleted) continue;
        const buf = Buffer.from(JSON.stringify(this.readAt(entry, docId)) + "\n", "utf8");
        if (size > 0 && size + buf.length > SEGMENT_MAX_BYTES) {
          fs.fsyncSync(fd); fs.closeSync(fd); index++; size = 0;
          fd = fs.openSync(this.segmentPath(segmentName(index)), "wx");
        }
        writeAll(fd, buf);
        next.set(docId, { segment: segmentName(index), byteOffset: size, length: buf.length - 1, deleted: false, checksum: hash(buf.subarray(0, -1)) });
        size += buf.length;
      }
      fs.fsyncSync(fd); fs.closeSync(fd); fd = -1;
      fsyncDir(this.paths.segmentsDir);
      this.offsetIndex.clear();
      for (const [id, entry] of next) this.offsetIndex.set(id, entry);
      this.currentSegmentIndex = index;
      this.currentSegmentSize = size;
      this.version = oldVersion + 1;
      writeSnapshotAtomic(this.paths.offsetSnapshot, this.currentSegmentIndex, this.currentSegmentSize, this.version, this.offsetIndex, () => { committed = true; });
      this.closeReadFds();
      try { this.cleanupOrphans(); } catch { /* Orphans are safe to reclaim on a later open. */ }
      this.openCurrentSegment();
      return { reclaimedBytes: bytesBefore - this.segmentBytes(), removedDocuments };
    } catch (error) {
      if (fd >= 0) fs.closeSync(fd);
      if (!committed) {
        this.offsetIndex.clear();
        for (const [id, entry] of oldEntries) this.offsetIndex.set(id, entry);
        this.currentSegmentIndex = oldIndex;
        this.currentSegmentSize = oldSize;
        this.version = oldVersion;
        this.closeReadFds();
        fs.truncateSync(this.segmentPath(segmentName(oldIndex)), oldSize);
        this.cleanupOrphans();
        this.openCurrentSegment(false);
      } else if (this.writeFd < 0) {
        this.closeReadFds();
        this.openCurrentSegment(false);
      }
      throw error;
    }
  }

  private planRecords(inputs: Array<{ id: string; doc: Document }>): Array<Omit<WalRecord, "status" | "op">> {
    let index = this.currentSegmentIndex;
    let size = this.currentSegmentSize;
    return inputs.map(({ id, doc }) => {
      const bytes = Buffer.from(JSON.stringify({ id, doc }) + "\n", "utf8");
      if (size > 0 && size + bytes.length > SEGMENT_MAX_BYTES) { index++; size = 0; }
      const plan = { docId: id, segment: segmentName(index), byteOffset: size, length: bytes.length - 1, dataChecksum: hash(bytes.subarray(0, -1)) };
      size += bytes.length;
      return plan;
    });
  }

  private writePlanned(plans: Array<Omit<WalRecord, "status" | "op">>): void {
    const initialIndex = this.currentSegmentIndex;
    const initialSize = this.currentSegmentSize;
    let segment = "";
    let fd = -1;
    try {
      for (const plan of plans) {
        if (plan.segment !== segment) {
          while (this.currentSegmentIndex < segmentIndexOf(plan.segment)) this.rotateSegment();
          fd = this.writeFd; segment = plan.segment;
        }
        const stored = Buffer.from(JSON.stringify({ id: plan.docId, doc: this.readPlannedDoc(plan) }) + "\n", "utf8");
        writeAll(fd, stored);
        this.currentSegmentSize += stored.length;
      }
      if (fd >= 0) fs.fsyncSync(fd);
    } catch (error) {
      if (fd >= 0 && fd !== this.writeFd) {
        try { fs.closeSync(fd); } catch { /* rotateSegment may already have closed it */ }
      }
      try { this.rollbackWrite(initialIndex, initialSize); } catch { this.writeBroken = true; }
      throw error;
    }
  }

  private rollbackWrite(index: number, size: number): void {
    if (this.writeFd >= 0) { fs.closeSync(this.writeFd); this.writeFd = -1; }
    for (const name of this.segmentNames()) if (segmentIndexOf(name) > index) fs.rmSync(this.segmentPath(name), { force: true });
    fs.truncateSync(this.segmentPath(segmentName(index)), size);
    this.currentSegmentIndex = index;
    this.currentSegmentSize = size;
    this.openCurrentSegment(false);
  }

  private assertWritable(): void {
    if (this.closed) throw new Error("storage is closed");
    if (this.writeBroken) throw new Error("storage writer is broken; reopen the store");
  }

  // Plans carry offsets/checksums; the document bytes are kept by the pending write path below.
  private readPlannedDoc(plan: Omit<WalRecord, "status" | "op">): Document {
    const doc = this.plannedDocs.get(plan.docId);
    if (!doc) throw new Error("storage write plan missing document");
    return doc;
  }

  private rotateSegment(): void {
    this.closeReadFds();
    fs.fsyncSync(this.writeFd); fs.closeSync(this.writeFd);
    this.currentSegmentIndex++; this.currentSegmentSize = 0; this.openCurrentSegment();
  }

  private openCurrentSegment(selectHighest = true): void {
    if (selectHighest) {
      const indexes = this.segmentNames().map(segmentIndexOf);
      if (indexes.length > 0) this.currentSegmentIndex = Math.max(this.currentSegmentIndex, ...indexes);
    }
    const p = this.segmentPath(segmentName(this.currentSegmentIndex));
    this.writeFd = fs.openSync(p, "a");
    this.currentSegmentSize = fs.statSync(p).size;
  }

  private applyWrite(r: Omit<WalRecord, "status" | "op">): void {
    this.offsetIndex.set(r.docId, { segment: r.segment, byteOffset: r.byteOffset, length: r.length, deleted: false, checksum: r.dataChecksum });
  }

  private readAt(entry: OffsetEntry, expectedId?: string): StoredDocument {
    const fd = this.getReadFd(entry.segment);
    const buf = readExact(fd, entry.byteOffset, entry.length);
    if (buf.length === 0) throw new Error("storage record is empty");
    if (entry.checksum && hash(buf) !== entry.checksum) throw new Error("storage record checksum mismatch");
    const parsed = JSON.parse(buf.toString("utf8")) as StoredDocument;
    if (parsed.id === undefined || typeof parsed.id !== "string" || typeof parsed.doc !== "object" || parsed.doc === null) throw new Error("storage record is invalid");
    if (expectedId !== undefined && parsed.id !== expectedId) throw new Error("storage record id mismatch");
    return parsed;
  }

  private getReadFd(segment: string): number {
    let fd = this.readFds.get(segment);
    if (fd === undefined) { fd = fs.openSync(this.segmentPath(segment), "r"); this.readFds.set(segment, fd); }
    return fd;
  }

  private loadOffsetSnapshot(): void {
    if (!fs.existsSync(this.paths.offsetSnapshot)) return;
    const raw = fs.readFileSync(this.paths.offsetSnapshot, "utf8");
    if (!raw.trim()) return;
    try {
      const parsed = JSON.parse(raw) as { segmentIndex: number; segmentSize: number; version?: number; entries: Record<string, OffsetEntry> };
      if (!Number.isSafeInteger(parsed.segmentIndex) || !Number.isSafeInteger(parsed.segmentSize) || typeof parsed.entries !== "object" || parsed.entries === null) throw new Error();
      for (const [id, entry] of Object.entries(parsed.entries)) {
        validateEntry(id, entry);
        this.offsetIndex.set(id, entry);
      }
      this.currentSegmentIndex = parsed.segmentIndex; this.currentSegmentSize = parsed.segmentSize; this.version = parsed.version ?? 0;
    } catch { throw new Error("offset snapshot is invalid"); }
  }

  private replayWal(): void {
    const records = this.wal.readAll();
    const committed = new Set(records.filter((r) => r.op === "write" && r.status === "committed").map(walKey));
    for (const record of records) {
      if (record.op === "delete" && record.status === "committed") {
        const entry = this.offsetIndex.get(record.docId); if (entry) { entry.deleted = true; this.version++; }
      } else if (record.op === "write") {
        const valid = this.verifySegmentRecord(record);
        if (record.status === "committed") {
          if (!valid) throw new Error("committed WAL record is corrupt");
          this.applyWrite(record); this.version++;
        } else if (!committed.has(walKey(record)) && valid) {
          this.applyWrite(record); this.version++;
        }
      }
    }
    this.snapshot();
  }

  private verifySegmentRecord(r: WalRecord): boolean {
    if (!/^segment-\d+\.log$/.test(r.segment)) return false;
    const p = this.segmentPath(r.segment);
    if (!fs.existsSync(p) || fs.statSync(p).size < r.byteOffset + r.length + 1) return false;
    try {
      const buf = readExact(this.getReadFd(r.segment), r.byteOffset, r.length);
      if (r.dataChecksum && hash(buf) !== r.dataChecksum) return false;
      const parsed = JSON.parse(buf.toString("utf8")) as StoredDocument;
      return parsed.id === r.docId && readExact(this.getReadFd(r.segment), r.byteOffset + r.length, 1)[0] === 10;
    } catch { return false; }
  }

  private segmentNames(): string[] { return fs.readdirSync(this.paths.segmentsDir).filter((n) => /^segment-\d+\.log$/.test(n)); }
  private segmentBytes(): number { return this.segmentNames().reduce((n, name) => n + fs.statSync(this.segmentPath(name)).size, 0); }

  private cleanupOrphans(): void {
    const keep = new Set([...this.offsetIndex.values()].map((e) => e.segment));
    keep.add(segmentName(this.currentSegmentIndex));
    for (const name of this.segmentNames()) if (!keep.has(name)) fs.rmSync(this.segmentPath(name), { force: true });
  }

  private closeReadFds(): void {
    for (const fd of this.readFds.values()) fs.closeSync(fd);
    this.readFds.clear();
  }
}

function ensureDirs(paths: DataPaths): void { for (const dir of [paths.dataDir, paths.segmentsDir, paths.indexDir]) fs.mkdirSync(dir, { recursive: true }); }

function acquireLock(dataDir: string): void {
  const lock = path.join(dataDir, LOCK_NAME);
  const claim = (): void => { fs.mkdirSync(lock); fs.writeFileSync(path.join(lock, "pid"), String(process.pid)); fsyncDir(dataDir); };
  try { claim(); return; } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw new Error("unable to acquire storage lock");
  }
  const guard = path.join(dataDir, ".lock-reclaim");
  try { fs.mkdirSync(guard); } catch {
    throw new Error("storage lock reclamation is guarded; if no writer is active, remove .lock-reclaim manually");
  }
  try {
    // Read the current owner only while reclamation is serialized.
    let pidText: string;
    try { pidText = fs.readFileSync(path.join(lock, "pid"), "utf8").trim(); } catch { throw new Error("storage data directory is already locked"); }
    const pid = Number(pidText);
    if (!/^\d+$/.test(pidText) || !Number.isSafeInteger(pid) || pid <= 0) throw new Error("storage data directory is already locked");
    try { process.kill(pid, 0); } catch (stale) {
      if ((stale as NodeJS.ErrnoException).code !== "ESRCH") throw new Error("storage data directory is already locked");
      fs.rmSync(lock, { recursive: true });
      try { claim(); return; } catch { throw new Error("storage data directory is already locked"); }
    }
    throw new Error("storage data directory is already locked");
  } finally { fs.rmSync(guard, { recursive: true }); }
}

function releaseLock(dataDir: string): void { fs.rmSync(path.join(dataDir, LOCK_NAME), { recursive: true, force: true }); }
function validateId(id: string): void { if (!id || id.includes("\n") || id.length > 1024) throw new Error("invalid document id"); }
function validateEntry(id: string, e: OffsetEntry): void { validateId(id); if (!/^segment-\d+\.log$/.test(e.segment) || !Number.isSafeInteger(e.byteOffset) || e.byteOffset < 0 || !Number.isSafeInteger(e.length) || e.length < 0 || typeof e.deleted !== "boolean" || (e.checksum !== undefined && !/^[a-f0-9]{64}$/.test(e.checksum))) throw new Error("invalid offset entry"); }
function segmentIndexOf(segment: string): number { return Number.parseInt(/^segment-(\d+)\.log$/.exec(segment)?.[1] ?? "-1", 10); }
function hash(value: Buffer): string { return createHash("sha256").update(value).digest("hex"); }
function readExact(fd: number, offset: number, length: number): Buffer { const out = Buffer.alloc(length); let at = 0; while (at < length) { const n = fs.readSync(fd, out, at, length - at, offset + at); if (n === 0) throw new Error("short storage read"); at += n; } return out; }
function writeAll(fd: number, buffer: Buffer): void { let at = 0; while (at < buffer.length) { const n = fs.writeSync(fd, buffer, at, buffer.length - at); if (n <= 0) throw new Error("storage write made no progress"); at += n; } }
function walKey(r: WalRecord): string { return `${r.docId}:${r.segment}:${r.byteOffset}`; }
function writeSnapshotAtomic(target: string, segmentIndex: number, segmentSize: number, version: number, entries: OffsetIndex, onRename: () => void): void {
  const serialized: Record<string, OffsetEntry> = {};
  for (const [id, entry] of entries) serialized[id] = entry;
  const tmp = target + ".tmp";
  const fd = fs.openSync(tmp, "w");
  try { writeAll(fd, Buffer.from(JSON.stringify({ segmentIndex, segmentSize, version, entries: serialized }), "utf8")); fs.fsyncSync(fd); }
  finally { fs.closeSync(fd); }
  try { fs.renameSync(tmp, target); }
  catch (error) {
    // A wrapper or filesystem can report failure after rename completed.
    if (!fs.existsSync(tmp) && fs.existsSync(target)) onRename();
    throw error;
  }
  onRename();
  fsyncDir(path.dirname(target));
}
function fsyncDir(dir: string): void { const fd = fs.openSync(dir, "r"); try { fs.fsyncSync(fd); } finally { fs.closeSync(fd); } }
function writeJsonAtomic(target: string, value: unknown): void { const tmp = `${target}.tmp`; const fd = fs.openSync(tmp, "w"); try { writeAll(fd, Buffer.from(JSON.stringify(value), "utf8")); fs.fsyncSync(fd); } finally { fs.closeSync(fd); } fs.renameSync(tmp, target); fsyncDir(path.dirname(target)); }

import fs from "node:fs";
import { createHash } from "node:crypto";
import type { WalRecord } from "../types.js";

function recordChecksum(record: Omit<WalRecord, "checksum">): string {
  return createHash("sha256").update(JSON.stringify(record)).digest("hex");
}

function withChecksum(record: Omit<WalRecord, "checksum">): WalRecord {
  return { ...record, checksum: recordChecksum(record) };
}

export class WriteAheadLog {
  private fd: number;
  private broken = false;

  constructor(private readonly path: string) { this.fd = fs.openSync(path, "a"); }

  private append(record: Omit<WalRecord, "checksum">): void { this.appendMany([record]); }

  private appendMany(records: Omit<WalRecord, "checksum">[]): void {
    if (this.broken) throw new Error("WAL writer is broken; checkpoint or reopen the store");
    if (records.length === 0) return;
    const blob = records.map((r) => JSON.stringify(withChecksum(r)) + "\n").join("");
    try {
      writeAll(this.fd, Buffer.from(blob, "utf8"));
      fs.fsyncSync(this.fd);
    } catch (error) { this.broken = true; throw error; }
  }

  logPending(record: Omit<WalRecord, "status" | "op">): void {
    const { checksum: ignored, ...base } = record;
    this.append({ ...base, op: "write", status: "pending" });
  }

  logCommitted(record: Omit<WalRecord, "status" | "op">): void {
    const { checksum: ignored, ...base } = record;
    this.append({ ...base, op: "write", status: "committed" });
  }

  logManyPending(records: Omit<WalRecord, "status" | "op">[]): void {
    this.appendMany(records.map(({ checksum: ignored, ...r }) => ({ ...r, op: "write", status: "pending" })));
  }

  logManyCommitted(records: Omit<WalRecord, "status" | "op">[]): void {
    this.appendMany(records.map(({ checksum: ignored, ...r }) => ({ ...r, op: "write", status: "committed" })));
  }

  logDelete(docId: string): void {
    this.append({ op: "delete", docId, segment: "", byteOffset: 0, length: 0, status: "committed" });
  }

  readAll(): WalRecord[] {
    if (!fs.existsSync(this.path)) return [];
    const raw = fs.readFileSync(this.path, "utf8");
    const lines = raw.split("\n");
    const records: WalRecord[] = [];
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!;
      if (!line) continue;
      let value: unknown;
      try { value = JSON.parse(line); } catch {
        if (i === lines.length - 1 && !raw.endsWith("\n")) break;
        throw new Error("WAL contains malformed record");
      }
      if (!isWalRecord(value)) throw new Error("WAL contains invalid record");
      if (value.checksum !== undefined) {
        const { checksum: ignored, ...withoutChecksum } = value;
        if (recordChecksum(withoutChecksum) !== value.checksum) throw new Error("WAL checksum mismatch");
      }
      records.push(value);
    }
    return records;
  }

  checkpoint(): void {
    if (this.fd >= 0) { fs.closeSync(this.fd); this.fd = -1; }
    try {
      const fd = fs.openSync(this.path, "w");
      try { fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
      this.fd = fs.openSync(this.path, "a");
      this.broken = false;
    } catch (error) {
      this.broken = true;
      if (this.fd >= 0) { fs.closeSync(this.fd); this.fd = -1; }
      try { this.fd = fs.openSync(this.path, "a"); } catch { /* close() remains safe after an unrecoverable checkpoint error */ }
      throw error;
    }
  }

  close(): void {
    if (this.fd >= 0) { fs.closeSync(this.fd); this.fd = -1; }
  }
}

function writeAll(fd: number, buffer: Buffer): void {
  let offset = 0;
  while (offset < buffer.length) {
    const written = fs.writeSync(fd, buffer, offset, buffer.length - offset);
    if (written <= 0) throw new Error("storage write made no progress");
    offset += written;
  }
}

function isWalRecord(value: unknown): value is WalRecord {
  if (typeof value !== "object" || value === null) return false;
  const r = value as Record<string, unknown>;
  return (r.op === "write" || r.op === "delete") && typeof r.docId === "string" &&
    typeof r.segment === "string" && Number.isSafeInteger(r.byteOffset) && (r.byteOffset as number) >= 0 &&
    Number.isSafeInteger(r.length) && (r.length as number) >= 0 &&
    (r.status === "pending" || r.status === "committed") &&
    (r.checksum === undefined || (typeof r.checksum === "string" && /^[a-f0-9]{64}$/.test(r.checksum))) &&
    (r.dataChecksum === undefined || (typeof r.dataChecksum === "string" && /^[a-f0-9]{64}$/.test(r.dataChecksum)));
}

import fs from "node:fs";
import { createHash } from "node:crypto";
import { tokenizeDetailed, type TokenInfo } from "./tokenizer.js";
import type { PostingList, Posting } from "../types.js";

export class InvertedIndexStore {
  private readonly index = new Map<string, { data: Uint32Array; size: number }>();
  private readonly ids: string[] = [];
  private readonly numbers = new Map<string, number>();
  private readonly freeNumbers: number[] = [];
  /** term -> number of distinct docs containing it (BM25 IDF input). */
  private readonly docFreq = new Map<string, number>();
  /** docId -> its length in tokens (BM25 length normalization input). */
  private readonly docLengths = new Map<string, number>();
  /** docId -> the distinct terms it contributed, so delete touches only those. */
  private readonly docTerms = new Map<string, string[]>();
  // shortcut: removed interned terms remain until rebuild/restart; prune if sustained vocabulary churn requires it.
  private readonly termIds = new Map<string, number>();
  private readonly interned: string[] = [];
  private intern(term: string): number {
    let id = this.termIds.get(term);
    if (id === undefined) { id = this.interned.length; this.interned.push(term); this.termIds.set(term, id); }
    return id;
  }
  private packedFrequencies(tokens: TokenInfo[]): PackedFrequencies {
    return new PackedFrequencies(tokens.map(t => this.intern(t.term)), this.termIds);
  }
  private totalTokens = 0;
  private dictionary: string[] | undefined;
  private readonly typoDictionary = new Map<string, Set<string>>();
  private readonly fields = new Map<string, IndexedField[]>();
  private readonly fieldTotals = new Map<
    string,
    { length: number; count: number }
  >();

  indexedFields(id: string): IndexedField[] {
    return this.fields.get(id) ?? [];
  }
  averageFieldLength(field: string): number {
    const stats = this.fieldTotals.get(field);
    return stats ? stats.length / stats.count : 1;
  }
  setFields(
    id: string,
    values: Array<{ field: string; text: string; tokens?: TokenInfo[] }>,
  ): void {
    this.removeFields(id);
    const fields = values.map(
      ({ field, text, tokens = tokenizeDetailed(text, field) }) => {
        const length = tokens.length
          ? tokens[tokens.length - 1]!.position + 1
          : 0;
        const windows: TokenWindow[] = [];
        const main = !["title", "path", "repo"].includes(field);
        let first = 0,
          last = 0;
        for (let start = 0; start < length; start += main ? 90 : length) {
          while (first < tokens.length && tokens[first]!.position < start)
            first++;
          while (
            last < tokens.length &&
            tokens[last]!.position < start + (main ? 120 : length)
          )
            last++;
          const local = tokens.slice(first, last);
          if (local.length)
            windows.push({
              start: local[0]!.start,
              end: local[local.length - 1]!.end,
              length: Math.min(main ? 120 : length, length - start),
              tf: this.packedFrequencies(local),
            });
          if (!main || start + 120 >= length) break;
        }
        const stats = this.fieldTotals.get(field) ?? { length: 0, count: 0 };
        for (const window of windows) {
          stats.length += window.length;
          stats.count++;
        }
        this.fieldTotals.set(field, stats);
        const packed = new Uint32Array(tokens.length * 4);
        tokens.forEach((t, i) => packed.set([this.intern(t.term), t.position, t.start, t.end], i * 4));
        const words = this.interned;
        return { field, length, tf: this.packedFrequencies(tokens), windows,
          packedBytes: packed.byteLength,
          get tokens(): Array<Omit<TokenInfo, "original">> {
            return Array.from({ length: packed.length / 4 }, (_, i) => ({ term: words[packed[i * 4]!]!, position: packed[i * 4 + 1]!, start: packed[i * 4 + 2]!, end: packed[i * 4 + 3]!, field }));
          }
        };
      },
    );
    this.fields.set(id, fields);
  }
  private removeFields(id: string): void {
    for (const field of this.fields.get(id) ?? []) {
      const stats = this.fieldTotals.get(field.field)!;
      for (const window of field.windows) {
        stats.length -= window.length;
        stats.count--;
      }
      if (!stats.count) this.fieldTotals.delete(field.field);
    }
    this.fields.delete(id);
  }
  prefix(prefix: string, limit = 20): string[] {
    const words = this.terms();
    let lo = 0,
      hi = words.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (words[mid]! < prefix) lo = mid + 1;
      else hi = mid;
    }
    const out: string[] = [];
    while (
      lo < words.length &&
      out.length < limit &&
      words[lo]!.startsWith(prefix)
    )
      out.push(words[lo++]!);
    return out;
  }
  private addTypoTerm(term: string): void {
    if (term.length > 64) return;
    for (const key of deletions(term)) {
      const bucket = this.typoDictionary.get(key) ?? new Set<string>();
      bucket.add(term);
      this.typoDictionary.set(key, bucket);
    }
  }
  typos(term: string, limit = 20): string[] {
    if (term.length < 3 || term.length > 64) return [];
    // shortcut: typos use terms up to 64 UTF-16 units and 2048 checks, raise only with measured recall needs.
    const out = new Set<string>();
    let work = 0;
    for (const key of deletions(term))
      for (const word of this.typoDictionary.get(key) ?? []) {
        if (++work > 2048) return [...out];
        if (oneEdit(term, word)) out.add(word);
        if (out.size >= limit) return [...out];
      }
    return [...out];
  }

  addDocument(docId: string, tokens: string[]): void {
    this.dictionary = undefined;
    if (this.docLengths.has(docId)) this.removeDocument(docId);

    const tf = new Map<string, number>();
    for (const token of tokens) {
      tf.set(token, (tf.get(token) ?? 0) + 1);
    }

    let number = this.numbers.get(docId);
    if (number === undefined) { number = this.freeNumbers.pop() ?? this.ids.length; this.ids[number] = docId; this.numbers.set(docId, number); }
    for (const [term, freq] of tf) {
      let list = this.index.get(term);
      if (list === undefined) {
        list = { data: new Uint32Array(8), size: 0 };
        this.index.set(term, list);
        this.addTypoTerm(term);
      }
      if (list.size * 2 === list.data.length) {
        const next = new Uint32Array(list.data.length * 2); next.set(list.data); list.data = next;
      }
      list.data[list.size * 2] = number;
      list.data[list.size * 2 + 1] = freq;
      list.size++;
      this.docFreq.set(term, (this.docFreq.get(term) ?? 0) + 1);
    }

    this.docLengths.set(docId, tokens.length);
    this.docTerms.set(docId, [...tf.keys()]);
    this.totalTokens += tokens.length;
  }

  clear(): void {
    this.termIds.clear();
    this.interned.length = 0;
    this.freeNumbers.length = 0;
    this.ids.length = 0;
    this.numbers.clear();
    this.fields.clear();
    this.fieldTotals.clear();
    this.dictionary = undefined;
    this.typoDictionary.clear();
    this.index.clear();
    this.docFreq.clear();
    this.docLengths.clear();
    this.docTerms.clear();
    this.totalTokens = 0;
  }

  /** Strip a document from its own terms' posting lists. Needed for delete/update. */
  removeDocument(docId: string): void {
    this.removeFields(docId);
    this.dictionary = undefined;
    const length = this.docLengths.get(docId);
    if (length === undefined) return;

    for (const term of this.docTerms.get(docId) ?? []) {
      const list = this.index.get(term);
      if (list === undefined) continue;
      const number = this.numbers.get(docId);
      let size = 0;
      for (let i = 0; i < list.size; i++) if (list.data[i * 2] !== number) {
        list.data[size * 2] = list.data[i * 2]!;
        list.data[size * 2 + 1] = list.data[i * 2 + 1]!; size++;
      }
      list.size = size;
      if (size === 0) {
        this.index.delete(term);
        if (term.length <= 64)
          for (const key of deletions(term)) {
            const bucket = this.typoDictionary.get(key);
            bucket?.delete(term);
            if (!bucket?.size) this.typoDictionary.delete(key);
          }
        this.docFreq.delete(term);
      } else {
        this.docFreq.set(term, size);
      }
    }

    const number = this.numbers.get(docId);
    if (number !== undefined) { this.ids[number] = ""; this.freeNumbers.push(number); this.numbers.delete(docId); }
    this.docLengths.delete(docId);
    this.docTerms.delete(docId);
    this.totalTokens -= length;
  }

  *postingEntries(term: string): IterableIterator<Posting> {
    const list = this.index.get(term);
    if (!list) return;
    for (let i = 0; i < list.size; i++) yield { docId: this.ids[list.data[i * 2]!]!, termFrequency: list.data[i * 2 + 1]! };
  }
  postings(term: string): PostingList { return [...this.postingEntries(term)]; }

  postingMemory() {
    let packedBytes = 0, postingCount = 0;
    for (const list of this.index.values()) { packedBytes += list.data.byteLength; postingCount += list.size; }
    let tokenBytes = 0, frequencyBytes = 0;
    for (const fields of this.fields.values()) for (const f of fields) { tokenBytes += f.packedBytes ?? 0; frequencyBytes += f.tf.byteLength; for (const w of f.windows) frequencyBytes += w.tf.byteLength; }
    return { packedBytes, tokenBytes, frequencyBytes, postingCount, objectEstimateBytes: postingCount * 48 };
  }

  terms(): string[] {
    return (this.dictionary ??= [...this.index.keys()].sort());
  }

  /** How many documents contain a term (n(qi) in BM25's IDF). */
  documentFrequency(term: string): number {
    return this.docFreq.get(term) ?? 0;
  }

  /** Length in tokens of a specific document (|D| in BM25). */
  documentLength(docId: string): number {
    return this.docLengths.get(docId) ?? 0;
  }

  /** Total number of indexed documents (N in BM25). */
  hasDocument(id: string): boolean {
    return this.docLengths.has(id);
  }

  documentCount(): number {
    return this.docLengths.size;
  }

  /** Average document length across the corpus (avgdl in BM25). */
  averageDocumentLength(): number {
    const n = this.docLengths.size;
    return n === 0 ? 0 : this.totalTokens / n;
  }

  snapshot(filePath: string, version: number): void {
    const payload = {
      formatVersion: 4,
      ids: this.ids,
      version,
      index: Object.fromEntries([...this.index].map(([term, list]) => [term, Array.from(list.data.subarray(0, list.size * 2))])),
      docFreq: Object.fromEntries(this.docFreq),
      docLengths: Object.fromEntries(this.docLengths),
      totalTokens: this.totalTokens,
    };
    const checksum = createHash("sha256")
      .update(JSON.stringify(payload))
      .digest("hex");
    const tmp = `${filePath}.tmp`;
    const fd = fs.openSync(tmp, "w");
    try {
      fs.writeFileSync(fd, JSON.stringify({ ...payload, checksum }));
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
    fs.renameSync(tmp, filePath);
  }

  /** Load a snapshot. Returns the storage version it was built at, or null if none. */
  load(filePath: string): number | null {
    if (!fs.existsSync(filePath)) return null;
    const raw = fs.readFileSync(filePath, "utf8");
    if (raw.trim().length === 0) return null;

    const payload = JSON.parse(raw) as {
      checksum?: string;
      formatVersion?: number;
      version?: number;
      ids?: string[];
      index: Record<string, PostingList | number[]>;
      docFreq: Record<string, number>;
      docLengths: Record<string, number>;
      totalTokens: number;
    };
    if (payload.formatVersion !== 3 && payload.formatVersion !== 4) return null;
    const { checksum, ...body } = payload;
    if (checksum !== createHash("sha256").update(JSON.stringify(body)).digest("hex"))
      throw new Error("index cache checksum mismatch");
    if (!Number.isSafeInteger(payload.version) || !payload.index || !payload.docLengths || !payload.docFreq || !Number.isSafeInteger(payload.totalTokens) || payload.totalTokens < 0)
      throw new Error("invalid index cache");
    const lengths = Object.values(payload.docLengths);
    if (lengths.some(n => !Number.isSafeInteger(n) || n < 0) || lengths.reduce((a,b) => a+b,0) !== payload.totalTokens)
      throw new Error("invalid index lengths");
    const docIds = payload.formatVersion === 4 ? payload.ids : Object.keys(payload.docLengths);
    if (!Array.isArray(docIds) || docIds.some(id => typeof id !== "string")) throw new Error("invalid document ids");
    const numbers = new Map<string, number>();
    docIds.forEach((id, i) => {
      if (!id) return;
      if (numbers.has(id) || !Object.hasOwn(payload.docLengths, id)) throw new Error("invalid document ids");
      numbers.set(id, i);
    });
    if (numbers.size !== lengths.length) throw new Error("invalid document ids");
    const sums = new Map<string, number>();
    const packed = new Map<string, {data:Uint32Array;size:number}>();
    for (const [term, list] of Object.entries(payload.index)) {
      if (!term || !Array.isArray(list) || !list.length) throw new Error("invalid postings");
      const size = payload.formatVersion === 4 ? list.length / 2 : list.length;
      if (!Number.isInteger(size) || payload.docFreq[term] !== size) throw new Error("invalid postings");
      const data = new Uint32Array(size * 2), seen = new Set<string>();
      for (let i = 0; i < size; i++) {
        const p = list[i] as Posting;
        const number = payload.formatVersion === 4 ? (list[i * 2] as number) : numbers.get(p?.docId);
        const frequency = payload.formatVersion === 4 ? list[i * 2 + 1] as number : p?.termFrequency;
        const id = number === undefined ? undefined : docIds[number];
        if (!Number.isSafeInteger(number) || number! < 0 || !id || seen.has(id) || !Number.isSafeInteger(frequency) || frequency <= 0 || frequency > 0xffffffff)
          throw new Error("invalid posting");
        seen.add(id); sums.set(id, (sums.get(id) ?? 0) + frequency);
        data[i * 2] = number!; data[i * 2 + 1] = frequency;
      }
      packed.set(term, {data,size});
    }
    for (const [id, length] of Object.entries(payload.docLengths)) if ((sums.get(id) ?? 0) !== length) throw new Error("invalid posting total");
    if (Object.keys(payload.docFreq).length !== packed.size) throw new Error("invalid frequencies");
    this.clear();
    docIds.forEach((id,i) => { this.ids.push(id); if (id) this.numbers.set(id,i); else this.freeNumbers.push(i); });
    for (const [term, list] of packed) { this.index.set(term,list); this.addTypoTerm(term); }
    for (const [term,n] of Object.entries(payload.docFreq)) this.docFreq.set(term,n);
    for (const [id,len] of Object.entries(payload.docLengths)) this.docLengths.set(id,len);
    this.totalTokens = payload.totalTokens;
    for (const term of this.index.keys()) for (const p of this.postingEntries(term)) {
      const terms = this.docTerms.get(p.docId) ?? [];
      terms.push(term); this.docTerms.set(p.docId,terms);
    }

    return payload.version ?? -1;
  }
}

export interface TokenWindow {
  start: number;
  end: number;
  length: number;
  tf: PackedFrequencies;
}
export interface IndexedField {
  field: string;
  length: number;
  tokens: Array<Omit<TokenInfo, "original">>;
  packedBytes?: number;
  tf: PackedFrequencies;
  windows: TokenWindow[];
}
class PackedFrequencies {
  private readonly data: Uint32Array;
  constructor(ids: number[], private readonly terms: Map<string, number>) {
    const counts = new Map<number, number>();
    for (const id of ids) counts.set(id, (counts.get(id) ?? 0) + 1);
    this.data = new Uint32Array([...counts].sort((a, b) => a[0] - b[0]).flat());
  }
  get byteLength(): number { return this.data.byteLength; }
  get(term: string): number | undefined {
    const id = this.terms.get(term);
    if (id === undefined) return undefined;
    let lo = 0, hi = this.data.length / 2;
    while (lo < hi) { const mid = (lo + hi) >>> 1; if (this.data[mid * 2]! < id) lo = mid + 1; else hi = mid; }
    return this.data[lo * 2] === id ? this.data[lo * 2 + 1] : undefined;
  }
  has(term: string): boolean { return this.get(term) !== undefined; }
}
function deletions(word: string): Set<string> {
  const keys = new Set([word]);
  for (let i = 0; i < word.length; i++)
    keys.add(word.slice(0, i) + word.slice(i + 1));
  return keys;
}
function oneEdit(a: string, b: string): boolean {
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0,
    j = 0,
    edits = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i++;
      j++;
      continue;
    }
    if (++edits > 1) return false;
    if (a.length >= b.length) i++;
    if (b.length >= a.length) j++;
  }
  return edits + (a.length - i) + (b.length - j) <= 1;
}

const STOPWORDS = new Set([
  "the",
  "a",
  "an",
  "and",
  "or",
  "but",
  "if",
  "of",
  "at",
  "by",
  "for",
  "with",
  "about",
  "to",
  "from",
  "in",
  "on",
  "is",
  "are",
  "was",
  "were",
  "be",
  "been",
  "being",
  "am",
  "it",
  "its",
  "this",
  "that",
  "these",
  "those",
  "as",
  "so",
  "than",
  "then",
  "there",
  "here",
  "not",
  "no",
  "do",
  "does",
  "did",
  "have",
  "has",
  "had",
  "i",
  "you",
  "he",
  "she",
  "we",
  "they",
]);
const WORD = /[\p{L}\p{M}\p{N}_]+/gu;

export interface TokenInfo {
  term: string;
  original: string;
  start: number;
  end: number;
  position: number;
  field: string;
}

export function stem(token: string): string {
  if (token.length <= 3) return token;
  if (token.endsWith("ing") && token.length > 5) return token.slice(0, -3);
  if (token.endsWith("edly")) return token.slice(0, -4);
  if (token.endsWith("ed") && token.length > 4) return token.slice(0, -2);
  if (token.endsWith("ies") && token.length > 4)
    return token.slice(0, -3) + "y";
  if (token.endsWith("es") && token.length > 4) return token.slice(0, -2);
  if (token.endsWith("s") && !token.endsWith("ss")) return token.slice(0, -1);
  return token;
}

function identifierParts(raw: string): string[] {
  return raw
    .split(/[_\-.]+|(?<=[a-z\d])(?=[A-Z])/)
    .filter(Boolean)
    .map((x) => x.toLowerCase());
}

export function tokenizeDetailed(text: string, field = "text"): TokenInfo[] {
  const out: TokenInfo[] = [];
  let position = 0;
  for (const m of text.matchAll(WORD)) {
    const original = m[0]!;
    const start = m.index ?? 0;
    // NFC makes composed and decomposed Unicode equivalent without changing source offsets.
    const raw = original.normalize("NFC").toLocaleLowerCase();
    const parts = identifierParts(original);
    const terms = parts.length > 1 ? [raw, ...parts] : [stem(raw)];
    if (!STOPWORDS.has(raw))
      for (const term of terms)
        out.push({
          term,
          original,
          start,
          end: start + original.length,
          position,
          field,
        });
    position++;
  }
  return out;
}

export function tokenize(text: string): string[] {
  return tokenizeDetailed(text).map((t) => t.term);
}

export function tokenizeDocument(doc: unknown): string[] {
  const values: string[] = [];
  collectStrings(doc, values);
  return tokenize(values.join(" "));
}

export function tokenizeDocumentDetailed(doc: unknown): TokenInfo[] {
  return documentFields(doc).flatMap(({ field, text }) =>
    tokenizeDetailed(text, field),
  );
}

export function documentFields(
  doc: unknown,
): Array<{ field: string; text: string }> {
  const fields: Array<{ field: string; text: string }> = [];
  if (doc && typeof doc === "object" && !Array.isArray(doc))
    for (const [field, value] of Object.entries(
      doc as Record<string, unknown>,
    )) {
      const values: string[] = [];
      collectStrings(value, values);
      if (values.length) fields.push({ field, text: values.join(" ") });
    }
  if (!fields.length) {
    const values: string[] = [];
    collectStrings(doc, values);
    fields.push({ field: "text", text: values.join(" ") });
  }
  return fields;
}

function collectStrings(value: unknown, out: string[]): void {
  if (value === null || value === undefined) return;
  if (["string", "number", "boolean"].includes(typeof value))
    out.push(String(value));
  else if (Array.isArray(value))
    for (const item of value) collectStrings(item, out);
  else if (typeof value === "object")
    for (const v of Object.values(value as Record<string, unknown>))
      collectStrings(v, out);
}

/** Unstemmed surface words include stopwords for exact positional phrases. */
export function surfaceTokens(text: string, field = "text"): TokenInfo[] {
  return [...text.matchAll(WORD)].map((m, position) => ({
    term: m[0].normalize("NFC").toLowerCase(),
    original: m[0],
    start: m.index!,
    end: m.index! + m[0].length,
    position,
    field,
  }));
}

import { BM25_K1, BM25_B } from "../config.js";
import type { InvertedIndexStore } from "./index.js";
import type { TermScore } from "../types.js";

export interface RankResult {
  docId: string;
  score: number;
  breakdown: TermScore[];
}

export interface RankOutput {
  /** Total number of documents matching at least one query term. */
  total: number;
  /** The top-N results (per the limit), highest score first. */
  results: RankResult[];
}

export interface RankOptions {
  limit?: number;
  k1?: number;
  b?: number;
}

export function idf(totalDocs: number, docsContaining: number): number {
  return Math.log(
    (totalDocs - docsContaining + 0.5) / (docsContaining + 0.5) + 1,
  );
}

/** Contribution of a single (term, doc) pair to the BM25 score. */
function contributionOf(
  termIdf: number,
  termFrequency: number,
  docLen: number,
  avgdl: number,
  k1: number,
  b: number,
): number {
  const denom = termFrequency + k1 * (1 - b + (b * docLen) / avgdl);
  return (termIdf * (termFrequency * (k1 + 1))) / denom;
}

export function rankBM25(
  index: InvertedIndexStore,
  queryTerms: string[],
  options: RankOptions = {},
): RankOutput {
  const { limit = Infinity, k1 = BM25_K1, b = BM25_B } = options;

  const totalDocs = index.documentCount();
  const avgdl = index.averageDocumentLength();
  if (totalDocs === 0 || avgdl === 0) return { total: 0, results: [] };

  // Deduplicate query terms and precompute each term's IDF once.
  const uniqueTerms = [...new Set(queryTerms)].filter(
    (t) => index.documentFrequency(t) > 0,
  );
  const idfByTerm = new Map<string, number>();
  for (const term of uniqueTerms) {
    idfByTerm.set(term, idf(totalDocs, index.documentFrequency(term)));
  }

  // Pass 1: accumulate total scores. Numbers only — no per-candidate objects.
  const scores = new Map<string, number>();
  for (const term of uniqueTerms) {
    const termIdf = idfByTerm.get(term)!;
    for (const { docId, termFrequency } of index.postingEntries(term)) {
      const c = contributionOf(
        termIdf,
        termFrequency,
        index.documentLength(docId),
        avgdl,
        k1,
        b,
      );
      scores.set(docId, (scores.get(docId) ?? 0) + c);
    }
  }

  // Select the winners: partial top-N when a limit is set, else full sort.
  const winners = selectTopN(scores, limit);

  // Pass 2: one walk per term collecting tf for winners only, not one walk per winner.
  const winnerIds = new Set(winners.map((w) => w.docId));
  const tfByDoc = new Map<string, Map<string, number>>();
  for (const id of winnerIds) tfByDoc.set(id, new Map());
  for (const term of uniqueTerms) {
    for (const { docId, termFrequency } of index.postingEntries(term)) {
      tfByDoc.get(docId)?.set(term, termFrequency);
    }
  }

  const results = winners.map(({ docId, score }) => {
    const docLen = index.documentLength(docId);
    const breakdown: TermScore[] = [];
    for (const [term, tf] of tfByDoc.get(docId)!) {
      const termIdf = idfByTerm.get(term)!;
      breakdown.push({
        term,
        termFrequency: tf,
        idf: termIdf,
        contribution: contributionOf(termIdf, tf, docLen, avgdl, k1, b),
      });
    }
    breakdown.sort((a, b2) => b2.contribution - a.contribution);
    return { docId, score, breakdown };
  });

  return { total: scores.size, results };
}

function selectTopN(
  scores: Map<string, number>,
  limit: number,
): Array<{ docId: string; score: number }> {
  const all: Array<{ docId: string; score: number }> = [];

  if (!Number.isFinite(limit) || limit >= scores.size) {
    for (const [docId, score] of scores) all.push({ docId, score });
    all.sort((a, b) => b.score - a.score);
    return all;
  }

  const heap = new MinHeap(limit);
  for (const [docId, score] of scores) heap.offer(docId, score);
  return heap.drainDescending();
}

/** Fixed-capacity min-heap keyed by score, keeping the top-`capacity` items. */
class MinHeap {
  private readonly ids: string[] = [];
  private readonly scores: number[] = [];

  constructor(private readonly capacity: number) {}

  offer(id: string, score: number): void {
    if (this.scores.length < this.capacity) {
      this.ids.push(id);
      this.scores.push(score);
      this.bubbleUp(this.scores.length - 1);
    } else if (score > this.scores[0]!) {
      this.ids[0] = id;
      this.scores[0] = score;
      this.bubbleDown(0);
    }
  }

  drainDescending(): Array<{ docId: string; score: number }> {
    const out = this.ids.map((id, i) => ({ docId: id, score: this.scores[i]! }));
    out.sort((a, b) => b.score - a.score);
    return out;
  }

  private bubbleUp(i: number): void {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.scores[parent]! <= this.scores[i]!) break;
      this.swap(i, parent);
      i = parent;
    }
  }

  private bubbleDown(i: number): void {
    const n = this.scores.length;
    for (;;) {
      const l = 2 * i + 1;
      const r = 2 * i + 2;
      let smallest = i;
      if (l < n && this.scores[l]! < this.scores[smallest]!) smallest = l;
      if (r < n && this.scores[r]! < this.scores[smallest]!) smallest = r;
      if (smallest === i) break;
      this.swap(i, smallest);
      i = smallest;
    }
  }

  private swap(a: number, b: number): void {
    [this.ids[a], this.ids[b]] = [this.ids[b]!, this.ids[a]!];
    [this.scores[a], this.scores[b]] = [this.scores[b]!, this.scores[a]!];
  }
}

/** A bounded heap. The least desirable row stays at the root. */
export class TopHeap<T> {
  private rows: T[] = [];
  constructor(
    private capacity: number,
    private compare: (a: T, b: T) => number,
  ) {}
  offer(row: T): void {
    if (!this.capacity) return;
    if (this.rows.length < this.capacity) {
      this.rows.push(row);
      let i = this.rows.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (this.compare(this.rows[i]!, this.rows[p]!) <= 0) break;
        [this.rows[i], this.rows[p]] = [this.rows[p]!, this.rows[i]!];
        i = p;
      }
    } else if (this.compare(row, this.rows[0]!) < 0) {
      this.rows[0] = row;
      let i = 0;
      for (;;) {
        let worst = i;
        for (const child of [i * 2 + 1, i * 2 + 2])
          if (
            child < this.rows.length &&
            this.compare(this.rows[child]!, this.rows[worst]!) > 0
          )
            worst = child;
        if (worst === i) break;
        [this.rows[i], this.rows[worst]] = [this.rows[worst]!, this.rows[i]!];
        i = worst;
      }
    }
  }
  sorted(): T[] {
    return this.rows.sort(this.compare);
  }
}

import fs from "node:fs";
import { createHash } from "node:crypto";
import {
  dataPaths,
  SNAPSHOT_EVERY_N_WRITES,
  type DataPaths,
  BM25_K1,
  BM25_B,
} from "./config.js";
import { Storage } from "./storage/storage.js";
import { TopHeap } from "./search/heap.js";
import { InvertedIndexStore, type IndexedField } from "./search/index.js";
import { idf } from "./search/rank.js";
import {
  tokenize,
  tokenizeDocument,
  tokenizeDetailed,
  documentFields,
  surfaceTokens,
  type TokenInfo,
} from "./search/tokenizer.js";
import type {
  Document,
  SearchHit,
  TermScore,
  SearchOptions,
  SearchSnippet,
  Facet,
  SearchInspector,
  RebuildStatus,
  MissingExplanation,
} from "./types.js";

export interface SearchResponse {
  query: string;
  terms: string[];
  tookMs: number;
  total: number;
  hits: SearchHit[];
  facets: { source: Facet[]; repo: Facet[]; type: Facet[]; language: Facet[] };
  groups: Array<{ key: string; count: number }>;
  inspector?: SearchInspector;
}
export interface BenchmarkResponse {
  query: string;
  terms: string[];
  indexed: { tookMs: number; scanned: number; hits: number };
  naive: { tookMs: number; scanned: number; hits: number };
  speedup: number;
  topHitsMatch: boolean;
}
export class SearchInputError extends Error {
  readonly statusCode = 400;
  constructor(message: string) {
    super(message);
    this.name = "SearchInputError";
  }
}
type Parsed = {
  terms: string[];
  phrases: string[];
  exclude: string[];
  fields: Array<[string, string]>;
};
const META = ["source", "repo", "type", "language"] as const;
type Scored = { id: string; score: number; breakdown: TermScore[] };

export class Engine {
  private readonly storage: Storage;
  private index = new InvertedIndexStore();
  private readonly paths: DataPaths;
  private writesSinceSnapshot = 0;
  private readonly docs = new Map<string, Document>();
  private readonly sourceIds = new Map<string, string>();
  private readonly hashes = new Map<string, string>();
  private readonly docHashes = new Map<string, string>();
  private readonly cache = new Map<string, { doc: Document; bytes: number }>();
  private cacheBytes = 0;
  private storageReads = 0;
  private cacheHits = 0;
  private readonly maxCacheEntries = 128;
  private readonly maxCacheBytes = 8 * 1024 * 1024;
  private progress: RebuildStatus = { state: "idle", processed: 0, total: 0 };
  private rebuildCancelled = false;
  private closed = false;
  private readonly metadata = new Map<string, Map<string, Set<string>>>();
  constructor(dataDir?: string) {
    this.paths = dataPaths(dataDir);
    this.storage = new Storage(dataDir);
    try {
      this.hydrateIndex();
    } catch (error) {
      this.storage.close();
      throw error;
    }
  }
  addDocument(doc: Document): string {
    doc = structuredClone(doc);
    const id = this.storage.write(doc);
    this.indexDoc(id, doc);
    this.maybeSnapshot();
    return id;
  }
  addDocuments(docs: Document[]): string[] {
    docs = structuredClone(docs);
    const ids = this.storage.writeBatch(docs);
    ids.forEach((id, i) => this.indexDoc(id, docs[i]!));
    this.writesSinceSnapshot += ids.length;
    if (this.writesSinceSnapshot >= SNAPSHOT_EVERY_N_WRITES * 20) this.checkpoint();
    return ids;
  }
  getDocument(id: string): Document | null {
    return this.storage.read(id);
  }
  deleteDocument(id: string): boolean {
    const ok = this.storage.delete(id);
    if (ok) {
      const old = this.docs.get(id);
      if (old) {
        const source = identity(old);
        if (source && this.sourceIds.get(source) === id)
          this.sourceIds.delete(source);
        if (this.hashes.get(this.docHashes.get(id)!) === id)
          this.hashes.delete(this.docHashes.get(id)!);
      }
      this.index.removeDocument(id);
      this.docs.delete(id);
      this.evict(id);
      this.docHashes.delete(id);
      this.removeMetadata(id, old);
      this.maybeSnapshot();
    }
    return ok;
  }
  documentCount(): number {
    return this.docs.size;
  }
  listDocuments(
    offset: number,
    limit: number,
  ): { total: number; items: Array<{ id: string; doc: Document }> } {
    const ids = this.storage.liveDocIds();
    return {
      total: ids.length,
      items: ids
        .slice(offset, offset + limit)
        .map((id) => ({ id, doc: this.storage.read(id) ?? {} })),
    };
  }
  collectBySource(source: string): Array<{ id: string; pageid?: number }> {
    return this.storage.liveDocIds().flatMap((id) => {
      const d = this.docs.get(id);
      return d?.source === source
        ? [{ id, pageid: typeof d.pageid === "number" ? d.pageid : undefined }]
        : [];
    });
  }
  reset(): void {
    const version = this.storage.stateVersion();
    try {
      this.storage.reset();
    } finally {
      // Reset may commit before a directory sync or cleanup fails.
      if (this.storage.stateVersion() !== version) {
        this.index.clear();
        this.docs.clear();
        this.sourceIds.clear();
        this.hashes.clear();
        this.cache.clear();
        this.cacheBytes = 0;
        this.docHashes.clear();
        this.metadata.clear();
        this.writesSinceSnapshot = 0;
        fs.rmSync(this.paths.invertedSnapshot, { force: true });
      }
    }
  }

  search(
    query: string,
    limitOrOptions: number | SearchOptions = 10,
    maybeOptions: SearchOptions = {},
  ): SearchResponse {
    const readsBefore = this.storageReads, hitsBefore = this.cacheHits;
    const began = performance.now();
    const options =
      typeof limitOrOptions === "number"
        ? { ...maybeOptions, limit: limitOrOptions }
        : limitOrOptions;
    if (options.match !== undefined && !["text", "literal", "substring"].includes(options.match)) throw new SearchInputError("invalid match mode");
    const limit = Math.max(0, Math.min(1000, Math.floor(options.limit ?? 10)));
    const offset = Math.max(0, Math.floor(options.offset ?? 0));
    if (
      !Number.isSafeInteger(offset) ||
      offset > 100000 ||
      !Number.isFinite(limit)
    )
      throw new SearchInputError("invalid pagination");
    if (options.match && options.match !== "text") return this.searchLiteral(query, options);

    const stageMs: Record<string, number> = {};
    let stage = began;
    const finish = (name: string) => {
      const now = performance.now();
      stageMs[name] = now - stage;
      stage = now;
    };
    const parsed = parseQuery(query);
    const terms = unique(
      parsed.terms.flatMap(tokenize).concat(parsed.phrases.flatMap(tokenize)),
    );
    if (
      !terms.length &&
      !parsed.phrases.some((p) => surfaceTokens(p).length) &&
      !parsed.fields.length &&
      !META.some((k) => options[k] !== undefined) &&
      !options.docIds
    )
      throw new SearchInputError(
        "query must contain a searchable term, phrase, filter, or document id",
      );
    finish("parse");
    const expansions: Record<string, string[]> = {};
    for (const term of terms) {
      const values = new Set([term]);
      for (const synonym of (options.synonyms?.[term] ?? []).slice(0, 20))
        for (const value of tokenize(synonym.slice(0, 256)))
          if (values.size < 20) values.add(value);
      if (options.prefix)
        for (const value of this.index.prefix(term))
          if (values.size < 20) values.add(value);
      if (options.typos)
        for (const value of this.index.typos(term))
          if (values.size < 20) values.add(value);
      expansions[term] = [...values];
    }
    finish("expand");
    // Intersect indexed metadata scopes before walking postings or scoring documents.
    const scopes: Set<string>[] = [];
    for (const [key, value] of [
      ...parsed.fields,
      ...META.flatMap((k) =>
        options[k] === undefined ? [] : [[k, options[k]!] as [string, string]],
      ),
    ])
      scopes.push(this.metadata.get(key)?.get(value) ?? new Set());
    if (options.docIds) scopes.push(new Set(options.docIds));
    scopes.sort((a, b) => a.size - b.size);
    let scope: Set<string> | undefined;
    if (scopes.length)
      scope = new Set(
        [...scopes[0]!].filter((id) => scopes.every((s) => s.has(id))),
      );
    finish("candidates");
    const tfById = new Map<string, Map<string, number>>();
    let postingReads = 0;
    for (const value of new Set(Object.values(expansions).flat())) {
      for (const posting of this.index.postingEntries(value)) {
        postingReads++;
        if (scope && !scope.has(posting.docId)) continue;
        const tf = tfById.get(posting.docId) ?? new Map<string, number>();
        tf.set(value, posting.termFrequency);
        tfById.set(posting.docId, tf);
      }
    }
    if (!terms.length)
      for (const id of scope ?? this.docs.keys())
        if (this.docs.has(id)) tfById.set(id, new Map());
    finish("postings");
    const excluded = new Set<string>();
    for (const term of parsed.exclude)
      for (const p of this.index.postingEntries(term)) {
        postingReads++;
        excluded.add(p.docId);
      }
    const candidates = new Map<string, Map<string, number>>();
    for (const [id, tf] of tfById) {
      if (
        excluded.has(id) ||
        parsed.phrases.some((p) => !hasPhrase(this.surfaceInfo(id), p))
      )
        continue;
      if (
        (options.mode ?? "any") === "all" &&
        terms.some((t) => !expansions[t]!.some((e) => tf.has(e)))
      )
        continue;
      candidates.set(id, tf);
    }
    finish("filter");
    const compare = (a: Scored, b: Scored) =>
      b.score - a.score || a.id.localeCompare(b.id);
    const heaps = new Map<string, TopHeap<Scored>>();
    const allIds: string[] = [];
    const groupBy = options.groupBy ?? "none";
    const weights = new Map<string, number>();
    for (const term of terms)
      for (const expanded of expansions[term]!)
        weights.set(
          expanded,
          Math.max(weights.get(expanded) ?? 0, expanded === term ? 1 : 0.65),
        );
    const idfs = new Map(
      [...weights.keys()].map((t) => [
        t,
        idf(this.docs.size, this.index.documentFrequency(t)),
      ]),
    );
    for (const [id, tf] of candidates) {
      const breakdown: TermScore[] = [];
      if (options.profile === "baseline") {
        for (const [term, frequency] of tf)
          breakdown.push({
            term,
            termFrequency: frequency,
            idf: idfs.get(term)!,
            contribution:
              bm25(
                frequency,
                this.index.documentLength(id),
                this.index.averageDocumentLength(),
              ) * idfs.get(term)!,
          });
      } else {
        const contributions = new Map<string, TermScore>();
        for (const field of this.index.indexedFields(id)) {
          let best: TermScore[] = [],
            bestScore = -1;
          for (const window of field.windows) {
            const scores: TermScore[] = [];
            for (const [term, weight] of weights) {
              const frequency = window.tf.get(term);
              if (frequency)
                scores.push({
                  term,
                  termFrequency: frequency,
                  idf: idfs.get(term)!,
                  contribution:
                    weight *
                    fieldWeight(field.field) *
                    idfs.get(term)! *
                    bm25(
                      frequency,
                      window.length,
                      this.index.averageFieldLength(field.field),
                    ),
                });
            }
            const score = scores.reduce((sum, s) => sum + s.contribution, 0);
            if (score > bestScore) {
              bestScore = score;
              best = scores;
            }
          }
          for (const entry of best) {
            const previous = contributions.get(entry.term);
            contributions.set(
              entry.term,
              previous
                ? {
                    ...entry,
                    termFrequency: previous.termFrequency + entry.termFrequency,
                    contribution: previous.contribution + entry.contribution,
                  }
                : entry,
            );
          }
        }
        breakdown.push(...contributions.values());
      }
      breakdown.sort((a, b) => b.contribution - a.contribution);
      const row = {
        id,
        score: breakdown.reduce((sum, t) => sum + t.contribution, 0),
        breakdown,
      };
      const key =
        groupBy === "none" ? "" : String(this.docs.get(id)?.[groupBy] ?? "");
      let heap = heaps.get(key);
      if (!heap) {
        heap = new TopHeap(offset + limit, compare);
        heaps.set(key, heap);
      }
      heap.offer(row);
      allIds.push(id);
    }
    let selected: Scored[];
    if (groupBy === "none") selected = heaps.get("")?.sorted() ?? [];
    else {
      const buckets = [...heaps].map(([key, heap]) => ({
        key,
        rows: heap.sorted(),
      }));
      buckets.sort((a, b) =>
        compare(
          a.rows[0] ?? { id: a.key, score: 0, breakdown: [] },
          b.rows[0] ?? { id: b.key, score: 0, breakdown: [] },
        ),
      );
      selected = [];
      for (let round = 0; selected.length < offset + limit; round++) {
        let moved = false;
        for (const bucket of buckets)
          if (bucket.rows[round]) {
            selected.push(bucket.rows[round]!);
            moved = true;
            if (selected.length === offset + limit) break;
          }
        if (!moved) break;
      }
    }
    const paged = selected.slice(offset, offset + limit);
    const resultFacets = facets(allIds, this.docs),
      groups = groupCounts(allIds, this.docs, groupBy);
    finish("score");
    const hits = paged.map((row) => {
      const doc = structuredClone(this.readDoc(row.id)!);
      let passages = makePassages(
        doc,
        this.index.indexedFields(row.id),
        weights,
        idfs,
        this.index,
      );
      if (!passages.length && parsed.phrases.length)
        passages = phrasePassages(
          doc,
          this.surfaceInfo(row.id),
          parsed.phrases,
        );
      return {
        docId: row.id,
        score: row.score,
        doc,
        breakdown: row.breakdown,
        snippet: passages[0],
        passages,
        ...(groupBy === "none" ? {} : { groupKey: String(doc[groupBy] ?? "") }),
      };
    });
    finish("read");
    const tookMs = performance.now() - began;
    stageMs.total = tookMs;
    const response: SearchResponse = {
      query,
      terms,
      tookMs,
      total: allIds.length,
      hits,
      facets: resultFacets,
      groups,
    };
    if (options.inspect)
      response.inspector = {
        parsedQuery: [...parsed.terms, ...parsed.phrases],
        expansions,
        candidateCount: tfById.size,
        postingReads,
        documentReads: this.storageReads - readsBefore,
        cacheHits: this.cacheHits - hitsBefore,
        documentSource: this.storageReads === readsBefore ? "memory" : this.cacheHits === hitsBefore ? "storage" : "mixed",
        stageMs,
        stages: Object.entries(stageMs).map(([name, tookMs]) => ({
          name,
          tookMs,
        })),
        scoreBreakdown: Object.fromEntries(
          paged.map((r) => [r.id, r.breakdown]),
        ),
      };
    return response;
  }

  rebuildStatus(): RebuildStatus { return { ...this.progress }; }
  cancelRebuild(): boolean {
    if (this.progress.state !== "running") return false;
    this.rebuildCancelled = true;
    return true;
  }
  async rebuildIndex(options: { signal?: AbortSignal; batchSize?: number } = {}): Promise<RebuildStatus> {
    if (this.closed) throw new Error("engine is closed");
    if (this.progress.state === "running") throw new SearchInputError("rebuild already running");
    const batchSize = options.batchSize ?? 32;
    if (!Number.isSafeInteger(batchSize) || batchSize < 1 || batchSize > 256) throw new SearchInputError("batchSize must be 1..256");
    const version = this.storage.stateVersion(), ids = this.storage.liveDocIds();
    const shadow = new InvertedIndexStore();
    this.rebuildCancelled = false;
    this.progress = { state: "running", processed: 0, total: ids.length, startedAt: new Date().toISOString() };
    const interrupted = () => {
      if (this.rebuildCancelled || options.signal?.aborted || this.closed) return "cancelled" as const;
      if (version !== this.storage.stateVersion()) return "stale" as const;
      return undefined;
    };
    try {
      // Yield before reading so even an empty rebuild can be cancelled.
      await new Promise<void>(resolve => setImmediate(resolve));
      for (let i = 0; i < ids.length; i++) {
        const state = interrupted();
        if (state) { this.progress.state = state; break; }
        const doc = this.storage.read(ids[i]!);
        if (!doc) throw new Error("document disappeared during rebuild");
        const fields = documentFields(doc).map(f => ({ ...f, tokens: tokenizeDetailed(f.text, f.field) }));
        shadow.addDocument(ids[i]!, fields.flatMap(f => f.tokens.map(t => t.term)));
        shadow.setFields(ids[i]!, fields);
        this.progress.processed++;
        if ((i + 1) % batchSize === 0) await new Promise<void>(resolve => setImmediate(resolve));
      }
      if (this.progress.state === "running") {
        const state = interrupted();
        if (state) this.progress.state = state;
        else { this.index = shadow; this.progress.state = "completed"; }
      }
    } catch (error) {
      this.progress.state = "failed";
      this.progress.error = error instanceof Error ? error.message : String(error);
    }
    this.progress.finishedAt = new Date().toISOString();
    return this.rebuildStatus();
  }

  private searchLiteral(query: string, options: SearchOptions): SearchResponse {
    const began = performance.now(), before = this.storageReads, hitsBefore = this.cacheHits;
    if (typeof query !== "string" || query.length < (options.match === "substring" ? 2 : 1) || query.length > 256)
      throw new SearchInputError("literal query must be 1..256 characters; substring requires at least 2");
    const ids = [...this.docs.keys()].filter(id => (!options.docIds || options.docIds.includes(id)) && META.every(k => options[k] === undefined || String(this.docs.get(id)?.[k]) === options[k]));
    if (ids.length > 2000) throw new SearchInputError("literal scan exceeds 2000 documents; narrow filters or document ids");
    const pattern = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), options.match === "substring" ? "giu" : "gu");
    const snippets = new Map<string, SearchSnippet[]>();
    let scanned = 0;
    for (const id of ids) {
      const doc = this.readDoc(id)!;
      const passages: SearchSnippet[] = [];
      for (const { field, text } of documentFields(doc)) {
        scanned += text.length;
        if (scanned > 8 * 1024 * 1024) throw new SearchInputError("literal scan exceeds 8 Mi UTF-16 units; narrow scope");
        pattern.lastIndex = 0;
        for (let found = pattern.exec(text); found && passages.length < 3; found = pattern.exec(text)) {
          const at = found.index, endAt = at + found[0].length;
          const start = Math.max(0, at - 80), end = Math.min(text.length, endAt + 100);
          const pages = field === "content" && Array.isArray(doc.pageOffsets) ? doc.pageOffsets as Array<{page:number;start:number;end:number}> : [];
          const page = pages.find(p => at >= p.start && at < p.end)?.page;
          passages.push({ field, text: text.slice(start, end), start, end, matches: [{start:at,end:endAt}], line: text.slice(0, at).split("\n").length, ...(page === undefined ? {} : {page}) });
        }
      }
      if (passages.length) snippets.set(id, passages);
    }
    const result = this.search("", { ...options, match: "text", docIds: [...snippets.keys()] });
    result.query = query; result.terms = [query]; result.tookMs = performance.now() - began;
    for (const hit of result.hits) { hit.passages = snippets.get(hit.docId); hit.snippet = hit.passages?.[0]; }
    if (result.inspector) {
      result.inspector.parsedQuery = [query]; result.inspector.expansions = { [query]: [query] };
      result.inspector.documentReads = this.storageReads - before;
      result.inspector.cacheHits = this.cacheHits - hitsBefore;
      result.inspector.documentSource = this.storageReads === before ? "memory" : this.cacheHits === hitsBefore ? "storage" : "mixed";
      result.inspector.stageMs.literalScan = result.tookMs - result.inspector.stageMs.total!;
      result.inspector.stageMs.total = result.tookMs;
    }
    return result;
  }

  explainMissing(query: string, docId: string, options: SearchOptions = {}): MissingExplanation {
    const reasons: MissingExplanation["reasons"] = [];
    const base: MissingExplanation = { query, docId, matched: false, returned: false, reasons, total: 0, expansions: {} };
    if (!this.docs.has(docId)) { reasons.push({code:"missing_document",detail:"Document does not exist"}); return base; }
    const literal = options.match && options.match !== "text";
    const parsed = literal ? {terms:[],phrases:[],exclude:[],fields:[]} : parseQuery(query);
    const terms = unique(parsed.terms.flatMap(tokenize).concat(parsed.phrases.flatMap(tokenize)));
    if (!literal && !terms.length && !parsed.phrases.length && !parsed.fields.length && !META.some(k => options[k] !== undefined) && !options.docIds) {
      const words = parsed.terms.flatMap(t => surfaceTokens(t));
      reasons.push(words.length ? {code:"stopwords",detail:"Query contains no indexed terms after stopword removal"} : {code:"no_terms",detail:"Query contains no positive searchable terms; use literal mode for symbols"}); return base;
    }
    const result = this.search(query, { ...options, inspect:true });
    base.total = result.total; base.expansions = result.inspector!.expansions;
    const doc = this.docs.get(docId)!;
    for (const [key, value] of [...parsed.fields, ...META.flatMap(k => options[k] === undefined ? [] : [[k, options[k]!] as [string,string]])])
      if (String(doc[key]) !== value) reasons.push({code:"filter",detail:`${key} does not match ${value}`});
    if (options.docIds && !options.docIds.includes(docId)) reasons.push({code:"filter",detail:"Document is outside the selected document ids"});
    if (!literal) {
      const tf = this.index.indexedFields(docId);
      const missing = terms.filter(t => !(base.expansions[t] ?? [t]).some(e => tf.some(f => f.tf.has(e))));
      if ((options.mode ?? "any") === "all" || missing.length === terms.length)
        for (const term of missing) reasons.push({code:(base.expansions[term]?.length ?? 0) > 1 ? "expansion" : "term",detail:`No match for ${term} or its enabled expansions`});
      for (const phrase of parsed.phrases) if (!hasPhrase(this.surfaceInfo(docId),phrase)) reasons.push({code:"phrase",detail:`Exact phrase missing: ${phrase}`});
      for (const term of parsed.exclude) if (tf.some(f => f.tf.has(term))) reasons.push({code:"exclusion",detail:`Matches excluded term ${term}`});
    }
    const scoped = this.search(query, {...options, docIds: options.docIds && !options.docIds.includes(docId) ? [] : [docId],offset:0,limit:1});
    base.matched = scoped.total > 0;
    if (!base.matched) { if (literal && !reasons.length) reasons.push({code:"literal",detail:"Original text does not contain the requested literal"}); return base; }
    const returnedAt = result.hits.findIndex(h => h.docId === docId);
    base.returned = returnedAt >= 0;
    if (base.returned) base.rank = (options.offset ?? 0) + returnedAt + 1;
    else {
      // shortcut: inspect only the first 1000 ranks, expand with a shared score-only ranking pass if needed.
      const page = this.search(query, {...options, offset:0, limit:1000});
      const position = page.hits.findIndex(h => h.docId === docId);
      if (position >= 0) {
        base.rank = position + 1;
        reasons.push({code:base.rank <= (options.offset ?? 0) ? "page" : "rank",detail:`Rank ${base.rank} is outside the requested page`});
      } else reasons.push({code:"rank_unknown",detail:"Matches but is outside the requested page. Rank is unknown beyond the first 1000 results inspected"});
    }
    return base;
  }

  naiveSearch(query: string, limit = 10): SearchResponse {
    const terms = unique(tokenize(query));
    const start = performance.now();
    const scored: Scored[] = [];
    for (const id of this.docs.keys()) {
      const doc = this.readDoc(id)!;
      const all = tokenizeDocument(doc);
      const tf = new Map<string, number>();
      for (const t of all)
        if (terms.includes(t)) tf.set(t, (tf.get(t) ?? 0) + 1);
      if (!tf.size) continue;
      const len = Math.max(all.length, 1);
      let score = 0;
      const breakdown: TermScore[] = [];
      for (const [term, f] of tf) {
        const termIdf = idf(this.docs.size, this.index.documentFrequency(term));
        const c =
          (termIdf * f * (BM25_K1 + 1)) /
          (f +
            BM25_K1 *
              (1 -
                BM25_B +
                (BM25_B * len) /
                  Math.max(this.index.averageDocumentLength(), 1)));
        score += c;
        breakdown.push({
          term,
          termFrequency: f,
          idf: termIdf,
          contribution: c,
        });
      }
      scored.push({ id, score, breakdown });
    }
    scored.sort((a, b) => b.score - a.score);
    return {
      query,
      terms,
      tookMs: performance.now() - start,
      total: scored.length,
      hits: scored.slice(0, limit).map((r) => ({
        docId: r.id,
        score: r.score,
        doc: structuredClone(this.readDoc(r.id)!),
        breakdown: r.breakdown,
      })),
      facets: { source: [], repo: [], type: [], language: [] },
      groups: [],
    };
  }
  benchmark(query: string, limit = 10): BenchmarkResponse {
    const indexed = this.search(query, { limit, profile: "baseline" }),
      naive = this.naiveSearch(query, limit);
    return {
      query,
      terms: indexed.terms,
      indexed: {
        tookMs: indexed.tookMs,
        scanned: indexed.total,
        hits: indexed.hits.length,
      },
      naive: {
        tookMs: naive.tookMs,
        scanned: this.storage.size(),
        hits: naive.hits.length,
      },
      speedup: naive.tookMs / Math.max(indexed.tookMs, 1e-6),
      topHitsMatch: indexed.hits[0]?.docId === naive.hits[0]?.docId,
    };
  }
  suggest(prefix: string, limit = 10): string[] {
    return this.index.prefix(
      prefix.normalize("NFC").toLowerCase(),
      Math.max(0, Math.min(50, limit)),
    );
  }
  diagnostics(term?: string): unknown {
    const selected = (
      term ? [term.toLocaleLowerCase()] : this.index.terms()
    ).slice(0, 50);
    return {
      documentCache: { byteSource: "estimated UTF-16 serialized document size; excludes object overhead", entries: this.cache.size, bytes: this.cacheBytes, maxEntries: this.maxCacheEntries, maxBytes: this.maxCacheBytes },
      postingMemory: this.index.postingMemory(),
      rebuild: this.rebuildStatus(),
      documents: this.index.documentCount(),
      vocabularySize: this.index.terms().length,
      postingCount: this.index
        .terms()
        .reduce((n, t) => n + this.index.documentFrequency(t), 0),
      indexBytes: fs.existsSync(this.paths.invertedSnapshot)
        ? fs.statSync(this.paths.invertedSnapshot).size
        : undefined,
      memoryBytes: process.memoryUsage().heapUsed,
      memorySource: "process.heapUsed",
      storage: this.storage.diagnostics(),
      terms: selected.map((t) => ({
        term: t,
        documentFrequency: this.index.documentFrequency(t),
        postings: this.index.postings(t).slice(0, 20),
      })),
    };
  }
  compare(
    query: string,
    options: SearchOptions = {},
  ): { baseline: SearchResponse; tuned: SearchResponse } {
    return {
      baseline: this.search(query, { ...options, profile: "baseline" }),
      tuned: this.search(query, { ...options, profile: "tuned" }),
    };
  }
  ingestDocuments(docs: Document[]): {
    ids: string[];
    added: number;
    updated: number;
    duplicates: number;
  } {
    const ids: string[] = [];
    let added = 0,
      updated = 0,
      duplicates = 0;
    let pending: Document[] = [];
    const pendingKeys = new Set<string>();
    const flush = () => {
      if (!pending.length) return;
      ids.push(...this.addDocuments(pending));
      added += pending.length;
      pending = [];
      pendingKeys.clear();
    };
    for (const doc of docs) {
      const source = identity(doc),
        hash = hashDoc(doc),
        key = source ?? hash;
      // Flush before a repeated identity so the next input sees the preceding durable version.
      if (pendingKeys.has(key)) flush();
      const existing = source
        ? this.sourceIds.get(source)
        : this.hashes.get(hash);
      if (!existing) {
        pending.push(doc);
        pendingKeys.add(key);
        if (pending.length === 500) flush();
        continue;
      }
      flush();
      if (this.docHashes.get(existing) === hash) {
        ids.push(existing);
        duplicates++;
      } else {
        const copy = structuredClone(doc);
        this.storage.writeWithId(existing, copy);
        this.indexDoc(existing, copy);
        this.maybeSnapshot();
        ids.push(existing);
        updated++;
      }
    }
    flush();
    return { ids, added, updated, duplicates };
  }
  exportBackup(): {
    version: 1;
    documents: Array<{ id: string; doc: Document }>;
  } {
    return {
      version: 1,
      documents: [...this.docs.keys()].map((id) => ({
        id,
        doc: structuredClone(this.readDoc(id)!),
      })),
    };
  }
  restoreBackup(input: unknown): {
    added: number;
    updated: number;
    duplicates: number;
  } {
    let items: Array<{ id: string; doc: Document }>;
    try {
      items = validateBackup(input);
    } catch (e) {
      throw new SearchInputError(
        e instanceof Error ? e.message : "invalid backup",
      );
    }
    const byId = new Map<string, Document>();
    for (const x of items) {
      if (byId.has(x.id)) throw new SearchInputError("duplicate backup id");
      byId.set(x.id, x.doc);
    }
    for (const [id, doc] of byId)
      if (this.docs.has(id) && this.docHashes.get(id) !== hashDoc(doc))
        throw new SearchInputError(`backup conflicts with existing id ${id}`);
    let added = 0,
      duplicates = 0;
    for (const [id, doc] of byId) {
      if (this.docs.has(id)) {
        duplicates++;
        continue;
      }
      const copy = structuredClone(doc);
      this.storage.writeWithId(id, copy);
      this.indexDoc(id, copy);
      added++;
    }
    return { added, updated: 0, duplicates };
  }
  compact(): { reclaimedBytes: number; removedDocuments: number } {
    const result = this.storage.compact();
    this.snapshot();
    return result;
  }
  snapshot(): void {
    this.storage.snapshot();
    this.index.snapshot(
      this.paths.invertedSnapshot,
      this.storage.stateVersion(),
    );
    this.writesSinceSnapshot = 0;
  }
  close(): void {
    this.closed = true;
    this.cancelRebuild();
    try {
      this.snapshot();
    } finally {
      this.storage.close();
    }
  }
  private checkpoint(): void {
    // WAL remains durable; only the rebuildable full-text cache waits for an explicit snapshot.
    this.storage.snapshot();
    this.writesSinceSnapshot = 0;
  }
  private evict(id: string): void {
    const value = this.cache.get(id);
    if (value) this.cacheBytes -= value.bytes;
    this.cache.delete(id);
  }
  private putCache(id: string, doc: Document): void {
    this.evict(id);
    const bytes = Buffer.byteLength(JSON.stringify(doc)) * 2;
    if (bytes > this.maxCacheBytes) return;
    this.cache.set(id, { doc, bytes }); this.cacheBytes += bytes;
    while (this.cache.size > this.maxCacheEntries || this.cacheBytes > this.maxCacheBytes) this.evict(this.cache.keys().next().value!);
  }
  private readDoc(id: string): Document | null {
    const cached = this.cache.get(id);
    if (cached) { this.cacheHits++; this.cache.delete(id); this.cache.set(id, cached); return cached.doc; }
    this.storageReads++;
    const doc = this.storage.read(id);
    if (doc) this.putCache(id, doc);
    return doc;
  }
  private surfaceInfo(id: string): TokenInfo[] {
    return documentFields(this.readDoc(id)).flatMap(f => surfaceTokens(f.text, f.field));
  }
  private maybeSnapshot(): void {
    if (++this.writesSinceSnapshot >= SNAPSHOT_EVERY_N_WRITES * 20) this.checkpoint();
  }
  private removeMetadata(id: string, doc?: Document): void {
    if (!doc) return;
    for (const key of META) {
      const values = this.metadata.get(key),
        value = String(doc[key]);
      const ids = values?.get(value);
      ids?.delete(id);
      if (!ids?.size) values?.delete(value);
    }
  }
  private indexDoc(id: string, doc: Document, cached = false): void {
    const old = this.docs.get(id);
    if (old) {
      const source = identity(old);
      if (source && this.sourceIds.get(source) === id)
        this.sourceIds.delete(source);
      if (this.hashes.get(this.docHashes.get(id)!) === id)
        this.hashes.delete(this.docHashes.get(id)!);
      this.removeMetadata(id, old);
    }
    const fields = documentFields(doc).map((f) => ({
      ...f,
      tokens: tokenizeDetailed(f.text, f.field),
    }));
    const info = fields.flatMap((f) => f.tokens);
    if (!cached)
      this.index.addDocument(
        id,
        info.map((x) => x.term),
      );
    this.index.setFields(id, fields);
    this.docs.set(id, Object.fromEntries([...META, "sourceId", "pageid", "fullName", "path"].filter(k => doc[k] !== undefined).map(k => [k, doc[k]])));
    this.putCache(id, doc);
    this.docHashes.set(id, hashDoc(doc));
    for (const key of META)
      if (doc[key] !== undefined) {
        const values = this.metadata.get(key) ?? new Map<string, Set<string>>();
        const value = String(doc[key]),
          ids = values.get(value) ?? new Set<string>();
        ids.add(id);
        values.set(value, ids);
        this.metadata.set(key, values);
      }
    const source = identity(doc);
    if (source) this.sourceIds.set(source, id);
    this.hashes.set(hashDoc(doc), id);
  }
  private hydrateIndex(): void {
    let loaded = false;
    const ids = this.storage.liveDocIds();
    try {
      loaded =
        this.index.load(this.paths.invertedSnapshot) ===
          this.storage.stateVersion() &&
        this.index.documentCount() === ids.length &&
        ids.every((id) => this.index.hasDocument(id));
    } catch {
      /* Corrupt caches never block recovery. */
    }
    if (!loaded) this.index.clear();
    for (const id of ids) {
      const doc = this.storage.read(id);
      if (doc) this.indexDoc(id, doc, loaded);
    }
  }
}

function unique(xs: string[]): string[] {
  return [...new Set(xs)];
}
function parseQuery(query: string): Parsed {
  if (typeof query !== "string" || query.length > 4096)
    throw new SearchInputError("query must be at most 4096 characters");
  if ((query.match(/"/g) ?? []).length % 2)
    throw new SearchInputError("unterminated quoted phrase");
  const phrases: string[] = [];
  const without = query.replace(/"([^\"]+)"/g, (_, p: string) => {
    phrases.push(p);
    return " ";
  });
  const words = without.split(/\s+/).filter(Boolean);
  const fields = words.flatMap((x) => {
    const m = /^(source|repo|type|language):(.+)$/.exec(x);
    return m ? [[m[1]!, m[2]!] as [string, string]] : [];
  });
  return {
    terms: words.filter(
      (x) => !x.startsWith("-") && !/^(source|repo|type|language):/.test(x),
    ),
    phrases,
    exclude: words
      .filter((x) => x.startsWith("-"))
      .flatMap((x) => tokenize(x.slice(1))),
    fields,
  };
}
function bm25(tf: number, length: number, average: number): number {
  return (
    (tf * (BM25_K1 + 1)) /
    (tf + BM25_K1 * (1 - BM25_B + (BM25_B * length) / Math.max(average, 1)))
  );
}
function fieldWeight(field: string): number {
  return field === "title"
    ? 3
    : field === "path"
      ? 2
      : field === "repo"
        ? 1.5
        : 1;
}
function hasPhrase(info: TokenInfo[], phrase: string): boolean {
  const q = surfaceTokens(phrase);
  if (!q.length) return false;
  for (let i = 0; i < info.length; i++) {
    const first = info[i]!;
    if (
      q.every(
        (t, j) =>
          info[i + j]?.field === first.field &&
          info[i + j]?.term === t.term &&
          info[i + j]?.position === first.position + j,
      )
    )
      return true;
  }
  return false;
}
function makePassages(
  doc: Document,
  fields: IndexedField[],
  weights: Map<string, number>,
  idfs: Map<string, number>,
  index: InvertedIndexStore,
): SearchSnippet[] {
  const texts = new Map(documentFields(doc).map((f) => [f.field, f.text]));
  const heap = new TopHeap<{
    field: IndexedField;
    start: number;
    end: number;
    score: number;
  }>(
    12,
    (a, b) =>
      b.score - a.score ||
      a.field.field.localeCompare(b.field.field) ||
      a.start - b.start,
  );
  for (const field of fields)
    for (const window of field.windows) {
      let score = 0;
      for (const [term, weight] of weights)
        if (window.tf.has(term))
          score +=
            weight *
            fieldWeight(field.field) *
            idfs.get(term)! *
            bm25(
              window.tf.get(term)!,
              window.length,
              index.averageFieldLength(field.field),
            );
      if (score)
        heap.offer({ field, start: window.start, end: window.end, score });
    }
  const out: SearchSnippet[] = [];
  for (const row of heap.sorted()) {
    if (
      out.some(
        (s) =>
          s.field === row.field.field && s.start < row.end && row.start < s.end,
      )
    )
      continue;
    const text = texts.get(row.field.field)!;
    const matching = row.field.tokens.filter(
      (t) => weights.has(t.term) && t.start >= row.start && t.end <= row.end,
    );
    const anchor = matching[0]!;
    const start = Math.max(row.start, anchor.start - 100),
      end = Math.min(row.end, start + 360);
    const matches = [
      ...new Map(
        matching
          .filter((t) => t.end <= end)
          .map((t) => [`${t.start}:${t.end}`, { start: t.start, end: t.end }]),
      ).values(),
    ];
    const pages =
      row.field.field === "content" && Array.isArray(doc.pageOffsets)
        ? (doc.pageOffsets as Array<{
            page: number;
            start: number;
            end: number;
          }>)
        : [];
    const page = pages.find(
      (p) => anchor.start >= p.start && anchor.start < p.end,
    )?.page;
    out.push({
      text: text.slice(start, end),
      field: row.field.field,
      start,
      end,
      matches,
      line: text.slice(0, anchor.start).split("\n").length,
      ...(page === undefined ? {} : { page }),
    });
    if (out.length === 3) break;
  }
  return out;
}
function phrasePassages(
  doc: Document,
  surfaces: TokenInfo[],
  phrases: string[],
): SearchSnippet[] {
  const texts = new Map(documentFields(doc).map((f) => [f.field, f.text]));
  const out: SearchSnippet[] = [];
  for (const phrase of phrases) {
    const words = surfaceTokens(phrase);
    if (!words.length) continue;
    const at = surfaces.findIndex((first, i) =>
      words.every(
        (word, j) =>
          surfaces[i + j]?.field === first.field &&
          surfaces[i + j]?.term === word.term &&
          surfaces[i + j]?.position === first.position + j,
      ),
    );
    if (at < 0) continue;
    const tokens = surfaces.slice(at, at + words.length),
      first = tokens[0]!,
      last = tokens[tokens.length - 1]!;
    const text = texts.get(first.field)!,
      start = Math.max(0, first.start - 80),
      end = Math.min(text.length, last.end + 100);
    if (
      out.some((s) => s.field === first.field && s.start < end && start < s.end)
    )
      continue;
    const pages =
      first.field === "content" && Array.isArray(doc.pageOffsets)
        ? (doc.pageOffsets as Array<{
            page: number;
            start: number;
            end: number;
          }>)
        : [];
    const page = pages.find(
      (p) => first.start >= p.start && first.start < p.end,
    )?.page;
    out.push({
      text: text.slice(start, end),
      field: first.field,
      start,
      end,
      matches: tokens.map((t) => ({ start: t.start, end: t.end })),
      line: text.slice(0, first.start).split("\n").length,
      ...(page === undefined ? {} : { page }),
    });
    if (out.length === 3) break;
  }
  return out;
}
function facetValues(
  ids: string[],
  docs: Map<string, Document>,
  key: string,
): Facet[] {
  const c = new Map<string, number>();
  for (const id of ids) {
    const v = docs.get(id)?.[key];
    if (v !== undefined) c.set(String(v), (c.get(String(v)) ?? 0) + 1);
  }
  return [...c]
    .map(([value, count]) => ({ value, count }))
    .sort((a, b) => b.count - a.count || a.value.localeCompare(b.value));
}
function facets(
  ids: string[],
  docs: Map<string, Document>,
): SearchResponse["facets"] {
  return {
    source: facetValues(ids, docs, "source"),
    repo: facetValues(ids, docs, "repo"),
    type: facetValues(ids, docs, "type"),
    language: facetValues(ids, docs, "language"),
  };
}
function groupCounts(
  ids: string[],
  docs: Map<string, Document>,
  by = "none",
): Array<{ key: string; count: number }> {
  if (by === "none") return [];
  const c = new Map<string, number>();
  for (const id of ids) {
    const k = String(docs.get(id)?.[by] ?? "");
    if (k) c.set(k, (c.get(k) ?? 0) + 1);
  }
  return [...c]
    .map(([key, count]) => ({ key, count }))
    .sort((a, b) => b.count - a.count || a.key.localeCompare(b.key));
}
function identity(doc: Document): string | undefined {
  if (typeof doc.sourceId === "string") return doc.sourceId;
  if (typeof doc.pageid === "number" && doc.source === "wikipedia")
    return `wikipedia:${doc.pageid}`;
  if (
    typeof doc.fullName === "string" &&
    typeof doc.path === "string" &&
    doc.source === "github"
  )
    return `github:${doc.fullName.toLowerCase()}:file:${doc.path}`;
  if (typeof doc.fullName === "string" && doc.source === "github")
    return `github:${doc.fullName.toLowerCase()}:repository`;
  return undefined;
}
function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => [k, canonical(v)]),
    );
  return value;
}
function hashDoc(doc: Document): string {
  return createHash("sha256")
    .update(JSON.stringify(canonical(doc)))
    .digest("hex");
}
function validateBackup(input: unknown): Array<{ id: string; doc: Document }> {
  validateJson(input, new Set());
  if (
    !input ||
    typeof input !== "object" ||
    (input as { version?: unknown }).version !== 1 ||
    !Array.isArray((input as { documents?: unknown }).documents)
  )
    throw new Error("invalid backup");
  const documents = (
    input as { documents: Array<{ id: string; doc: Document }> }
  ).documents;
  for (const item of documents) {
    if (
      !item ||
      typeof item !== "object" ||
      typeof item.id !== "string" ||
      !item.id ||
      item.id.includes("\n") ||
      item.id.length > 1024 ||
      !item.doc ||
      typeof item.doc !== "object" ||
      Array.isArray(item.doc)
    )
      throw new Error("invalid backup document");
  }
  return documents;
}
function validateJson(value: unknown, ancestors: Set<object>, depth = 0): void {
  if (depth > 100) throw new Error("backup nesting exceeds 100 levels");
  if (value === null || typeof value === "string" || typeof value === "boolean")
    return;
  if (typeof value === "number" && Number.isFinite(value)) return;
  if (
    !value ||
    typeof value !== "object" ||
    ancestors.has(value) ||
    (!Array.isArray(value) &&
      Object.getPrototypeOf(value) !== Object.prototype &&
      Object.getPrototypeOf(value) !== null)
  )
    throw new Error("backup must contain valid JSON values");
  ancestors.add(value);
  for (const child of Object.values(value))
    validateJson(child, ancestors, depth + 1);
  ancestors.delete(value);
}

import { createHash } from "node:crypto";
import { Worker } from "node:worker_threads";
import type { Engine } from "../engine.js";
import { extractDocuments, type ExtractOptions } from "../ingest/extract.js";

export type AsyncEngine = { [K in keyof Engine]: Engine[K] extends (...args: infer A) => infer R ? (...args: A) => Promise<Awaited<R>> : never };
export type RuntimeEngine = { [K in keyof Engine]: Engine[K] extends (...args: infer A) => infer R ? (...args: A) => R | Promise<Awaited<R>> : never };
export interface Extraction { extract(filename: string, buffer: Buffer, options?: ExtractOptions): ReturnType<typeof extractDocuments>; available(): boolean; hash(buffer: Buffer): Promise<string> }
export class WorkerUnavailable extends Error { readonly statusCode = 503; }

export async function startWorker(dataDir: string): Promise<AsyncEngine & Extraction> {
  const module = new URL("./worker.js", import.meta.url);
  const source = import.meta.url.endsWith(".ts");
  if (source) module.pathname = module.pathname.replace(/\.js$/, ".ts");
  const execArgv = process.execArgv.filter(arg => !arg.startsWith("--input-type"));
  const worker = source
    ? new Worker(`const { workerData } = require('node:worker_threads'); import('tsx/esm/api').then(({register}) => { register(); return import(workerData.module); }).catch(error => { throw error; });`, { eval: true, execArgv, workerData: { dataDir, module: module.href } })
    : new Worker(module, { execArgv, workerData: { dataDir } });
  let seq = 0;
  let failed: Error | undefined;
  let closing = false;
  const pending = new Map<number, { resolve(value: unknown): void; reject(error: Error): void }>();
  const fail = (error: Error) => {
    failed = new WorkerUnavailable(error.message);
    for (const call of pending.values()) call.reject(failed);
    pending.clear();
  };
  const ready = new Promise<void>((resolve, reject) => {
    pending.set(0, { resolve: () => resolve(), reject });
  });
  worker.on("message", (message: { id: number; result?: unknown; error?: string; statusCode?: number }) => {
    const call = pending.get(message.id);
    if (!call) return;
    pending.delete(message.id);
    if (message.error) call.reject(Object.assign(new Error(message.error), { statusCode: message.statusCode }));
    else call.resolve(message.result);
  });
  worker.on("error", fail);
  worker.on("exit", (code) => fail(new Error(`Engine worker stopped (${code})`)));
  try { await ready; } catch (error) { await worker.terminate(); throw error; }
  const invoke = (method: string, args: unknown[]): Promise<unknown> => {
    if (failed) return Promise.reject(failed);
    if (closing && method !== "close") return Promise.reject(new WorkerUnavailable("Engine is shutting down"));
    if (pending.size >= 32 && method !== "close") return Promise.reject(new WorkerUnavailable("Engine queue is full; retry later"));
    const id = ++seq;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      try { worker.postMessage({ id, method, args }); }
      catch (error) { pending.delete(id); reject(error); }
    });
  };
  return new Proxy({} as AsyncEngine & Extraction, {
    get: (_, method: string) => method === "then" ? undefined : method === "available" ? () => !failed && !closing : method === "close" ? async () => {
      if (closing) return;
      closing = true;
      try { await invoke("close", []); } finally { await worker.terminate(); }
    } : (...args: unknown[]) => invoke(method, args),
  });
}

export const inlineExtraction: Extraction = { extract: extractDocuments, available: () => true, hash: async buffer => createHash("sha256").update(buffer).digest("hex") };

import { createHash } from "node:crypto";
import { parentPort, workerData } from "node:worker_threads";
import { setImmediate as yieldTurn } from "node:timers/promises";
import { Engine } from "../engine.js";
import { extractDocuments, type ExtractOptions } from "../ingest/extract.js";
import type { Document } from "../types.js";

const port = parentPort!;
const engine = new Engine(workerData.dataDir);
process.on("uncaughtException", error => {
  try { engine.close(); } finally { throw error; }
});
const allowed = new Set([
  "addDocument", "addDocuments", "getDocument", "deleteDocument", "documentCount", "listDocuments", "collectBySource", "reset",
  "search", "naiveSearch", "benchmark", "suggest", "diagnostics", "compare", "ingestDocuments", "exportBackup", "restoreBackup",
  "compact", "snapshot", "close", "explainMissing", "rebuildIndex", "rebuildStatus", "cancelRebuild",
]);
let writing = false;
const waiting: Array<() => void> = [];
const reads = new Set(["documentCount", "getDocument", "listDocuments", "collectBySource", "search", "suggest", "diagnostics", "compare", "benchmark", "naiveSearch", "exportBackup", "explainMissing", "rebuildStatus", "cancelRebuild"]);

async function call(method: string, args: unknown[]): Promise<unknown> {
  if (method === "hash") return createHash("sha256").update(args[0] as Uint8Array).digest("hex");
  if (method === "extract") {
    const data = args[1] as Uint8Array;
    return extractDocuments(args[0] as string, Buffer.from(data.buffer, data.byteOffset, data.byteLength), args[2] as ExtractOptions | undefined);
  }
  if (!allowed.has(method)) throw new Error("Unknown engine method");
  const fn = (engine as unknown as Record<string, (...args: unknown[]) => unknown>)[method]!;
  if (method !== "addDocuments" && method !== "ingestDocuments") return fn.apply(engine, args);
  const docs = args[0] as Document[];
  const ids: string[] = [];
  let added = 0, updated = 0, duplicates = 0;
  for (let offset = 0; offset < docs.length; offset += 16) {
    const batch = docs.slice(offset, offset + 16);
    if (method === "addDocuments") ids.push(...engine.addDocuments(batch));
    else {
      const result = engine.ingestDocuments(batch);
      ids.push(...result.ids); added += result.added; updated += result.updated; duplicates += result.duplicates;
    }
    await yieldTurn();
  }
  return method === "addDocuments" ? ids : { ids, added, updated, duplicates };
}

port.on("message", (message: { id: number; method: string; args: unknown[] }) => {
  const run = async () => {
    const write = !reads.has(message.method) && message.method !== "extract" && message.method !== "hash";
    if (write) writing = true;
    try { port.postMessage({ id: message.id, result: await call(message.method, message.args) }); }
    catch (error) { port.postMessage({ id: message.id, error: error instanceof Error ? error.message : "Engine failed", statusCode: (error as { statusCode?: number }).statusCode }); }
    finally {
      if (write) { writing = false; waiting.shift()?.(); }
    }
  };
  if (writing && (!reads.has(message.method) && message.method !== "extract" && message.method !== "hash")) waiting.push(() => { void run(); });
  else void run();
});
port.postMessage({ id: 0 });

import Fastify from "fastify";
import cors from "@fastify/cors";
import multipart from "@fastify/multipart";
import { Engine } from "../engine.js";
import { registerRoutes } from "./routes.js";
import { IngestJobs } from "../ingest/jobs.js";
import { DemoRuntime } from "../runtime/demo.js";
import { FolderSources } from "../ingest/folders.js";
import { startWorker, inlineExtraction, type AsyncEngine, type Extraction } from "../runtime/engine.js";
import type { FastifyInstance } from "fastify";
import { dataPaths } from "../config.js";

export function buildServer(dataDir: string | undefined, options: { worker: true }): Promise<{ app: FastifyInstance; engine: AsyncEngine & Extraction }>;
export function buildServer(dataDir?: string, options?: { worker?: false }): Promise<{ app: FastifyInstance; engine: Engine }>;
export async function buildServer(dataDir?: string, options: { worker?: boolean } = {}): Promise<{ app: FastifyInstance; engine: Engine | (AsyncEngine & Extraction) }> {
  const app = Fastify({ logger: false, bodyLimit: 64 * 1024 * 1024 });
  await app.register(cors, { origin: (origin, callback) => callback(null, !origin || allowedOrigin(origin)) });
  app.addHook("onRequest", async (request, reply) => {
    if (!["GET", "HEAD", "OPTIONS"].includes(request.method) && request.headers.origin && !allowedOrigin(request.headers.origin)) {
      return reply.code(403).send({ error: "origin is not allowed" });
    }
  });
  // File uploads (PDFs, text, code) stream through here; 64 MB per file.
  await app.register(multipart, {
    limits: { fileSize: 64 * 1024 * 1024, files: 200 },
  });

  const engine = options.worker ? await startWorker(dataPaths(dataDir).dataDir) : new Engine(dataDir);
  const extraction = options.worker ? engine as AsyncEngine & Extraction : inlineExtraction;
  let jobs: IngestJobs;
  let folders: FolderSources;
  try {
    jobs = new IngestJobs(engine, dataPaths(dataDir).dataDir);
    folders = new FolderSources(engine, extraction, dataPaths(dataDir).dataDir);
  } catch (error) { await engine.close(); throw error; }
  const demo = new DemoRuntime();
  registerRoutes(app, engine, jobs, folders, extraction, demo);

  // Flush snapshots and close fds cleanly on shutdown.
  app.addHook("onClose", async () => {
    try { await Promise.all([jobs.close(), folders.close(), demo.close()]); } finally { await engine.close(); }
  });

  return { app, engine };
}

function allowedOrigin(origin: string): boolean {
  try {
    const url = new URL(origin);
    return ["http:", "https:"].includes(url.protocol) && (["localhost", "127.0.0.1", "[::1]"].includes(url.hostname) || origin === process.env.SHARDLY_ALLOWED_ORIGIN);
  } catch { return false; }
}

/** Entry point when run directly (npm run dev / start). */
async function main() {
  const port = Number.parseInt(process.env.PORT ?? "3001", 10);
  const host = process.env.HOST ?? "127.0.0.1";
  const { app, engine } = await buildServer(undefined, { worker: true });

  const shutdown = async () => {
    await app.close();
    process.exit(0);
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);

  await app.listen({ port, host });
  console.log(
    `Shardly API listening on http://${host}:${port}  (${await engine.documentCount()} docs indexed)`,
  );
}

// Run only when invoked as the entry module, not when imported by tests.
const isMain = process.argv[1]?.endsWith("server.ts") || process.argv[1]?.endsWith("server.js");
if (isMain) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

import type { Document } from "../types.js";

export class InputError extends Error {
  readonly statusCode = 400;
}

export function object(value: unknown, label = "body"): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new InputError(`${label} must be a JSON object`);
  }
  return value as Record<string, unknown>;
}

export function documents(value: unknown): Document[] {
  if (!Array.isArray(value) || value.length > 10_000) {
    throw new InputError("documents must be an array of at most 10000 objects");
  }
  for (const doc of value) {
    object(doc, "document");
    validateJson(doc, 0);
  }
  return value as Document[];
}

function validateJson(value: unknown, depth: number): void {
  if (depth > 64) throw new InputError("document nesting exceeds 64 levels");
  if (value !== null && typeof value === "object") {
    for (const child of Object.values(value)) validateJson(child, depth + 1);
  } else if (typeof value === "number" && !Number.isFinite(value)) {
    throw new InputError("document numbers must be finite");
  } else if (!["string", "number", "boolean"].includes(typeof value) && value !== null) {
    throw new InputError("documents must contain JSON values");
  }
}

export function text(value: unknown, label: string, max = 2000): string {
  if (typeof value !== "string" || !value.trim() || value.length > max) {
    throw new InputError(`${label} must be a nonempty string of at most ${max} characters`);
  }
  return value.trim();
}

export function queryText(value: unknown, label = "query", max = 2000): string {
  if (typeof value !== "string" || value.length === 0 || value.length > max) {
    throw new InputError(`${label} must be a nonempty string of at most ${max} characters`);
  }
  return value;
}

export function optionalText(value: unknown, label: string, max = 256): string | undefined {
  return value === undefined ? undefined : text(value, label, max);
}

export function flag(value: unknown, label: string): boolean | undefined {
  if (value === undefined) return undefined;
  if (value === true || value === "true") return true;
  if (value === false || value === "false") return false;
  throw new InputError(`${label} must be true or false`);
}

export function integer(value: unknown, label: string, fallback: number, min: number, max: number): number {
  if (value === undefined) return fallback;
  const n = typeof value === "number" ? value : typeof value === "string" && /^\d+$/.test(value) ? Number(value) : NaN;
  if (!Number.isSafeInteger(n) || n < min || n > max) {
    throw new InputError(`${label} must be an integer between ${min} and ${max}`);
  }
  return n;
}

export function choice<T extends string>(value: unknown, label: string, choices: readonly T[]): T | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string" || !choices.includes(value as T)) {
    throw new InputError(`${label} must be one of ${choices.join(", ")}`);
  }
  return value as T;
}

export function synonyms(value: unknown): Record<string, string[]> | undefined {
  if (value === undefined) return undefined;
  if (typeof value === "string") {
    if (value.length > 8000) throw new InputError("synonyms are too large");
    try { value = JSON.parse(value); } catch { throw new InputError("synonyms must be valid JSON"); }
  }
  const entries = Object.entries(object(value, "synonyms"));
  if (entries.length > 32) throw new InputError("at most 32 synonym mappings are allowed");
  const result: Record<string, string[]> = Object.create(null);
  for (const [term, aliases] of entries) {
    text(term, "synonym term", 80);
    if (!Array.isArray(aliases) || aliases.length > 8) throw new InputError("each synonym accepts at most 8 alternatives");
    result[term] = aliases.map((alias) => text(alias, "synonym alternative", 80));
  }
  return result;
}

import { PassThrough } from "node:stream";
import type { FastifyInstance } from "fastify";
import type { RuntimeEngine, Extraction } from "../runtime/engine.js";
import type { DemoRuntime } from "../runtime/demo.js";
import type { FolderSources } from "../ingest/folders.js";
import type { Document, SearchOptions } from "../types.js";
import { fetchGithubDocuments } from "../ingest/github.js";
import { countCorpus } from "../ingest/corpus.js";
import type { IngestJobs } from "../ingest/jobs.js";
import { InputError, object, documents, text, queryText, optionalText, flag, integer, choice, synonyms } from "./validation.js";

interface IdParam {
  id: string;
}

interface SearchQuery {
  q?: string;
  limit?: string;
  [key: string]: unknown;
}

interface ListQuery {
  offset?: string;
  limit?: string;
}

function previewDoc(doc: Document, maxLen = 280): Document {
  let truncated = false;

  const trim = (value: unknown): unknown => {
    if (typeof value === "string" && value.length > maxLen) {
      truncated = true;
      return value.slice(0, maxLen).trimEnd() + "\u2026";
    }
    if (Array.isArray(value)) return value.map(trim);
    if (value !== null && typeof value === "object") {
      const out: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(value)) out[k] = trim(v);
      return out;
    }
    return value;
  };

  const out = trim(doc) as Record<string, unknown>;
  if (truncated) out._truncated = true;
  return out;
}

export function registerRoutes(app: FastifyInstance, engine: RuntimeEngine, jobs: IngestJobs, folders: FolderSources, extraction: Extraction, demo: DemoRuntime): void {
  app.get("/health", async (req, reply) => {
    void req;
    return extraction.available() ? { status: "ok" } : reply.code(503).send({ status: "unavailable" });
  });

  app.get("/stats", async () => ({ documents: await engine.documentCount() }));

  app.post<{ Body: Document }>("/documents", async (req, reply) => {
    const body = documents([req.body])[0]!;
    const id = await engine.addDocument(body);
    return reply.code(201).send({ id });
  });

  app.post<{ Body: Document[] }>("/documents/bulk", async (req, reply) => {
    const body = documents(req.body);
    const ids = await engine.addDocuments(body);
    return reply.code(201).send({ ids, count: ids.length });
  });

  app.post("/documents/upload", async (req, reply) => {
    if (!req.isMultipart()) {
      return reply.code(400).send({ error: "expected a multipart upload" });
    }
    const results: Array<{
      filename: string;
      status: "indexed" | "skipped";
      reason?: string;
      documents: number;
      added?: number;
      updated?: number;
      duplicates?: number;
    }> = [];

    for await (const part of req.parts()) {
      if (part.type !== "file") continue;
      const buffer = await part.toBuffer();
      const extracted = await extraction.extract(part.filename, buffer);
      const ingestion = extracted.docs.length > 0 ? await engine.ingestDocuments(
        extracted.docs.map((doc, ordinal) => ({ ...doc, source: "upload", sourceId: `upload:${part.filename}:${ordinal}` })),
      ) : undefined;
      results.push({
        filename: extracted.filename,
        status: extracted.status,
        reason: extracted.reason,
        documents: extracted.docs.length,
        ...ingestion,
      });
    }

    const indexed = results.reduce((s, r) => s + r.documents, 0);
    return reply
      .code(201)
      .send({ results, indexed, documents: await engine.documentCount() });
  });

  app.post<{
    Body: { user?: string; token?: string; deep?: boolean };
  }>("/ingest/github", async (req, reply) => {
    const body = object(req.body);
    const user = text(body.user, "GitHub target", 256);
    const token = optionalText(body.token, "GitHub token", 512);
    const deep = flag(body.deep, "deep") ?? false;
    try {
      const { docs, summary } = await fetchGithubDocuments({
        user: user.trim(),
        token: token?.trim() || undefined,
        deep: Boolean(deep),
      });
      const ingestion = await engine.ingestDocuments(docs);
      return reply
        .code(201)
        .send({ ...summary, ingestion, totalDocuments: await engine.documentCount() });
    } catch (e) {
      return reply
        .code(400)
        .send({ error: token ? (e instanceof Error ? e.message : "GitHub indexing failed").replaceAll(token, "[redacted]") : e instanceof Error ? e.message : "GitHub indexing failed" });
    }
  });

  app.get("/corpus/wikipedia/status", async () => ({
    available: await countCorpus(),
    indexed: (await engine.collectBySource("wikipedia")).length,
  }));

  app.post("/corpus/wikipedia/index", async (reqIgnored, reply) => {
    void reqIgnored;
    const job = jobs.create({ kind: "wikipedia" });
    reply.header("content-type", "application/x-ndjson");
    reply.header("cache-control", "no-cache");
    const stream = new PassThrough();
    const timer = setInterval(async () => {
      const current = jobs.get(job.id)!;
      stream.write(JSON.stringify({ type: "progress", indexed: current.progress.indexed, total: current.progress.total }) + "\n");
      if (["completed", "failed", "cancelled", "interrupted"].includes(current.status)) {
        clearInterval(timer);
        stream.end(JSON.stringify(current.status === "completed"
          ? { type: "done", indexed: current.progress.indexed, documents: await engine.documentCount() }
          : { type: "error", error: current.error ?? "Import stopped" }) + "\n");
      }
    }, 100);
    stream.on("close", () => { clearInterval(timer); jobs.cancel(job.id); });

    return reply.send(stream);
  });

  app.post("/corpus/wikipedia/deindex", async () => {
    if (jobs.busy() || folders.busy()) throw new InputError("cancel active imports before removing the corpus");
    const targets = await engine.collectBySource("wikipedia");
    let removed = 0;
    for (const t of targets) if (await engine.deleteDocument(t.id)) removed++;
    await engine.snapshot();
    return { removed, documents: await engine.documentCount() };
  });

  app.post("/compact", async () => ({
    ...await engine.compact(),
    documents: await engine.documentCount(),
  }));

  app.post("/reset", async (req, reply) => {
    void req;
    if (folders.list().some(source => !source.paused)) return reply.code(400).send({ error: "pause folder sources before resetting the store" });
    if (jobs.busy() || folders.busy()) throw new InputError("cancel active imports before resetting the store");
    await engine.reset();
    return { ok: true, documents: 0 };
  });

  app.get<{ Querystring: ListQuery }>("/documents", async (req) => {
    const offset = integer(req.query.offset, "offset", 0, 0, 100_000);
    const limit = integer(req.query.limit, "limit", 50, 1, 200);
    const { total, items } = await engine.listDocuments(offset, limit);
    return {
      total,
      offset,
      limit,
      items: items.map((it) => ({ id: it.id, doc: previewDoc(it.doc) })),
    };
  });

  // O(1) lookup by id — returns the FULL document for the detail view.
  app.get<{ Params: IdParam }>("/documents/:id", async (req, reply) => {
    const doc = await engine.getDocument(req.params.id);
    if (doc === null) return reply.code(404).send({ error: "not found" });
    return { id: req.params.id, doc };
  });

  app.delete<{ Params: IdParam }>("/documents/:id", async (req, reply) => {
    const ok = await engine.deleteDocument(req.params.id);
    if (!ok) return reply.code(404).send({ error: "not found" });
    return reply.code(204).send();
  });

  app.get<{ Querystring: SearchQuery }>("/search", async (req, reply) => {
    const q = queryText(req.query.q, "query parameter 'q'");
    const result = await engine.search(q, searchOptions(req.query));
    return {
      ...result,
      hits: result.hits.map((h) => ({ ...h, doc: previewDoc(h.doc) })),
    };
  });

  app.get<{ Querystring: SearchQuery }>("/suggest", async (req) => ({
    suggestions: await engine.suggest(text(req.query.q, "query parameter 'q'", 80), integer(req.query.limit, "limit", 8, 1, 20)),
  }));

  app.get<{ Querystring: { term?: string } }>("/diagnostics", async (req) => await engine.diagnostics(optionalText(req.query.term, "term", 80)));

  app.post("/search/compare", async (req) => {
    const body = object(req.body);
    const result = await engine.compare(queryText(body.query), searchOptions(body.options === undefined ? {} : object(body.options, "options")));
    return {
      ...result,
      baseline: { ...result.baseline, hits: result.baseline.hits.map((hit) => ({ ...hit, doc: previewDoc(hit.doc) })) },
      tuned: { ...result.tuned, hits: result.tuned.hits.map((hit) => ({ ...hit, doc: previewDoc(hit.doc) })) },
    };
  });

  app.post("/search/explain-missing", async (req) => {
    const body = object(req.body);
    return engine.explainMissing(queryText(body.query), text(body.id, "document id", 128), searchOptions(body.options === undefined ? {} : object(body.options, "options")));
  });
  app.get("/maintenance/rebuild", async () => engine.rebuildStatus());
  app.post("/maintenance/rebuild", async (req, reply) => {
    void req;
    const status = await engine.rebuildStatus();
    if (status.state !== "running") void Promise.resolve(engine.rebuildIndex()).catch(error => app.log.error(error));
    return reply.code(202).send(await engine.rebuildStatus());
  });
  app.delete("/maintenance/rebuild", async () => ({ cancelled: await engine.cancelRebuild() }));
  app.post("/maintenance/rebuild/cancel", async () => ({ cancelled: await engine.cancelRebuild() }));

  app.get("/backup", async (req, reply) => {
    void req;
    reply.header("content-disposition", 'attachment; filename="shardly-backup.json"');
    reply.header("cache-control", "no-store");
    return await engine.exportBackup();
  });

  app.post("/backup", async (req) => {
    if (jobs.busy() || folders.busy()) throw new InputError("cancel active imports before restoring a backup");
    const body = object(req.body);
    const backup = object(body.backup, "backup");
    if (backup.version !== 1 || !Array.isArray(backup.documents)) throw new InputError("unsupported backup format");
    if (backup.documents.length > 100_000) throw new InputError("backup exceeds 100000 documents");
    const ids = new Set<string>();
    for (const entry of backup.documents) {
      const record = object(entry, "backup entry");
      const id = text(record.id, "backup document id", 128);
      if (!/^[a-zA-Z0-9_-]+$/.test(id) || ids.has(id)) throw new InputError("backup contains an invalid or duplicate document id");
      ids.add(id);
      documents([record.doc]);
    }
    return await engine.restoreBackup(backup);
  });

  app.get("/jobs", async () => ({ jobs: jobs.list() }));
  app.post("/jobs", async (req, reply) => reply.code(202).send(jobs.create(req.body)));
  app.get<{ Params: IdParam }>("/jobs/:id", async (req, reply) => jobs.get(req.params.id) ?? reply.code(404).send({ error: "job not found" }));
  app.post<{ Params: IdParam }>("/jobs/:id/cancel", async (req, reply) => jobs.cancel(req.params.id) ?? reply.code(404).send({ error: "job not found" }));
  app.post<{ Params: IdParam }>("/jobs/:id/retry", async (req, reply) => {
    const body = req.body === undefined ? {} : object(req.body);
    const job = jobs.retry(req.params.id, optionalText(body.token, "GitHub token", 512));
    return job ? reply.code(202).send(job) : reply.code(404).send({ error: "job not found" });
  });

  app.post("/demo/seed", async () => demo.seed());
  app.post("/demo/import", async () => demo.import());
  app.post("/demo/durability", async () => demo.durability());
  app.get<{ Querystring: SearchQuery }>("/demo/search", async (req) => {
    const selected = await demo.ready();
    const result = await selected.search(queryText(req.query.q), { ...searchOptions(req.query), source: "demo" });
    return { ...result, hits: result.hits.map(hit => ({ ...hit, doc: previewDoc(hit.doc) })) };
  });
  const compareDemo = async (input: unknown) => {
    const body = object(input);
    const selected = await demo.ready();
    const result = await selected.compare(queryText(body.query), { ...searchOptions(body.options === undefined ? {} : object(body.options, "options")), source: "demo" });
    return {
      ...result,
      baseline: { ...result.baseline, hits: result.baseline.hits.map(hit => ({ ...hit, doc: previewDoc(hit.doc) })) },
      tuned: { ...result.tuned, hits: result.tuned.hits.map(hit => ({ ...hit, doc: previewDoc(hit.doc) })) },
    };
  };
  app.post("/demo/compare", async (req) => compareDemo(req.body));
  app.post("/demo/search/compare", async (req) => compareDemo(req.body));

  app.get("/sources/folders", async () => ({ sources: folders.list() }));
  app.post("/sources/folders", async (req, reply) => {
    const body = object(req.body);
    return reply.code(202).send(await folders.create(text(body.path, "folder path", 4096)));
  });
  app.get<{ Params: IdParam }>("/sources/folders/:id", async (req, reply) => folders.get(req.params.id) ?? reply.code(404).send({ error: "folder source not found" }));
  for (const action of ["pause", "resume", "rescan"] as const) {
    app.post<{ Params: IdParam }>(`/sources/folders/:id/${action}`, async (req, reply) => {
      const source = await folders.action(req.params.id, action);
      return source ? reply.code(action === "pause" ? 200 : 202).send(source) : reply.code(404).send({ error: "folder source not found" });
    });
  }
  app.delete<{ Params: IdParam }>("/sources/folders/:id", async (req, reply) => {
    const result = await folders.remove(req.params.id);
    return result ?? reply.code(404).send({ error: "folder source not found" });
  });

  // Indexed search vs naive linear scan, timed side by side.
  app.get<{ Querystring: SearchQuery }>("/benchmark", async (req, reply) => {
    const q = queryText(req.query.q, "query parameter 'q'");
    return await engine.benchmark(q, integer(req.query.limit, "limit", 10, 1, 100));
  });
}

function searchOptions(input: Record<string, unknown>): SearchOptions {
  let docIds: unknown = input.docIds;
  if (typeof docIds === "string") docIds = docIds.length ? docIds.split(",") : [];
  if (docIds !== undefined && (!Array.isArray(docIds) || docIds.length > 1000 || docIds.some((id) => typeof id !== "string" || id.length > 128))) {
    throw new InputError("docIds must contain at most 1000 document ids");
  }
  return {
    limit: integer(input.limit, "limit", 10, 1, 100),
    offset: integer(input.offset, "offset", 0, 0, 100_000),
    mode: choice(input.mode, "mode", ["all", "any"]),
    groupBy: choice(input.groupBy, "groupBy", ["none", "repo", "source"]),
    match: choice(input.match, "match", ["text", "literal", "substring"]),
    profile: choice(input.profile, "profile", ["baseline", "tuned"]),
    source: optionalText(input.source, "source"), repo: optionalText(input.repo, "repo"),
    type: optionalText(input.type, "type"), language: optionalText(input.language, "language"),
    docIds: docIds as string[] | undefined,
    prefix: flag(input.prefix, "prefix"), typos: flag(input.typos, "typos"), inspect: flag(input.inspect, "inspect"),
    synonyms: synonyms(input.synonyms),
  };
}

import fs from "node:fs";
import { promises as fsp, constants } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { RuntimeEngine, Extraction } from "../runtime/engine.js";
import { TEXT_EXTENSIONS, extensionOf, type ExtractResult } from "./extract.js";
import { InputError } from "../api/validation.js";

const exec = promisify(execFile);
const MAX_STAGED_BYTES = 256 * 1024 * 1024;
interface FileRecord { hash: string; ids: string[]; size?: number; mtimeMs?: number; ctimeMs?: number }
export interface FolderSource {
  id: string; path: string; status: "idle" | "syncing" | "paused" | "error"; paused: boolean;
  createdAt: string; lastSyncedAt?: string; error?: string; ignoreMode: "git" | "safe-fallback";
  progress: { scanned: number; indexed: number; removed: number }; files: number;
}
interface SavedSource extends FolderSource { records: Record<string, FileRecord> }

export class FolderSources {
  private readonly sources = new Map<string, SavedSource>();
  private readonly active = new Map<string, { controller: AbortController; promise: Promise<void> }>();
  private readonly file: string;
  private readonly gitDir: string;
  private timer: NodeJS.Timeout;
  private closed = false;
  private persistenceError = false;
  private gitReady?: Promise<boolean>;
  private readonly recovered = new Set<string>();
  private readonly removing = new Set<string>();

  constructor(private readonly engine: RuntimeEngine, private readonly extraction: Extraction, dataDir: string) {
    this.file = path.join(dataDir, "folders.json");
    this.gitDir = path.join(dataDir, "folder-ignore.git");
    if (fs.existsSync(this.file)) {
      const saved: unknown = JSON.parse(fs.readFileSync(this.file, "utf8"));
      if (!Array.isArray(saved) || saved.length > 20) throw new Error("Invalid folder sources");
      for (const source of saved as SavedSource[]) {
        if (!source || !/^[a-z0-9-]{36}$/.test(source.id) || !path.isAbsolute(source.path) || typeof source.paused !== "boolean" || !source.records || typeof source.records !== "object" || Array.isArray(source.records)) throw new Error("Invalid folder source");
        for (const [relative, record] of Object.entries(source.records)) {
          if (!safeRelative(relative) || !record || typeof record.hash !== "string" || !Array.isArray(record.ids) || record.ids.some(id => typeof id !== "string")) throw new Error("Invalid folder file record");
        }
        source.status = source.paused ? "paused" : "idle";
        source.progress = { scanned: 0, indexed: 0, removed: 0 };
        source.files = Object.keys(source.records).length;
        this.sources.set(source.id, source);
      }
    }
    this.timer = setInterval(() => {
      if (this.closed || this.persistenceError) return;
      for (const source of this.sources.values()) if (!source.paused) this.start(source);
    }, 2000);
    this.timer.unref();
    setImmediate(() => { for (const source of this.sources.values()) if (!source.paused) this.start(source); });
  }

  list(): FolderSource[] { return [...this.sources.values()].map(source => this.public(source)); }
  get(id: string): FolderSource | undefined { const source = this.sources.get(id); return source && this.public(source); }
  busy(): boolean { return this.active.size > 0; }
  private public({ records, ...source }: SavedSource): FolderSource { void records; return { ...source, progress: { ...source.progress } }; }

  async create(root: string): Promise<FolderSource> {
    this.writable();
    if (!path.isAbsolute(root)) throw new InputError("folder path must be absolute");
    let canonical: string;
    try { canonical = await fsp.realpath(root); if (!(await fsp.stat(canonical)).isDirectory()) throw new Error(); }
    catch { throw new InputError("folder path must be an existing readable directory"); }
    if (this.sources.size >= 20) throw new InputError("at most 20 folder sources are allowed");
    if ([...this.sources.values()].some(source => source.path === canonical)) throw new InputError("folder is already managed");
    const source: SavedSource = { id: randomUUID(), path: canonical, createdAt: new Date().toISOString(), status: "idle", paused: false, ignoreMode: "safe-fallback", progress: { scanned: 0, indexed: 0, removed: 0 }, files: 0, records: Object.create(null) };
    this.sources.set(source.id, source);
    try { this.persist(); } catch (error) { this.sources.delete(source.id); throw error; }
    this.start(source);
    return this.public(source);
  }

  async action(id: string, action: "pause" | "resume" | "rescan"): Promise<FolderSource | undefined> {
    this.writable();
    const source = this.sources.get(id);
    if (!source) return;
    if (this.removing.has(id)) throw new InputError("folder source is being removed");
    if (action === "pause") {
      source.paused = true;
      this.active.get(id)?.controller.abort();
      await this.active.get(id)?.promise;
      source.status = "paused";
      this.persist();
    } else {
      if (action === "resume") source.paused = false;
      this.persist();
      this.start(source, action === "rescan");
    }
    return this.public(source);
  }

  async remove(id: string): Promise<{ removed: number } | undefined> {
    this.writable();
    const source = this.sources.get(id);
    if (!source) return;
    if (this.removing.has(id)) throw new InputError("folder source is being removed");
    this.removing.add(id);
    try {
      source.paused = true;
      this.active.get(id)?.controller.abort();
      await this.active.get(id)?.promise;
      let removed = 0;
      for (const { id: docId } of await this.engine.collectBySource("folder")) if (await this.deleteOwned(source, docId)) removed++;
      await this.engine.snapshot();
      this.sources.delete(id);
      try { this.persist(); } catch (error) { this.sources.set(id, source); throw error; }
      return { removed };
    } finally { this.removing.delete(id); }
  }

  async close(): Promise<void> {
    this.closed = true;
    clearInterval(this.timer);
    for (const active of this.active.values()) active.controller.abort();
    await Promise.all([...this.active.values()].map(active => active.promise));
    this.persist();
  }

  private writable(): void {
    if (this.closed) throw new InputError("folder sources are shutting down");
    if (this.persistenceError) throw new Error("Cannot save folder sources; check disk space and restart");
  }

  private start(source: SavedSource, force = false): void {
    if (this.closed || this.persistenceError || this.active.has(source.id) || this.removing.has(source.id)) return;
    const controller = new AbortController();
    const promise = this.sync(source, controller.signal, force).catch(error => {
      source.status = source.paused ? "paused" : "error";
      if (!controller.signal.aborted) source.error = error instanceof Error ? error.message : "Folder sync failed";
    }).finally(() => {
      this.active.delete(source.id);
      try { this.persist(); } catch { this.persistenceError = true; source.status = "error"; source.error = "Cannot save folder sources; check disk space and restart"; }
    });
    this.active.set(source.id, { controller, promise });
  }

  private async gitAvailable(): Promise<boolean> {
    const ready = await (this.gitReady ??= exec("git", ["init", "--bare", "--quiet", this.gitDir]).then(() => true, () => false));
    if (!ready) this.gitReady = undefined;
    return ready;
  }

  private async sync(source: SavedSource, signal: AbortSignal, force: boolean): Promise<void> {
    source.status = "syncing";
    source.error = undefined;
    source.progress = { scanned: 0, indexed: 0, removed: 0 };
    if (await fsp.realpath(source.path) !== source.path || (await fsp.lstat(source.path)).isSymbolicLink()) throw new Error("Folder root changed; select it again");
    const git = await this.gitAvailable();
    source.ignoreMode = git ? "git" : "safe-fallback";
    const candidates: string[] = [];
    const walk = async (dir: string): Promise<void> => {
      signal.throwIfAborted();
      const canonical = await fsp.realpath(dir);
      if ((canonical !== source.path && !canonical.startsWith(source.path + path.sep)) || canonical !== dir || (await fsp.lstat(dir)).isSymbolicLink()) throw new Error("Folder directory changed or escaped selected root");
      const handle = await fsp.open(dir, constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW);
      let entries;
      try {
        const actual = await fsp.realpath(process.platform === "linux" ? `/proc/self/fd/${handle.fd}` : dir);
        if (actual !== dir) throw new Error("Folder directory changed during scan");
        entries = await fsp.readdir(process.platform === "linux" ? `/proc/self/fd/${handle.fd}` : dir, { withFileTypes: true });
      } finally { await handle.close(); }
      const directories = entries.filter(entry => entry.isDirectory() && entry.name !== ".git").map(entry => path.relative(source.path, path.join(dir, entry.name)).split(path.sep).join("/") + "/");
      const ignoredDirectories = git ? await this.ignored(source, directories) : new Set<string>();
      for (const entry of entries) {
        if (entry.isSymbolicLink() || entry.name === ".git") continue;
        const full = path.join(dir, entry.name);
        if (!git && entry.name === ".gitignore") throw new Error("Git unavailable; folder with .gitignore cannot be synced safely. Install Git and rescan.");
        if (entry.isDirectory() && !ignoredDirectories.has(path.relative(source.path, full).split(path.sep).join("/") + "/")) await walk(full);
        else if (entry.isFile() && (TEXT_EXTENSIONS.has(extensionOf(entry.name)) || extensionOf(entry.name) === "pdf")) candidates.push(path.relative(source.path, full).split(path.sep).join("/"));
        if (candidates.length > 10_000) throw new Error("Folder exceeds 10000 supported files; choose a smaller folder");
      }
    };
    await walk(source.path);
    const ignored = git ? await this.ignored(source, candidates) : new Set<string>();
    if (!this.recovered.has(source.id)) {
      // Reconcile writes acknowledged before a crash or failed metadata save.
      for (const { id } of await this.engine.collectBySource("folder")) {
        const doc = await this.engine.getDocument(id);
        if (doc?.folderId !== source.id || typeof doc.path !== "string" || !safeRelative(doc.path) || typeof doc.sourceId !== "string" || !doc.sourceId.startsWith(`folder:${source.id}:`)) continue;
        const record = source.records[doc.path] ??= { hash: "", ids: [] };
        if (!record.ids.includes(id)) record.ids.push(id);
      }
      this.recovered.add(source.id);
    }
    const seen = new Set<string>();
    let stagedBytes = 0;
    const pending: Array<{ relative: string; hash: string; stat: fs.Stats; extracted: ExtractResult }> = [];
    for (const relative of candidates) {
      signal.throwIfAborted();
      if (ignored.has(relative)) continue;
      seen.add(relative);
      const old = source.records[relative];
      const stat = await fsp.lstat(path.join(source.path, relative));
      if (!stat.isFile() || stat.isSymbolicLink()) throw new Error("Folder file changed during scan");
      source.progress.scanned++;
      let owned = !!old;
      for (const id of old?.ids ?? []) {
        const doc = await this.engine.getDocument(id);
        if (doc?.source !== "folder" || doc.folderId !== source.id || doc.path !== relative) { owned = false; break; }
      }
      if (!force && owned && old?.size === stat.size && old.mtimeMs === stat.mtimeMs && old.ctimeMs === stat.ctimeMs) continue;
      // Reserve input plus UTF-16 extraction before allocating either.
      if (stagedBytes + stat.size * 3 > MAX_STAGED_BYTES) throw new Error("Folder changed-file extraction exceeds 256 MiB staging budget; sync a smaller folder");
      const buffer = await readContained(source.path, relative);
      if (stagedBytes + buffer.length * 3 > MAX_STAGED_BYTES) throw new Error("Folder changed-file extraction exceeds 256 MiB staging budget; sync a smaller folder");
      const hash = await this.extraction.hash(buffer);
      if (!force && owned && old?.hash === hash) {
        Object.assign(old, { size: stat.size, mtimeMs: stat.mtimeMs, ctimeMs: stat.ctimeMs });
        continue;
      }
      const extracted = await this.extraction.extract(relative, buffer, { strictStructured: true });
      signal.throwIfAborted();
      if (extracted.status === "skipped" && extracted.reason !== "empty file" && !extracted.reason?.startsWith("unsupported binary") && !extracted.reason?.startsWith("no extractable text")) throw new Error(`${relative}: ${extracted.reason}`);
      stagedBytes += Math.max(stat.size * 3, buffer.length + JSON.stringify(extracted.docs).length * 2);
      if (stagedBytes > MAX_STAGED_BYTES) throw new Error("Folder changed-file extraction exceeds 256 MiB staging budget; sync a smaller folder");
      pending.push({ relative, hash, stat, extracted });
    }
    // Validate every changed file before reconciling documents from this scan.
    for (const { relative, hash, stat, extracted } of pending) {
      signal.throwIfAborted();
      const old = source.records[relative];
      // shortcut: JSON records use ordinal identities; use record keys if stable identity across array reordering is needed.
      const result = await this.engine.ingestDocuments(extracted.docs.map((doc, ordinal) => ({ ...doc, source: "folder", folderId: source.id, path: relative, sourceId: `folder:${source.id}:${relative}:${ordinal}` })));
      source.records[relative] = { hash, ids: result.ids, size: stat.size, mtimeMs: stat.mtimeMs, ctimeMs: stat.ctimeMs };
      for (const id of old?.ids ?? []) if (!result.ids.includes(id) && await this.deleteOwned(source, id)) source.progress.removed++;
      source.progress.indexed += result.added + result.updated;
      this.persist();
    }
    // Deletions happen only after a complete successful scan.
    signal.throwIfAborted();
    for (const relative of Object.keys(source.records)) {
      if (seen.has(relative)) continue;
      for (const id of source.records[relative]!.ids) if (await this.deleteOwned(source, id)) source.progress.removed++;
      delete source.records[relative];
    }
    source.files = Object.keys(source.records).length;
    source.lastSyncedAt = new Date().toISOString();
    source.status = source.paused ? "paused" : "idle";
  }

  private async ignored(source: SavedSource, files: string[]): Promise<Set<string>> {
    const ignored = new Set<string>();
    for (let offset = 0; offset < files.length; offset += 128) {
      const batch = files.slice(offset, offset + 128);
      const output = await new Promise<string>((resolve, reject) => {
        const child = execFile("git", ["-c", "core.bare=false", "-c", "core.excludesFile=/dev/null", `--git-dir=${this.gitDir}`, `--work-tree=${source.path}`, "check-ignore", "--no-index", "-z", "--stdin"], { cwd: source.path, maxBuffer: 1024 * 1024 }, (error, stdout) => error && error.code !== 1 ? reject(new Error("Cannot evaluate folder .gitignore rules")) : resolve(stdout));
        child.stdin!.end(batch.join("\0") + "\0");
      });
      for (const file of output.split("\0").filter(Boolean)) ignored.add(file);
    }
    return ignored;
  }

  private async deleteOwned(source: SavedSource, id: string): Promise<boolean> {
    const doc = await this.engine.getDocument(id);
    return doc?.source === "folder" && doc.folderId === source.id && typeof doc.sourceId === "string" && doc.sourceId.startsWith(`folder:${source.id}:`) ? this.engine.deleteDocument(id) : false;
  }

  private persist(): void {
    const fd = fs.openSync(`${this.file}.tmp`, "w", 0o600);
    try { fs.writeFileSync(fd, JSON.stringify([...this.sources.values()])); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
    fs.renameSync(`${this.file}.tmp`, this.file);
    const dir = fs.openSync(path.dirname(this.file), "r");
    try { fs.fsyncSync(dir); } finally { fs.closeSync(dir); }
  }
}

function safeRelative(relative: string): boolean { return !!relative && !path.isAbsolute(relative) && !relative.split(/[\\/]/).some(part => part === ".." || part === ""); }
async function readContained(root: string, relative: string): Promise<Buffer> {
  if (!safeRelative(relative)) throw new Error("Unsafe folder path");
  const file = path.join(root, relative);
  for (let dir = path.dirname(file); dir !== root; dir = path.dirname(dir)) if ((await fsp.lstat(dir)).isSymbolicLink()) throw new Error("Folder contains a symlink");
  const handle = await fsp.open(file, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const actual = await fsp.realpath(process.platform === "linux" ? `/proc/self/fd/${handle.fd}` : file);
    if (!actual.startsWith(root + path.sep)) throw new Error("File escaped selected folder");
    const stat = await handle.stat();
    if (!stat.isFile() || stat.size > 64 * 1024 * 1024) throw new Error("File is not regular or exceeds 64 MB");
    return await handle.readFile();
  } finally { await handle.close(); }
}

import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { setImmediate as yieldTurn } from "node:timers/promises";
import type { RuntimeEngine } from "../runtime/engine.js";
import { fetchGithubDocuments } from "./github.js";
import { countCorpus, streamCorpus } from "./corpus.js";
import { InputError, object, text, flag, optionalText } from "../api/validation.js";

export interface JobRequest {
  kind: "github" | "wikipedia";
  user?: string;
  deep?: boolean;
}
export interface IngestJob {
  id: string;
  request: JobRequest;
  status: "queued" | "running" | "completed" | "failed" | "cancelled" | "interrupted";
  createdAt: string;
  updatedAt: string;
  progress: { completed: number; total: number; indexed: number };
  error?: string;
  result?: unknown;
}

export function jobRequest(input: unknown): { request: JobRequest; token?: string } {
  const body = object(input);
  if (body.kind !== "github" && body.kind !== "wikipedia") throw new InputError("job kind must be github or wikipedia");
  return {
    request: body.kind === "github"
      ? { kind: "github", user: text(body.user, "GitHub target", 256), deep: flag(body.deep, "deep") ?? false }
      : { kind: "wikipedia" },
    token: optionalText(body.token, "GitHub token", 512),
  };
}

export class IngestJobs {
  private readonly jobs = new Map<string, IngestJob>();
  private readonly tokens = new Map<string, string>();
  private readonly file: string;
  private active: { id: string; controller: AbortController; promise: Promise<void> } | undefined;
  private closed = false;
  private persistenceError: string | undefined;

  constructor(private readonly engine: RuntimeEngine, dataDir: string) {
    this.file = path.join(dataDir, "jobs.json");
    if (fs.existsSync(this.file)) {
      const saved = JSON.parse(fs.readFileSync(this.file, "utf8")) as IngestJob[];
      if (!Array.isArray(saved) || saved.length > 100) throw new Error("Invalid ingestion job history");
      for (const job of saved) {
        if (!validSavedJob(job)) throw new Error("Invalid ingestion job history");
        // Credentials stay in memory; interrupted imports require an explicit retry.
        if (job.status === "running" || job.status === "queued") {
          job.status = "interrupted";
          job.error = "Server stopped before completion. Retry to resume; imported batches are retained.";
        }
        this.jobs.set(job.id, job);
      }
      this.persist();
    }
  }

  list(): IngestJob[] { return [...this.jobs.values()].reverse(); }
  get(id: string): IngestJob | undefined { return this.jobs.get(id); }
  busy(): boolean { return this.active !== undefined || [...this.jobs.values()].some((j) => j.status === "queued"); }

  create(input: unknown): IngestJob {
    if (this.closed) throw new InputError("ingestion is shutting down");
    if (this.persistenceError) throw new Error(this.persistenceError);
    if ([...this.jobs.values()].filter((job) => job.status === "queued" || job.status === "running").length >= 20) {
      throw new InputError("ingestion queue is full");
    }
    const { request, token } = jobRequest(input);
    const now = new Date().toISOString();
    const job: IngestJob = { id: randomUUID(), request, status: "queued", createdAt: now, updatedAt: now, progress: { completed: 0, total: 0, indexed: 0 } };
    this.jobs.set(job.id, job);
    if (token) this.tokens.set(job.id, token);
    for (const old of this.jobs.values()) {
      if (this.jobs.size <= 100) break;
      if (old.status !== "queued" && old.status !== "running") this.jobs.delete(old.id);
    }
    try { this.persist(); }
    catch (error) { this.jobs.delete(job.id); this.tokens.delete(job.id); throw error; }
    setImmediate(() => this.pump());
    return job;
  }

  cancel(id: string): IngestJob | undefined {
    const job = this.jobs.get(id);
    if (!job) return undefined;
    if (job.status === "queued") {
      job.status = "cancelled";
      this.tokens.delete(id);
      this.persist();
    } else if (job.status === "running") {
      this.active?.controller.abort();
    }
    return job;
  }

  retry(id: string, token?: string): IngestJob | undefined {
    const job = this.jobs.get(id);
    if (!job) return undefined;
    if (job.status === "queued" || job.status === "running") throw new InputError("cancel the active job before retrying");
    return this.create({ ...job.request, token });
  }

  async close(): Promise<void> {
    this.closed = true;
    this.active?.controller.abort();
    await this.active?.promise;
    for (const job of this.jobs.values()) {
      if (job.status === "queued") job.status = "interrupted";
    }
    this.tokens.clear();
    this.persist();
  }

  private pump(): void {
    if (this.closed || this.active || this.persistenceError) return;
    const job = [...this.jobs.values()].find((j) => j.status === "queued");
    if (!job) return;
    const controller = new AbortController();
    const promise = this.run(job, controller.signal).catch(() => {
      // Stop the queue if job history cannot be saved; preserve the failure in memory.
      this.persistenceError = "Cannot save ingestion job history. Check disk space and permissions, then restart the server.";
      job.status = "failed";
      job.error = this.persistenceError;
      this.tokens.delete(job.id);
    }).finally(() => {
      this.active = undefined;
      setImmediate(() => this.pump());
    });
    this.active = { id: job.id, controller, promise };
  }

  private async run(job: IngestJob, signal: AbortSignal): Promise<void> {
    job.status = "running";
    try {
      this.persist();
      if (job.request.kind === "github") {
        const { docs, summary } = await fetchGithubDocuments({
          user: job.request.user!, deep: job.request.deep, token: this.tokens.get(job.id), signal,
          onProgress: (completed, total) => {
            job.progress = { ...job.progress, completed, total };
            this.persist();
          },
        });
        signal.throwIfAborted();
        const ingestion = await this.engine.ingestDocuments(docs);
        job.progress.indexed = docs.length;
        job.result = { ...summary, ingestion, documents: await this.engine.documentCount() };
      } else {
        job.progress.total = await countCorpus();
        await streamCorpus(async (docs) => {
          signal.throwIfAborted();
          await this.engine.ingestDocuments(docs);
          job.progress.completed += docs.length;
          job.progress.indexed += docs.length;
          this.persist();
          await yieldTurn();
        });
        job.result = { documents: await this.engine.documentCount() };
      }
      await this.engine.snapshot();
      job.status = "completed";
    } catch (error) {
      job.status = signal.aborted ? "cancelled" : "failed";
      job.error = signal.aborted ? "Import cancelled. Completed batches are retained." : error instanceof Error ? error.message : "Import failed";
      const token = this.tokens.get(job.id);
      if (token) job.error = job.error.replaceAll(token, "[redacted]");
    } finally {
      this.tokens.delete(job.id);
      job.updatedAt = new Date().toISOString();
      this.persist();
    }
  }

  private persist(): void {
    const tmp = `${this.file}.tmp`;
    const fd = fs.openSync(tmp, "w", 0o600);
    try { fs.writeFileSync(fd, JSON.stringify([...this.jobs.values()])); fs.fsyncSync(fd); }
    finally { fs.closeSync(fd); }
    fs.renameSync(tmp, this.file);
    const dir = fs.openSync(path.dirname(this.file), "r");
    try { fs.fsyncSync(dir); } finally { fs.closeSync(dir); }
  }
}

function validSavedJob(job: IngestJob): boolean {
  return !!job && typeof job.id === "string" && job.id.length <= 128 &&
    !!job.request && (job.request.kind === "wikipedia" ||
      (job.request.kind === "github" && typeof job.request.user === "string" && job.request.user.length <= 256 &&
        (job.request.deep === undefined || typeof job.request.deep === "boolean"))) &&
    ["queued", "running", "completed", "failed", "cancelled", "interrupted"].includes(job.status) &&
    typeof job.createdAt === "string" && Number.isFinite(Date.parse(job.createdAt)) &&
    typeof job.updatedAt === "string" && Number.isFinite(Date.parse(job.updatedAt)) &&
    !!job.progress && [job.progress.completed, job.progress.total, job.progress.indexed].every((n) => Number.isSafeInteger(n) && n >= 0) &&
    (job.error === undefined || typeof job.error === "string");
}

import { extractText, getDocumentProxy } from "unpdf";
import type { Document } from "../types.js";

export interface ExtractResult {
  filename: string;
  status: "indexed" | "skipped";
  /** Present when skipped — why we couldn't index it. */
  reason?: string;
  /** The documents to index (empty when skipped). */
  docs: Document[];
}

/** Extensions we confidently treat as UTF-8 text (source code, docs, data). */
export const TEXT_EXTENSIONS = new Set([
  "txt", "md", "markdown", "log", "csv", "tsv", "rtf",
  "json", "ndjson", "jsonl", "yaml", "yml", "toml", "ini", "env", "xml", "html",
  "css", "scss", "js", "jsx", "ts", "tsx", "mjs", "cjs",
  "py", "rb", "go", "rs", "java", "kt", "c", "h", "cpp", "hpp", "cc",
  "cs", "php", "swift", "scala", "sh", "bash", "zsh", "sql", "graphql",
  "vue", "svelte", "dockerfile", "makefile", "gitignore", "lock", "conf",
]);

export function extensionOf(filename: string): string {
  const base = filename.toLowerCase().split(/[\\/]/).pop() ?? "";
  const dot = base.lastIndexOf(".");
  // Handle dotfiles / extensionless names like "Dockerfile", "Makefile".
  if (dot <= 0) return base;
  return base.slice(dot + 1);
}

function isProbablyBinary(buffer: Buffer): boolean {
  const sample = buffer.subarray(0, Math.min(buffer.length, 8192));
  if (sample.length === 0) return false;
  let suspicious = 0;
  for (const byte of sample) {
    if (byte === 0) return true; // NUL — definitively binary
    // Allow tab(9), LF(10), CR(13); flag other C0 control chars.
    if (byte < 9 || (byte > 13 && byte < 32)) suspicious++;
  }
  return suspicious / sample.length > 0.3;
}

function withSource(value: unknown, filename: string): Document {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return { ...(value as Record<string, unknown>), filename };
  }
  return { filename, content: value };
}

async function extractPdf(filename: string, buffer: Buffer): Promise<ExtractResult> {
  const pdf = await getDocumentProxy(new Uint8Array(buffer));
  const { totalPages, text } = await extractText(pdf, { mergePages: false });
  const pageTexts = Array.isArray(text) ? text : [text ?? ""];
  let offset = 0;
  const pageOffsets = pageTexts.map((page, index) => {
    const start = offset;
    offset += page.length + (index < pageTexts.length - 1 ? 2 : 0);
    return { page: index + 1, start, end: start + page.length };
  });
  const content = pageTexts.join("\n\n");
  if (content.trim().length === 0) {
    return {
      filename,
      status: "skipped",
      reason: "no extractable text (likely a scanned/image-only PDF)",
      docs: [],
    };
  }
  return {
    filename,
    status: "indexed",
    docs: [{ filename, type: "pdf", pages: totalPages, pageOffsets, content }],
  };
}

export interface ExtractOptions { strictStructured?: boolean }

function extractJson(filename: string, text: string, strict: boolean): Document[] | null {
  try {
    const parsed = JSON.parse(text);
    const arr = Array.isArray(parsed) ? parsed : [parsed];
    return arr.map((o) => withSource(o, filename));
  } catch (error) {
    if (strict) throw error;
    return null;
  }
}

function extractNdjson(filename: string, text: string): Document[] {
  const docs: Document[] = [];
  for (const [index, line] of text.split("\n").entries()) {
    const t = line.trim();
    if (!t) continue;
    try {
      docs.push(withSource(JSON.parse(t), filename));
    } catch {
      throw new Error(`invalid JSON on line ${index + 1}`);
    }
  }
  return docs;
}

export async function extractDocuments(
  filename: string,
  buffer: Buffer,
  options: ExtractOptions = {},
): Promise<ExtractResult> {
  const ext = extensionOf(filename);

  try {
    if (ext === "pdf") return await extractPdf(filename, buffer);

    // For everything else we need UTF-8 text. Reject true binaries up front.
    if (isProbablyBinary(buffer)) {
      if (options.strictStructured && ["json", "ndjson", "jsonl"].includes(ext)) throw new Error("invalid structured file: binary content");
      return {
        filename,
        status: "skipped",
        reason: "unsupported binary file (no text to index)",
        docs: [],
      };
    }

    const text = new TextDecoder("utf-8", { fatal: true }).decode(buffer);

    if (text.trim().length === 0) {
      if (ext === "json" && options.strictStructured) throw new Error("invalid JSON: empty file");
      return { filename, status: "skipped", reason: "empty file", docs: [] };
    }

    if (ext === "json") {
      const docs = extractJson(filename, text, options.strictStructured === true);
      if (docs) return { filename, status: "indexed", docs };
      // Not valid JSON — fall back to storing the raw text.
    }

    if (ext === "ndjson" || ext === "jsonl") {
      const docs = extractNdjson(filename, text);
      return { filename, status: "indexed", docs };
    }

    return {
      filename,
      status: "indexed",
      docs: [{ filename, content: text }],
    };
  } catch (e) {
    return {
      filename,
      status: "skipped",
      reason: e instanceof Error ? e.message : "failed to extract",
      docs: [],
    };
  }
}

import type { Document } from "../types.js";
import { TEXT_EXTENSIONS, extensionOf } from "./extract.js";

const API = "https://api.github.com";

export interface GithubOptions {
  user: string;
  token?: string;
  deep?: boolean;
  signal?: AbortSignal;
  onProgress?: (completed: number, total: number) => void;
  /** Safety caps so one call can't fan out unboundedly. */
  maxRepos?: number;
  maxFilesPerRepo?: number;
  maxTotalFiles?: number;
  maxFileBytes?: number;
}

export interface GithubSummary {
  user: string;
  reposFound: number;
  reposIndexed: number;
  filesIndexed: number;
  documents: number;
  rateRemaining: number | null;
  deep: boolean;
  errors: string[];
}

interface Repo {
  name: string;
  full_name: string;
  description: string | null;
  language: string | null;
  topics?: string[];
  stargazers_count: number;
  forks_count: number;
  html_url: string;
  updated_at: string;
  private: boolean;
  default_branch: string;
  fork: boolean;
}

interface GhResponse<T> {
  ok: boolean;
  status: number;
  data: T;
  rateRemaining: number | null;
}

async function gh<T>(
  path: string,
  token: string | undefined,
  accept = "application/vnd.github+json",
  signal?: AbortSignal,
): Promise<GhResponse<T>> {
  const headers: Record<string, string> = {
    Accept: accept,
    "User-Agent": "shardly",
    "X-GitHub-Api-Version": "2022-11-28",
  };
  if (token) headers.Authorization = `Bearer ${token}`;

  const res = await fetch(path.startsWith("http") ? path : `${API}${path}`, {
    headers,
    signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(30000)]) : AbortSignal.timeout(30000),
  });
  const remainingHeader = res.headers.get("x-ratelimit-remaining");
  const rateRemaining = remainingHeader === null ? null : Number(remainingHeader);

  const isJson = accept.includes("json") && !accept.includes("raw");
  const data = (isJson ? await res.json().catch(() => null) : await res.text()) as T;
  return { ok: res.ok, status: res.status, data, rateRemaining };
}

async function mapLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  const out: R[] = new Array(items.length);
  let next = 0;
  async function worker() {
    for (;;) {
      const i = next++;
      if (i >= items.length) return;
      out[i] = await fn(items[i]!, i);
    }
  }
  const workers = Array.from({ length: Math.min(limit, items.length) }, worker);
  await Promise.all(workers);
  return out;
}

export interface GithubTarget {
  kind: "user" | "repo";
  /** For kind "user". */
  user?: string;
  /** For kind "repo". */
  owner?: string;
  repo?: string;
}

/** Accept a bare username, an `owner/repo`, or a full GitHub URL. */
export function parseGithubTarget(input: string): GithubTarget {
  const cleaned = input
    .trim()
    .replace(/^https?:\/\/github\.com\//i, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(/\.git$/i, "");
  const parts = cleaned.split("/").filter(Boolean);
  if (parts.length >= 2) {
    return { kind: "repo", owner: parts[0], repo: parts[1] };
  }
  return { kind: "user", user: parts[0] ?? "" };
}

async function repoListPath(
  user: string,
  token: string | undefined,
  signal?: AbortSignal,
): Promise<{ base: string; ownAccount: boolean }> {
  if (token) {
    const me = await gh<{ login?: string }>("/user", token, undefined, signal);
    if (me.ok && me.data?.login?.toLowerCase() === user.toLowerCase()) {
      return {
        base: "/user/repos?per_page=100&affiliation=owner&sort=updated",
        ownAccount: true,
      };
    }
  }
  return { base: `/users/${encodeURIComponent(user)}/repos?per_page=100&sort=updated`, ownAccount: false };
}

async function listRepos(
  user: string,
  token: string | undefined,
  maxRepos: number,
  signal?: AbortSignal,
): Promise<{ repos: Repo[]; rateRemaining: number | null }> {
  const { base } = await repoListPath(user, token, signal);
  const repos: Repo[] = [];
  let rateRemaining: number | null = null;

  for (let page = 1; repos.length < maxRepos; page++) {
    const res = await gh<Repo[] | { message?: string }>(
      `${base}&page=${page}`,
      token,
      undefined,
      signal,
    );
    rateRemaining = res.rateRemaining;

    if (!res.ok) {
      if (res.status === 404) throw new Error(`GitHub user "${user}" not found`);
      if (res.status === 401) throw new Error("invalid GitHub token");
      if (res.status === 403)
        throw new Error(
          "GitHub rate limit reached — add a personal access token to continue",
        );
      const msg = (res.data as { message?: string })?.message ?? `HTTP ${res.status}`;
      throw new Error(`GitHub error: ${msg}`);
    }

    const page_ = res.data as Repo[];
    if (!Array.isArray(page_) || page_.length === 0) break;
    repos.push(...page_);
    if (page_.length < 100) break; // last page
  }

  return { repos: repos.slice(0, maxRepos), rateRemaining };
}

async function fetchReadme(
  fullName: string,
  token: string | undefined,
  signal?: AbortSignal,
): Promise<string | undefined> {
  const res = await gh<string>(
    `/repos/${fullName}/readme`,
    token,
    "application/vnd.github.raw",
    signal,
  );
  if (!res.ok || typeof res.data !== "string") return undefined;
  return res.data.trim() || undefined;
}

function repoDoc(repo: Repo, readme: string | undefined): Document {
  return {
    source: "github",
    sourceId: `github:${repo.full_name.toLowerCase()}:repository`,
    type: "repository",
    title: repo.full_name,
    repo: repo.full_name,
    fullName: repo.full_name,
    description: repo.description ?? "",
    language: repo.language ?? "",
    topics: repo.topics ?? [],
    stars: repo.stargazers_count,
    forks: repo.forks_count,
    url: repo.html_url,
    updatedAt: repo.updated_at,
    private: repo.private,
    ...(readme ? { readme } : {}),
  };
}

interface TreeEntry {
  path: string;
  type: string;
  sha: string;
  size?: number;
}

/** Index individual text/source files of a repo (deep mode). */
async function fetchRepoFiles(
  repo: Repo,
  token: string | undefined,
  maxFiles: number,
  maxFileBytes: number,
  errors: string[],
  signal?: AbortSignal,
): Promise<Document[]> {
  const tree = await gh<{ tree?: TreeEntry[]; message?: string }>(
    `/repos/${repo.full_name}/git/trees/${repo.default_branch}?recursive=1`,
    token,
    undefined,
    signal,
  );
  if (!tree.ok || !Array.isArray(tree.data.tree)) return [];

  const candidates = tree.data.tree
    .filter(
      (e) =>
        e.type === "blob" &&
        (e.size ?? 0) <= maxFileBytes &&
        TEXT_EXTENSIONS.has(extensionOf(e.path)),
    )
    .slice(0, maxFiles);

  // Fetch blobs concurrently — the single biggest speedup for deep mode.
  const results = await mapLimit<TreeEntry, Document | null>(candidates, 8, async (entry) => {
    const blob = await gh<{ content?: string; encoding?: string }>(
      `/repos/${repo.full_name}/git/blobs/${entry.sha}`,
      token,
      undefined,
      signal,
    );
    if (!blob.ok || !blob.data.content) return null;
    try {
      const content = new TextDecoder("utf-8", { fatal: true }).decode(Buffer.from(blob.data.content, "base64"));
      if (content.trim().length === 0) return null;
      return {
        source: "github",
        sourceId: `github:${repo.full_name.toLowerCase()}:file:${entry.path}`,
        type: "file",
        repo: repo.full_name,
        fullName: repo.full_name,
        language: repo.language ?? "",
        path: entry.path,
        url: `${repo.html_url}/blob/${repo.default_branch}/${entry.path}`,
        content,
      } satisfies Document;
    } catch {
      errors.push(`failed to decode ${repo.full_name}/${entry.path}`);
      return null;
    }
  });

  return results.filter((d): d is Document => d !== null);
}

/** Fetch a single repository's metadata object. */
async function fetchRepo(
  owner: string,
  repo: string,
  token: string | undefined,
  signal?: AbortSignal,
): Promise<{ repo: Repo; rateRemaining: number | null }> {
  const res = await gh<Repo | { message?: string }>(
    `/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`,
    token,
    undefined,
    signal,
  );
  if (!res.ok) {
    if (res.status === 404) throw new Error(`repository "${owner}/${repo}" not found`);
    if (res.status === 401) throw new Error("invalid GitHub token");
    if (res.status === 403)
      throw new Error("GitHub rate limit reached — add a personal access token");
    const msg = (res.data as { message?: string })?.message ?? `HTTP ${res.status}`;
    throw new Error(`GitHub error: ${msg}`);
  }
  return { repo: res.data as Repo, rateRemaining: res.rateRemaining };
}

async function documentsForRepo(
  repo: Repo,
  token: string | undefined,
  deep: boolean,
  fileBudget: number,
  maxFilesPerRepo: number,
  maxFileBytes: number,
  errors: string[],
  signal?: AbortSignal,
): Promise<Document[]> {
  signal?.throwIfAborted();
  const readme = await fetchReadme(repo.full_name, token, signal).catch(() => undefined);
  const docs: Document[] = [repoDoc(repo, readme)];

  if (deep && fileBudget > 0) {
    const files = await fetchRepoFiles(
      repo,
      token,
      Math.min(maxFilesPerRepo, fileBudget),
      maxFileBytes,
      errors,
      signal,
    ).catch((e) => {
      errors.push(`${repo.full_name}: ${e instanceof Error ? e.message : e}`);
      return [] as Document[];
    });
    docs.push(...files);
  }
  signal?.throwIfAborted();
  return docs;
}

export async function fetchGithubDocuments(
  opts: GithubOptions,
): Promise<{ docs: Document[]; summary: GithubSummary }> {
  const raw = opts.user.trim();
  if (!raw) throw new Error("a GitHub username or repository is required");

  const caps = {
    maxRepos: opts.maxRepos ?? 100,
    maxFilesPerRepo: opts.maxFilesPerRepo ?? 25,
    maxTotalFiles: opts.maxTotalFiles ?? 400,
    maxFileBytes: opts.maxFileBytes ?? 120_000,
  };
  const deep = opts.deep ?? false;
  const errors: string[] = [];

  const target = parseGithubTarget(raw);

  // Gather the repositories to index (one for a repo target, many for a user).
  let repos: Repo[];
  let rateRemaining: number | null;
  let label: string;
  if (target.kind === "repo") {
    const r = await fetchRepo(target.owner!, target.repo!, opts.token, opts.signal);
    repos = [r.repo];
    rateRemaining = r.rateRemaining;
    label = `${target.owner}/${target.repo}`;
  } else {
    const listed = await listRepos(target.user!, opts.token, caps.maxRepos, opts.signal);
    repos = listed.repos;
    rateRemaining = listed.rateRemaining;
    label = target.user!;
  }

  const docs: Document[] = [];
  let filesIndexed = 0;
  let completed = 0;

  if (deep) {
    for (const repo of repos) {
      const budget = caps.maxTotalFiles - filesIndexed;
      const repoDocs = await documentsForRepo(
        repo, opts.token, true, budget, caps.maxFilesPerRepo, caps.maxFileBytes, errors, opts.signal,
      );
      filesIndexed += repoDocs.filter((d) => d.type === "file").length;
      docs.push(...repoDocs);
      opts.signal?.throwIfAborted();
      opts.onProgress?.(++completed, repos.length);
    }
  } else {
    // No files to budget — fetch every repo's README concurrently.
    const perRepo = await mapLimit(repos, 8, (repo) =>
      documentsForRepo(repo, opts.token, false, 0, 0, caps.maxFileBytes, errors, opts.signal).then((docs) => {
        opts.onProgress?.(++completed, repos.length);
        return docs;
      }),
    );
    for (const ds of perRepo) docs.push(...ds);
  }

  opts.signal?.throwIfAborted();
  const summary: GithubSummary = {
    user: label,
    reposFound: repos.length,
    reposIndexed: repos.length,
    filesIndexed,
    documents: docs.length,
    rateRemaining,
    deep,
    errors,
  };
  return { docs, summary };
}

import type { SearchGroup, SearchOptions, SearchSnippet } from "./api";

export interface SavedSearch {
  id: string;
  name: string;
  query: string;
  options: SearchOptions;
  exact?: boolean;
}
export interface Collection {
  id: string;
  name: string;
  docIds: string[];
}

const object = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === "object" && !Array.isArray(value);
const text = (value: unknown, max: number): value is string =>
  typeof value === "string" && !!value.trim() && value.length <= max;
const id = (value: unknown): value is string =>
  text(value, 128) && /^[a-zA-Z0-9_-]+$/.test(value);
const ids = (value: unknown): value is string[] =>
  Array.isArray(value) &&
  value.length <= 1000 &&
  value.every(id) &&
  new Set(value).size === value.length;

export function validSynonyms(
  value: unknown,
): value is Record<string, string[]> {
  return (
    object(value) &&
    JSON.stringify(value).length <= 8000 &&
    Object.entries(value).length <= 32 &&
    Object.entries(value).every(
      ([term, aliases]) =>
        text(term, 80) &&
        Array.isArray(aliases) &&
        aliases.length <= 8 &&
        aliases.every((alias) => text(alias, 80)),
    )
  );
}

export function validSearchOptions(value: unknown): value is SearchOptions {
  if (!object(value)) return false;
  return Object.entries(value).every(([key, v]) => {
    if (v === undefined) return true;
    switch (key) {
      case "match":
        return v === "text" || v === "literal" || v === "substring";
      case "mode":
        return v === "all" || v === "any";
      case "groupBy":
        return v === "none" || v === "repo" || v === "source";
      case "profile":
        return v === "baseline" || v === "tuned";
      case "prefix":
      case "typos":
      case "inspect":
        return typeof v === "boolean";
      case "limit":
        return Number.isSafeInteger(v) && Number(v) >= 1 && Number(v) <= 100;
      case "offset":
        return Number.isSafeInteger(v) && Number(v) >= 0 && Number(v) <= 100000;
      case "source":
      case "repo":
      case "type":
      case "language":
        return text(v, 256);
      case "docIds":
        return ids(v);
      case "synonyms":
        return validSynonyms(v);
      default:
        return false;
    }
  });
}

export function validSavedSearches(value: unknown): value is SavedSearch[] {
  return (
    Array.isArray(value) &&
    value.length <= 1000 &&
    value.every(
      (x) =>
        object(x) &&
        id(x.id) &&
        text(x.name, 256) &&
        text(x.query, 2000) &&
        (x.exact === undefined || typeof x.exact === "boolean") &&
        validSearchOptions(x.options),
    ) &&
    new Set(value.map((x) => x.id)).size === value.length
  );
}
export function validCollections(value: unknown): value is Collection[] {
  return (
    Array.isArray(value) &&
    value.length <= 1000 &&
    value.every(
      (x) => object(x) && id(x.id) && text(x.name, 256) && ids(x.docIds),
    ) &&
    new Set(value.map((x) => x.id)).size === value.length
  );
}

function read<T>(
  key: string,
  fallback: T,
  valid: (value: unknown) => value is T,
): T {
  if (typeof window === "undefined") return fallback;
  try {
    const value: unknown = JSON.parse(localStorage.getItem(key) ?? "null");
    return valid(value) ? value : fallback;
  } catch {
    return fallback;
  }
}
export function loadSavedSearches(): SavedSearch[] {
  return read("shardly-saved-searches", [], validSavedSearches);
}
export function recentSearches(next: SavedSearch, previous: SavedSearch[]): SavedSearch[] {
  const signature = JSON.stringify(searchParams(next.query, next.options, Boolean(next.exact)).toString());
  return [next, ...previous.filter((item) => JSON.stringify(searchParams(item.query, item.options, Boolean(item.exact)).toString()) !== signature)].slice(0, 8);
}
export function loadRecentSearches(): SavedSearch[] {
  return read("shardly-recent-searches", [], validSavedSearches);
}
export function loadCollections(): Collection[] {
  return read("shardly-collections", [], validCollections);
}
export function saveWorkspace(
  key: "shardly-saved-searches" | "shardly-recent-searches" | "shardly-collections",
  value: unknown,
): string | null {
  if (
    !(key === "shardly-collections"
      ? validCollections(value)
      : validSavedSearches(value))
  ) {
    return "Changes could not be saved. Check names, IDs, and search options.";
  }
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return null;
  } catch {
    return "Could not save changes in this browser (storage may be full or blocked).";
  }
}

export function searchParams(
  q: string,
  options: SearchOptions,
  exact = false,
): URLSearchParams {
  const params = new URLSearchParams({ q });
  if (exact) params.set("exact", "true");
  for (const [key, value] of Object.entries(options)) {
    if (value !== undefined && value !== false) {
      params.set(
        key,
        key === "synonyms"
          ? JSON.stringify(value)
          : Array.isArray(value)
            ? value.join(",")
            : String(value),
      );
    }
  }
  return params;
}
export function readSearchOptions(params: URLSearchParams): SearchOptions {
  const options: Record<string, unknown> = {};
  for (const [key, value] of params) {
    if (key === "q" || key === "exact") continue;
    if (key === "synonyms") {
      try {
        options[key] = JSON.parse(value);
      } catch {
        throw new Error("Synonyms in the URL must be valid JSON.");
      }
    } else if (key === "docIds") options[key] = value ? value.split(",") : [];
    else if (key === "limit" || key === "offset")
      options[key] = /^\d+$/.test(value) ? Number(value) : NaN;
    else if (["prefix", "typos", "inspect"].includes(key))
      options[key] =
        value === "true" ? true : value === "false" ? false : value;
    else if (
      [
        "mode",
        "match",
        "groupBy",
        "profile",
        "source",
        "repo",
        "type",
        "language",
      ].includes(key)
    )
      options[key] = value;
  }
  if (!validSearchOptions(options))
    throw new Error(
      "Invalid search options in the URL. Clear the filters and try again.",
    );
  return options;
}

export function passageMarks(
  passage: SearchSnippet,
): Array<{ start: number; end: number }> {
  const spans = passage.matches
    .map((m) => ({
      start: Math.max(0, m.start - passage.start),
      end: Math.min(passage.text.length, m.end - passage.start),
    }))
    .filter((m) => m.end > m.start)
    .sort((a, b) => a.start - b.start || a.end - b.end);
  const merged: Array<{ start: number; end: number }> = [];
  for (const span of spans) {
    const last = merged[merged.length - 1];
    if (last && span.start <= last.end) last.end = Math.max(last.end, span.end);
    else merged.push({ ...span });
  }
  return merged;
}
export function distinctPassages(
  snippet: SearchSnippet | undefined,
  passages: SearchSnippet[] = [],
): SearchSnippet[] {
  const result: SearchSnippet[] = [];
  for (const passage of [...(snippet ? [snippet] : []), ...passages]) {
    if (
      !result.some(
        (p) =>
          p.text === passage.text ||
          (p.field === passage.field &&
            p.start < passage.end &&
            passage.start < p.end),
      )
    )
      result.push(passage);
    if (result.length === 3) break;
  }
  return result;
}

// Field offsets refer to the engine's recursively flattened original field values.
export function originalFieldText(
  doc: Record<string, unknown>,
  field: string,
): string {
  const values: string[] = [];
  function collect(value: unknown) {
    if (value === null || value === undefined) return;
    if (["string", "number", "boolean"].includes(typeof value))
      values.push(String(value));
    else if (Array.isArray(value)) value.forEach(collect);
    else if (typeof value === "object")
      Object.values(value as Record<string, unknown>).forEach(collect);
  }
  collect(Object.hasOwn(doc, field) ? doc[field] : undefined);
  return values.join(" ");
}
export function documentMatchHref(
  docId: string,
  query: string,
  passage?: SearchSnippet,
): string {
  const params = new URLSearchParams({ q: query });
  if (passage) {
    params.set("field", passage.field);
    params.set("at", String(passage.matches[0]?.start ?? passage.start));
    params.set("end", String(passage.matches[0]?.end ?? passage.end));
  }
  return `/document/${encodeURIComponent(docId)}?${params}`;
}

export function visibleGroups(
  groups: SearchGroup[],
  total: number,
): SearchGroup[] {
  const unassigned =
    total - groups.reduce((sum, group) => sum + group.count, 0);
  return unassigned > 0 ? [...groups, { key: "", count: unassigned }] : groups;
}

"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import MissingInspector from "@/components/MissingInspector";
import { Icon, Segmented, Switch, Toast } from "@/components/ui";
import {
  compareSearch,
  getDocument,
  search,
  suggest,
  type SearchGroup,
  type SearchHit,
  type SearchOptions,
  type SearchResponse,
  type SearchSnippet,
} from "@/lib/api";
import { describe, snippet } from "@/lib/docmeta";
import {
  loadCollections,
  loadRecentSearches,
  recentSearches,
  loadSavedSearches,
  saveWorkspace,
  readSearchOptions,
  searchParams,
  validSynonyms,
  passageMarks,
  distinctPassages,
  originalFieldText,
  documentMatchHref,
  visibleGroups,
  type Collection,
  type SavedSearch,
} from "@/lib/workspace";

const initialOptions: SearchOptions = {
  mode: "all",
  groupBy: "none",
  prefix: false,
  typos: false,
  profile: "tuned",
  inspect: false,
  limit: 10,
  offset: 0,
};

const FACETS = { source: "Source", repo: "Repository", type: "Type", language: "Language" } as const;

export default function SearchView({ documents, sourcesHref }: { documents?: number | null; sourcesHref: string }) {
  const [q, setQ] = useState("");
  const [exact, setExact] = useState(false);
  const [options, setOptions] = useState<SearchOptions>(initialOptions);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [suggestionIndex, setSuggestionIndex] = useState(-1);
  const [res, setRes] = useState<SearchResponse | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [selected, setSelected] = useState(0);
  const [preview, setPreview] = useState<SearchHit | null>(null);
  const [fullDoc, setFullDoc] = useState<Record<string, unknown> | null>(null);
  const [recent, setRecent] = useState<SavedSearch[]>([]);
  const recentRef = useRef<SavedSearch[]>([]);
  const [saved, setSaved] = useState<SavedSearch[]>([]);
  const [collections, setCollections] = useState<Collection[]>([]);
  const [compare, setCompare] = useState<{ baseline: SearchResponse; tuned: SearchResponse } | null>(null);
  const [notice, setNoticeText] = useState<{ text: string; n: number } | null>(null);
  const setNotice = (text: string) => setNoticeText((c) => ({ text, n: (c?.n ?? 0) + 1 }));
  const generation = useRef(0);
  const suggestionGeneration = useRef(0);
  const previewGeneration = useRef(0);
  const compareGeneration = useRef(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [synonymDraft, setSynonymDraft] = useState("{}");
  const [synonymError, setSynonymError] = useState<string | null>(null);
  const [collectionTarget, setCollectionTarget] = useState<string | null>(null);
  const [missingOpen, setMissingOpen] = useState(false);
  const [missingTarget, setMissingTarget] = useState<string | undefined>();
  const [saving, setSaving] = useState(false);
  const [nameDraft, setNameDraft] = useState("");
  const [nameError, setNameError] = useState<string | null>(null);
  const [appliedOptions, setAppliedOptions] = useState<SearchOptions>(initialOptions);

  useEffect(() => {
    setSaved(loadSavedSearches());
    recentRef.current = loadRecentSearches(); setRecent(recentRef.current);
    setCollections(loadCollections());
    const apply = () => {
      ++compareGeneration.current;
      setCompare(null);
      setErr(null);
      hideSuggestions();
      closePreview();
      try {
        const params = new URLSearchParams(window.location.search);
        const nextQ = params.get("q") ?? "";
        if (params.get("explain")) { setMissingTarget(params.get("explain")!); setMissingOpen(true); }
        const nextExact = params.get("exact") === "true";
        const nextOptions = { ...initialOptions, ...readSearchOptions(params) };
        setQ(nextQ);
        setExact(nextExact);
        setOptions(nextOptions);
        setSynonymDraft(JSON.stringify(nextOptions.synonyms ?? {}, null, 2));
        if (nextQ.trim()) void run(nextQ, nextOptions, nextExact, false);
        else { ++generation.current; setRes(null); setBusy(false); }
      } catch (error) {
        ++generation.current;
        setBusy(false);
        setRes(null);
        setErr(error instanceof Error ? error.message : "Invalid search URL");
      }
    };
    apply();
    window.addEventListener("popstate", apply);
    return () => {
      window.removeEventListener("popstate", apply);
      ++generation.current;
      ++suggestionGeneration.current;
      ++previewGeneration.current;
      ++compareGeneration.current;
    };
  }, []);

  useEffect(() => {
    const request = ++suggestionGeneration.current;
    setSuggestions([]);
    setSuggestionIndex(-1);
    if (q.trim().length < 2) return;
    const timer = window.setTimeout(async () => {
      try {
        const items = await suggest(q.trim());
        if (request === suggestionGeneration.current && document.activeElement === inputRef.current) setSuggestions(items);
      } catch {
        if (request === suggestionGeneration.current) setSuggestions([]);
      }
    }, 180);
    return () => { window.clearTimeout(timer); ++suggestionGeneration.current; };
  }, [q]);

  const hits = res?.hits ?? [];
  const grouped = !!appliedOptions.groupBy && appliedOptions.groupBy !== "none";
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      const target = e.target as HTMLElement;
      if (target.matches("input, textarea, select, button, [contenteditable=true]")) return;
      if (e.key === "/") { e.preventDefault(); inputRef.current?.focus(); return; }
      if (e.key === "Escape") { setCollectionTarget(null); closePreview(); return; }
      if (grouped) return;
      if (e.key === "j") { e.preventDefault(); setSelected((n) => Math.min(n + 1, Math.max(0, hits.length - 1))); }
      else if (e.key === "k") { e.preventDefault(); setSelected((n) => Math.max(n - 1, 0)); }
      else if (e.key === "Enter" && hits[selected]) openPreview(hits[selected]!);
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [hits, selected, grouped]);

  function closePreview() {
    ++previewGeneration.current;
    setPreview(null);
    setFullDoc(null);
    setPreviewError(null);
  }
  function hideSuggestions() {
    ++suggestionGeneration.current;
    setSuggestions([]);
    setSuggestionIndex(-1);
  }
  async function run(nextQ = q, nextOptions = options, nextExact = exact, push = true) {
    ++compareGeneration.current;
    if (!nextQ.trim()) return;
    const actualQuery = nextExact && (!nextOptions.match || nextOptions.match === "text") ? `"${nextQ.replaceAll('"', "")}"` : nextQ;
    const runId = ++generation.current;
    setBusy(true);
    setErr(null);
    setCompare(null);
    setRes(null);
    setSelected(0);
    hideSuggestions();
    closePreview();
    const url = `${window.location.pathname}?${searchParams(nextQ, nextOptions, nextExact)}`;
    if (push && url !== `${window.location.pathname}${window.location.search}`) window.history.pushState({}, "", url);
    else window.history.replaceState({}, "", url);
    try {
      const result = await search(actualQuery, nextOptions);
      if (runId === generation.current) {
        setRes(result);
        setAppliedOptions(nextOptions);
        const nextRecent = recentSearches({ id: crypto.randomUUID(), name: nextQ.trim(), query: nextQ, options: { ...nextOptions, offset: 0 }, exact: nextExact }, recentRef.current);
        const historyError = saveWorkspace("shardly-recent-searches", nextRecent);
        if (historyError) setErr(historyError);
        else { recentRef.current = nextRecent; setRecent(nextRecent); }
      }
    } catch (error) {
      if (runId === generation.current) {
        setErr(error instanceof Error ? error.message : "Search failed");
        setRes(null);
      }
    } finally {
      if (runId === generation.current) setBusy(false);
    }
  }
  function change(key: keyof SearchOptions, value: unknown) {
    const next = { ...options, [key]: value, offset: key === "offset" ? (value as number) : 0 };
    setOptions(next);
    void run(q, next);
  }
  function restore(item: SavedSearch) {
    const next = { ...initialOptions, ...(item.options as SearchOptions) };
    setQ(item.query);
    setExact(Boolean(item.exact));
    setOptions(next);
    setSynonymDraft(JSON.stringify(next.synonyms ?? {}, null, 2));
    void run(item.query, next, Boolean(item.exact));
  }
  function saveSearch() {
    if (!q.trim()) return;
    const name = nameDraft.trim();
    if (!name || name.length > 256) { setNameError("Enter a name of 1–256 characters."); return; }
    const next = [...saved, { id: crypto.randomUUID(), name, query: q, options: { ...options }, exact }];
    const error = saveWorkspace("shardly-saved-searches", next);
    if (error) { setNameError(error); return; }
    setSaved(next); setSaving(false); setNotice("Search saved");
  }
  function deleteSaved(id: string) {
    const next = saved.filter((item) => item.id !== id);
    const error = saveWorkspace("shardly-saved-searches", next);
    if (error) setErr(error); else setSaved(next);
  }
  function storeCollections(next: Collection[]) {
    const error = saveWorkspace("shardly-collections", next);
    if (error) { setErr(error); return false; }
    setCollections(next);
    return true;
  }
  const scope = options.docIds ? collections.find((c) => c.docIds.length === options.docIds!.length && c.docIds.every((id) => options.docIds!.includes(id))) : undefined;
  function addToCollection(collectionId: string) {
    if (!collectionTarget) return;
    const next = collections.map((c) => c.id === collectionId && !c.docIds.includes(collectionTarget) ? { ...c, docIds: [...c.docIds, collectionTarget] } : c);
    if (!storeCollections(next)) return;
    const name = next.find((c) => c.id === collectionId)?.name;
    setCollectionTarget(null);
    setNotice(`Added to ${name}`);
    if (scope?.id === collectionId) change("docIds", next.find((c) => c.id === collectionId)!.docIds);
  }
  function createCollection() {
    const name = nameDraft.trim();
    if (!name || name.length > 256) { setNameError("Enter a name of 1–256 characters."); return; }
    if (!storeCollections([...collections, { id: crypto.randomUUID(), name, docIds: collectionTarget ? [collectionTarget] : [] }])) return;
    setCollectionTarget(null);
    setNotice(`Added to ${name}`);
  }
  async function openPreview(hit: SearchHit) {
    const request = ++previewGeneration.current;
    setSelected(Math.max(0, hits.indexOf(hit)));
    setPreview(hit);
    setFullDoc(null);
    setPreviewError(null);
    try {
      const record = await getDocument(hit.docId);
      if (request === previewGeneration.current) setFullDoc(record.doc);
    } catch (error) {
      if (request === previewGeneration.current) setPreviewError(error instanceof Error ? error.message : "Could not load document. Try opening it again.");
    }
  }
  function selectSuggestion(value: string) {
    const next = { ...options, offset: 0 };
    setQ(value);
    setOptions(next);
    void run(value, next);
    inputRef.current?.focus();
  }
  async function runCompare() {
    if (!res) return;
    const request = ++compareGeneration.current;
    setErr(null);
    try {
      const result = await compareSearch(res.query, { ...appliedOptions, inspect: false });
      if (request === compareGeneration.current) setCompare(result);
    } catch (error) {
      if (request === compareGeneration.current) setErr(error instanceof Error ? error.message : "Comparison failed");
    }
  }
  function applySynonyms() {
    try {
      const value: unknown = JSON.parse(synonymDraft);
      if (!validSynonyms(value)) throw new Error("Use an object with at most 32 terms, each mapped to up to 8 strings of 80 characters or fewer.");
      setSynonymError(null);
      change("synonyms", value);
    } catch (error) {
      setSynonymError(error instanceof Error ? error.message : "Invalid synonym JSON");
    }
  }
  function closeMenu(id: string) { document.getElementById(id)?.hidePopover(); }

  const tuned = [exact, options.mode === "any", options.prefix, options.typos, !!options.synonyms, options.inspect, options.match && options.match !== "text", options.profile === "baseline", grouped].filter(Boolean).length;
  const idle = !res && !busy && !err;
  const limit = options.limit ?? 10;
  const offset = options.offset ?? 0;

  return (
    <div className={`search${idle ? " is-idle" : ""}`}>
      <section className="search-head">
        {idle && (
          <h1 className="search-title">
            {documents ? <>Search <span className="num">{documents.toLocaleString()}</span> documents</> : documents === 0 ? "Nothing indexed yet" : "Search your documents"}
          </h1>
        )}
        <form className={`searchbox${busy ? " busy" : ""}`} role="search" onSubmit={(e) => { e.preventDefault(); if (suggestionIndex < 0) void run(); }}>
          <Icon name="search" size={18} />
          <input
            ref={inputRef}
            id="q"
            type="text"
            value={q}
            aria-label="Search documents"
            onChange={(e) => { ++compareGeneration.current; setCompare(null); setQ(e.target.value); setOptions((c) => ({ ...c, offset: 0 })); setSuggestionIndex(-1); }}
            onKeyDown={(e) => {
              if (e.key === "Escape") { hideSuggestions(); return; }
              if (e.key === "ArrowDown" && suggestions.length) { e.preventDefault(); setSuggestionIndex((n) => Math.min(n + 1, suggestions.length - 1)); return; }
              if (e.key === "ArrowUp" && suggestions.length) { e.preventDefault(); setSuggestionIndex((n) => Math.max(n - 1, -1)); return; }
              if (e.key === "Enter" && suggestionIndex >= 0) { e.preventDefault(); selectSuggestion(suggestions[suggestionIndex]!); }
            }}
            placeholder="Words, a filename, or a phrase"
            autoComplete="off"
            spellCheck={false}
            autoFocus
            onBlur={hideSuggestions}
            role="combobox"
            aria-expanded={suggestions.length > 0}
            aria-controls="search-suggestions"
            aria-activedescendant={suggestionIndex >= 0 ? `suggestion-${suggestionIndex}` : undefined}
          />
          {q ? <button type="button" className="icon-button ghost" aria-label="Clear query" onClick={() => { setQ(""); inputRef.current?.focus(); }}><Icon name="x" size={14} /></button> : <kbd aria-hidden>/</kbd>}
          <button type="button" className={`icon-button options-trigger${tuned ? " tuned" : ""}`} popoverTarget="search-options" aria-label={`Search options${tuned ? `, ${tuned} changed` : ""}`}>
            <Icon name="sliders" />{tuned > 0 && <span className="badge-dot">{tuned}</span>}
          </button>
          <button className="button solid search-go" disabled={busy || !q.trim()}>{busy ? "Searching" : "Search"}</button>
          <span className="scanline" aria-hidden />
          {suggestions.length > 0 && (
            <div id="search-suggestions" className="suggestions" role="listbox">
              {suggestions.map((item, i) => (
                <button type="button" id={`suggestion-${i}`} role="option" aria-selected={i === suggestionIndex} key={item} onMouseDown={(e) => e.preventDefault()} onClick={() => selectSuggestion(item)}>
                  <Icon name="search" size={14} />{item}
                </button>
              ))}
            </div>
          )}
        </form>

        <div id="search-options" popover="auto" className="menu options-panel" aria-label="Search options">
          <Segmented label="Match" value={options.match ?? "text"} options={[["text", "Words"], ["literal", "Literal"], ["substring", "Substring"]]} onChange={(v) => change("match", v)} />
          {options.match && options.match !== "text" && <p className="hint">{options.match === "literal" ? "Exact text, case sensitive." : "Partial text, any case."} Scope to 2,000 documents or fewer.</p>}
          <Segmented label="Require" value={options.mode ?? "all"} options={[["all", "All words"], ["any", "Any word"]]} onChange={(v) => change("mode", v)} />
          <div className="switch-list">
            <Switch label="Exact phrase" checked={exact} onChange={(next) => { setExact(next); void run(q, options, next); }} />
            <Switch label="Prefix matching" checked={!!options.prefix} onChange={(next) => change("prefix", next)} />
            <Switch label="Typo tolerance" checked={!!options.typos} onChange={(next) => change("typos", next)} />
            <Switch label="Synonyms" checked={!!options.synonyms} onChange={(next) => { setSynonymError(null); change("synonyms", next ? {} : undefined); }} />
          </div>
          {options.synonyms && (
            <div className="synonyms">
              <textarea aria-label="Synonyms as JSON" value={synonymDraft} onChange={(e) => setSynonymDraft(e.target.value)} placeholder={'{"car": ["automobile"]}'} rows={3} spellCheck={false} />
              <button type="button" className="button small" onClick={applySynonyms}>Apply</button>
              {synonymError && <p role="alert" className="field-error">{synonymError}</p>}
            </div>
          )}
          <Segmented label="Ranking" value={options.profile ?? "tuned"} options={[["tuned", "Fields & passages"], ["baseline", "BM25"]]} onChange={(v) => change("profile", v)} />
          <Segmented label="Group" value={options.groupBy ?? "none"} options={[["none", "None"], ["repo", "Repository"], ["source", "Source"]]} onChange={(v) => change("groupBy", v)} />
          <div className="switch-list">
            <Switch label="Query inspector" hint="Stage timings and reads" checked={!!options.inspect} onChange={(next) => change("inspect", next)} />
          </div>
        </div>

        {idle && options.docIds !== undefined && (
          <span className="chip active">
            <Icon name="layers" size={13} />Searching in {scope?.name ?? "selected documents"}
            <button type="button" className="chip-x" aria-label="Clear collection scope" onClick={() => setOptions({ ...options, docIds: undefined })}><Icon name="x" size={12} /></button>
          </span>
        )}
        {idle && (recent.length > 0 || saved.length > 0) && (
          <div className="shortcuts">
            {saved.map((s) => (
              <span className="chip saved" key={s.id}>
                <button type="button" onClick={() => restore(s)}><Icon name="bookmark" size={13} />{s.name}</button>
                <button type="button" className="chip-x" aria-label={`Delete saved search ${s.name}`} onClick={() => deleteSaved(s.id)}><Icon name="x" size={12} /></button>
              </span>
            ))}
            {recent.slice(0, 6).map((item) => (
              <button type="button" key={item.id} className="chip" onClick={() => restore(item)}>{item.query}</button>
            ))}
          </div>
        )}
        {idle && documents === 0 && <Link className="button primary" href={sourcesHref}><Icon name="plus" />Add a source</Link>}
      </section>

      {err && <p className="alert" role="alert">{err}</p>}

      {(res || busy) && (
        <div className="result-bar">
          <span className="result-count">
            {res ? <><b>{res.total.toLocaleString()}</b> {res.total === 1 ? "match" : "matches"} <span className="mono">{res.tookMs.toFixed(1)} ms</span></> : "Searching…"}
          </span>
          {options.docIds !== undefined && (
            <span className="chip active">
              <Icon name="layers" size={13} />{scope?.name ?? "Selected documents"}
              <button type="button" className="chip-x" aria-label="Clear collection scope" onClick={() => change("docIds", undefined)}><Icon name="x" size={12} /></button>
            </span>
          )}
          {res?.facets && (Object.keys(FACETS) as Array<keyof typeof FACETS>).map((key) => {
            const values = res.facets?.[key];
            const active = options[key];
            if (!values?.length && !active) return null;
            const id = `facet-${key}`;
            return (
              <span key={key} className="facet">
                <button type="button" className={`chip${active ? " active" : ""}`} popoverTarget={id}>
                  {active ? <>{FACETS[key]}: <b>{active}</b></> : FACETS[key]}<Icon name="chevron" size={13} />
                </button>
                <div id={id} popover="auto" className="menu facet-menu" aria-label={`Filter by ${FACETS[key].toLowerCase()}`}>
                  {active && <button type="button" className="menu-item" onClick={() => { closeMenu(id); change(key, undefined); }}><Icon name="x" /><span>Clear filter</span></button>}
                  {values?.map((f) => (
                    <button type="button" key={f.value} className="menu-item" aria-pressed={active === f.value} onClick={() => { closeMenu(id); change(key, active === f.value ? undefined : f.value); }}>
                      <span className="tick">{active === f.value && <Icon name="check" size={14} />}</span><span>{f.value}</span><span className="count">{f.count}</span>
                    </button>
                  ))}
                </div>
              </span>
            );
          })}
          {res && (
            <span className="result-tools">
              <button type="button" className="icon-button" popoverTarget="result-tools" aria-label="More actions"><Icon name="more" /></button>
              <div id="result-tools" popover="auto" className="menu" aria-label="More actions">
                <button type="button" className="menu-item" onClick={() => { closeMenu("result-tools"); setNameDraft(q.trim()); setNameError(null); setSaving(true); }}><Icon name="bookmark" /><span>Save search</span></button>
                <button type="button" className="menu-item" onClick={() => { closeMenu("result-tools"); void runCompare(); }}><Icon name="layers" /><span>Compare ranking<small>BM25 next to fields & passages</small></span></button>
                <button type="button" className="menu-item" onClick={() => { closeMenu("result-tools"); setMissingTarget(undefined); setMissingOpen(true); }}><Icon name="info" /><span>Why is a document missing?</span></button>
              </div>
            </span>
          )}
        </div>
      )}

      {saving && (
        <form className="inline-form" onSubmit={(e) => { e.preventDefault(); saveSearch(); }}>
          <input aria-label="Saved search name" autoFocus value={nameDraft} maxLength={256} onChange={(e) => setNameDraft(e.target.value)} aria-invalid={!!nameError} placeholder="Name this search" />
          <button className="button primary small">Save</button>
          <button type="button" className="button ghost small" onClick={() => setSaving(false)}>Cancel</button>
          {nameError && <p role="alert" className="field-error">{nameError}</p>}
        </form>
      )}
      {res?.inspector && <InspectorPanel inspector={res.inspector} />}
      {compare && <ComparePanel result={compare} offset={appliedOptions.offset ?? 0} onClose={() => setCompare(null)} />}
      {res && missingOpen && <MissingInspector key={res.query} query={res.query} options={appliedOptions} target={missingTarget} onClose={() => setMissingOpen(false)} />}

      <div className={`results${preview ? " has-preview" : ""}`}>
        <div className="results-main">
          {busy && !res && <div className="skeleton" aria-hidden>{[0, 1, 2].map((i) => <div key={i}><span /><span /><span /></div>)}</div>}
          {res && grouped && res.groups && (
            <div className="groups">
              {visibleGroups(res.groups, res.total).map((group) => (
                <GroupResults key={`${JSON.stringify([res.query, appliedOptions])}-${group.key}`} group={group} query={res.query} options={appliedOptions} onOpen={openPreview} onCollect={setCollectionTarget} />
              ))}
            </div>
          )}
          {res && res.hits.length === 0 && (
            <div className="empty">
              <h2>No matches for “{res.query}”</h2>
              <p>Try fewer words, turn on typo tolerance, or clear a filter.</p>
            </div>
          )}
          {res && !grouped && res.hits.length > 0 && (
            <ol className="hits" aria-label="Search results">
              {hits.map((hit, i) => (
                <HitRow key={hit.docId} index={i} hit={hit} rank={offset + i + 1} query={res.query} active={i === selected} onOpen={() => openPreview(hit)} onCollect={() => setCollectionTarget(hit.docId)} />
              ))}
            </ol>
          )}
          {res && !grouped && res.total > limit && (
            <Pager page={Math.floor(offset / limit) + 1} pages={Math.ceil(res.total / limit)} disabled={busy} onPrev={() => change("offset", Math.max(0, offset - limit))} onNext={() => change("offset", offset + limit)} />
          )}
          {res && res.hits.length > 0 && <p className="keys" aria-hidden>{grouped ? <><kbd>tab</kbd> move <kbd>enter</kbd> preview</> : <><kbd>j</kbd><kbd>k</kbd> move <kbd>enter</kbd> preview <kbd>esc</kbd> close</>}</p>}
        </div>
        {preview && res && (
          <Preview
            hit={preview}
            fullDoc={fullDoc}
            error={previewError}
            query={res.query}
            onClose={closePreview}
            onCollect={() => setCollectionTarget(preview.docId)}
          />
        )}
      </div>

      {collectionTarget && (
        <div className="sheet" role="dialog" aria-label="Add to collection">
          <div className="sheet-head"><h2>Add to collection</h2><button type="button" className="icon-button ghost" aria-label="Close" onClick={() => setCollectionTarget(null)}><Icon name="x" /></button></div>
          {collections.length > 0 && (
            <div className="sheet-list">
              {collections.map((c) => {
                const has = c.docIds.includes(collectionTarget);
                return (
                  <button type="button" key={c.id} className="menu-item" disabled={has} onClick={() => addToCollection(c.id)}>
                    <Icon name={has ? "check" : "layers"} /><span>{c.name}</span><span className="count">{c.docIds.length}</span>
                  </button>
                );
              })}
            </div>
          )}
          <form className="inline-form" onSubmit={(e) => { e.preventDefault(); createCollection(); }}>
            <input aria-label="New collection name" value={nameDraft} maxLength={256} onChange={(e) => setNameDraft(e.target.value)} placeholder="New collection" autoFocus={!collections.length} />
            <button className="button small" disabled={!nameDraft.trim()}><Icon name="plus" size={14} />Create</button>
            {nameError && <p role="alert" className="field-error">{nameError}</p>}
          </form>
          <p className="hint">Stored in this browser.</p>
        </div>
      )}
      {notice && <Toast key={notice.n} message={notice.text} />}
    </div>
  );
}

function Pager({ page, pages, disabled, onPrev, onNext }: { page: number; pages: number; disabled: boolean; onPrev: () => void; onNext: () => void }) {
  return (
    <nav className="pager" aria-label="Pages">
      <button type="button" className="button ghost small" disabled={disabled || page <= 1} onClick={onPrev}><Icon name="back" size={14} />Previous</button>
      <span className="mono">{page} / {pages}</span>
      <button type="button" className="button ghost small" disabled={disabled || page >= pages} onClick={onNext}>Next<Icon name="arrow" size={14} /></button>
    </nav>
  );
}

function GroupResults({ group, query, options, onOpen, onCollect }: { group: SearchGroup; query: string; options: SearchOptions; onOpen: (hit: SearchHit) => void; onCollect: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  const [offset, setOffset] = useState(0);
  const [result, setResult] = useState<SearchResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const limit = options.limit ?? 10;
  useEffect(() => {
    if (!open) return;
    let cancelled = false;
    setBusy(true);
    setError(null);
    setResult(null);
    const field = options.groupBy === "repo" ? "repo" : "source";
    async function fetchGroup() {
      if (group.key) return search(query, { ...options, [field]: group.key, groupBy: "none", offset, limit });
      const matches: SearchHit[] = [];
      let scanned = 0;
      let response: SearchResponse;
      do {
        response = await search(query, { ...options, groupBy: "none", offset: scanned, limit: 100 });
        if (cancelled) return response;
        matches.push(...response.hits.filter((hit) => String(hit.doc[field] ?? "") === ""));
        scanned += response.hits.length;
      } while (matches.length < offset + limit && scanned < response.total && response.hits.length > 0);
      return { ...response, total: group.count, hits: matches.slice(offset, offset + limit) };
    }
    fetchGroup()
      .then((response) => { if (!cancelled) setResult(response); })
      .catch((e) => { if (!cancelled) setError(e instanceof Error ? e.message : "Could not load group"); })
      .finally(() => { if (!cancelled) setBusy(false); });
    return () => { cancelled = true; };
  }, [open, offset, query, options, group.key, limit]);
  return (
    <details className="group" onToggle={(e) => setOpen(e.currentTarget.open)}>
      <summary><Icon name="chevron" size={14} /><span>{group.key || "Unassigned"}</span><span className="count">{group.count}</span></summary>
      {open && (
        <div className="group-body">
          {busy && <Spinner label="Loading group" />}
          {error && <p role="alert" className="alert">{error}</p>}
          <ol className="hits">
            {result?.hits.map((hit, i) => <HitRow key={hit.docId} index={i} hit={hit} rank={offset + i + 1} query={query} active={false} onOpen={() => onOpen(hit)} onCollect={() => onCollect(hit.docId)} />)}
          </ol>
          {result && result.total === 0 && <p className="hint">No matches in this group.</p>}
          {group.count > limit && <Pager page={Math.floor(offset / limit) + 1} pages={Math.ceil(group.count / limit)} disabled={busy} onPrev={() => setOffset(Math.max(0, offset - limit))} onNext={() => setOffset(offset + limit)} />}
        </div>
      )}
    </details>
  );
}

function Spinner({ label }: { label: string }) {
  return <p className="spinner" role="status"><span aria-hidden />{label}</p>;
}

function Highlighted({ passage }: { passage: SearchSnippet }) {
  const out: React.ReactNode[] = [];
  let last = 0;
  passageMarks(passage).forEach((mark, i) => {
    if (mark.start > last) out.push(passage.text.slice(last, mark.start));
    out.push(<mark key={i} data-match-start={mark.start + passage.start}>{passage.text.slice(mark.start, mark.end)}</mark>);
    last = mark.end;
  });
  out.push(passage.text.slice(last));
  return <>{out}</>;
}

function where(passage: SearchSnippet) {
  return passage.page ? `p. ${passage.page}` : passage.line ? `line ${passage.line}` : passage.field;
}

function HitRow({ hit, index, rank, query, active, onOpen, onCollect }: { hit: SearchHit; index: number; rank: number; query: string; active: boolean; onOpen: () => void; onCollect: () => void }) {
  const { title, badge } = describe(hit.doc);
  const passages = distinctPassages(hit.snippet, hit.passages);
  const [first, ...rest] = passages;
  return (
    <li className={`hit${active ? " active" : ""}`} style={{ "--i": index } as React.CSSProperties}>
      <span className="hit-rank mono" aria-hidden>{rank}</span>
      <button type="button" className="hit-open" onClick={onOpen}>
        <span className="hit-title"><span className="tag">{badge}</span>{title}</span>
        <span className="hit-snippet">{first ? <><Highlighted passage={first} />{(first.page || first.line) && <span className="where">{where(first)}</span>}</> : snippet(hit.doc)}</span>
      </button>
      {rest.length > 0 && (
        <ul className="hit-more">
          {rest.map((p) => (
            <li key={`${p.field}-${p.start}`}>
              <Link href={documentMatchHref(hit.docId, query, p)}><span className="where">{where(p)}</span><span className="hit-snippet"><Highlighted passage={p} /></span></Link>
            </li>
          ))}
        </ul>
      )}
      <div className="hit-actions">
        <Link className="text-button" href={documentMatchHref(hit.docId, query, first)}><Icon name="external" size={14} />Open</Link>
        <button type="button" className="text-button" onClick={onCollect}><Icon name="plus" size={14} />Collect</button>
        <details className="score">
          <summary className="text-button mono">score {hit.score.toFixed(2)}</summary>
          <table>
            <thead><tr><th>term</th><th>tf</th><th>idf</th><th>contribution</th></tr></thead>
            <tbody>{hit.breakdown.map((b) => <tr key={b.term}><td>{b.term}</td><td>{b.termFrequency}</td><td>{b.idf.toFixed(3)}</td><td>{b.contribution.toFixed(4)}</td></tr>)}</tbody>
          </table>
        </details>
      </div>
    </li>
  );
}

function Preview({ onCollect, hit, fullDoc, error, query, onClose }: { onCollect: () => void; hit: SearchHit; fullDoc: Record<string, unknown> | null; error: string | null; query: string; onClose: () => void }) {
  const { title, badge } = describe(hit.doc);
  const first = hit.snippet ?? hit.passages?.[0];
  const text = fullDoc && first ? originalFieldText(fullDoc, first.field) : snippet(fullDoc ?? hit.doc, 700);
  const fullTextRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const at = first?.matches[0]?.start;
    if (at !== undefined) fullTextRef.current?.querySelector(`[data-match-start="${at}"]`)?.scrollIntoView({ block: "center" });
  }, [fullDoc, hit.docId]);
  const matches = (hit.passages ?? (first ? [first] : [])).filter((p) => p.field === first?.field).flatMap((p) => p.matches);
  const fullPassage = { text, field: first?.field ?? "content", start: 0, end: text.length, matches };
  return (
    <aside className="preview" aria-label="Document preview" key={hit.docId}>
      <div className="preview-head">
        <span className="tag">{badge}</span>
        <button type="button" className="icon-button ghost" aria-label="Close preview" onClick={onClose}><Icon name="x" /></button>
      </div>
      <h2>{title}</h2>
      <div className="preview-actions">
        <Link className="button primary small" href={documentMatchHref(hit.docId, query, first)}>Open at match<Icon name="arrow" size={14} /></Link>
        <button type="button" className="button ghost small" onClick={onCollect}><Icon name="plus" size={14} />Add to collection</button>
      </div>
      {error && <p className="alert" role="alert">{error}</p>}
      <div ref={fullTextRef} className="preview-text" tabIndex={0} aria-label="Full document text">
        {fullDoc ? <Highlighted passage={fullPassage} /> : error ? "Full document unavailable." : <Spinner label="Loading document" />}
      </div>
      {fullDoc && <details className="disclosure"><summary><Icon name="chevron" size={14} />All fields</summary><pre className="code">{JSON.stringify(fullDoc, null, 2)}</pre></details>}
    </aside>
  );
}

function InspectorPanel({ inspector }: { inspector: NonNullable<SearchResponse["inspector"]> }) {
  const stats: Array<[string, string]> = [
    ...Object.entries(inspector.stageMs).map(([name, ms]): [string, string] => [name, `${ms.toFixed(2)} ms`]),
    ["candidates", String(inspector.candidateCount)],
    ["posting reads", String(inspector.postingReads)],
    ["document reads", String(inspector.documentReads)],
    ...(inspector.cacheHits !== undefined ? [["cache hits", String(inspector.cacheHits)] as [string, string]] : []),
  ];
  return (
    <details className="panel inspector" open>
      <summary><Icon name="chevron" size={14} />Query inspector <span className="mono">{inspector.parsedQuery.join(" · ") || "filters only"}</span></summary>
      <dl className="stats">{stats.map(([k, v]) => <div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>
      {inspector.documentSource && <p className="hint">Documents read from {inspector.documentSource}.</p>}
      <details className="disclosure"><summary><Icon name="chevron" size={14} />Raw query data</summary><pre className="code">{JSON.stringify({ expansions: inspector.expansions, scoreBreakdown: inspector.scoreBreakdown }, null, 2)}</pre></details>
    </details>
  );
}

function ComparePanel({ result, offset, onClose }: { offset: number; result: { baseline: SearchResponse; tuned: SearchResponse }; onClose: () => void }) {
  const base = result.baseline.hits;
  const tuned = result.tuned.hits;
  return (
    <section className="panel compare" aria-label="Ranking comparison">
      <div className="panel-head"><h2>Ranking comparison</h2><button type="button" className="icon-button ghost" aria-label="Close comparison" onClick={onClose}><Icon name="x" /></button></div>
      <div className="compare-cols">
        {(["baseline", "tuned"] as const).map((profile) => (
          <div key={profile}>
            <h3>{profile === "baseline" ? "BM25" : "Fields & passages"} <span className="mono">{result[profile].tookMs.toFixed(2)} ms</span></h3>
            <ol>
              {result[profile].hits.map((hit, i) => {
                const other = (profile === "tuned" ? base : tuned).findIndex((h) => h.docId === hit.docId);
                const delta = other < 0 ? null : other - i;
                return (
                  <li key={hit.docId}>
                    <span className="mono rank">{offset + i + 1}</span>
                    <Link href={documentMatchHref(hit.docId, result[profile].query, hit.snippet)}>{describe(hit.doc).title}</Link>
                    <span className={`mono delta${delta === null ? " out" : delta > 0 ? " up" : delta < 0 ? " down" : ""}`} title={hit.breakdown.map((b) => `${b.term}: ${b.contribution.toFixed(3)}`).join(" · ")}>
                      {delta === null ? "new" : delta === 0 ? "=" : delta > 0 ? `+${delta}` : delta}
                    </span>
                  </li>
                );
              })}
            </ol>
          </div>
        ))}
      </div>
      <p className="hint">Ranks are within this page. The change column shows how far each document moves against the other profile.</p>
    </section>
  );
}
